/* Static content data for Waqt24 (Du'a, Hadees, Ilm names/words/myths, quiz bank). Loaded before the main script in index.html. */
const DUAS = [
  {cat:'Roz Marra', title:'Sone ki Dua', arabic:'اَللّٰھُمَّ بِاسْمِکَ أَمُوتُ وَأَحْیَا', translit:"Allahumma bismika amutu wa ahya.", meaning:'Aye Allah! Main Tere hi naam par marta (sota) hoon aur zinda hota (jagta) hoon.', ref:'Sahih Bukhari', ent:"Dua Before Sleeping", enm:"In Your name, O Allah, I die and I live."},
  {cat:'Roz Marra', title:'Jagne ki Dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِی أَحْیَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَیْهِ النُّشُورُ', translit:'Alhamdu lillahil-lazi ahyana ba\'da ma amatana wa ilaihin-nushur', meaning:'Sab tareef Allah ke liye hai jisne humein maut ke baad zinda kiya, aur usi ki taraf lautna hai.', ref:'Sahih Bukhari', ent:"Dua on Waking Up", enm:"All praise is for Allah, who gave us life after causing us to die, and to Him is the resurrection."},
  {cat:'Khana', title:'Khana Shuru Karne ki Dua', arabic:'بِسْمِ اللَّهِ وَعَلَیٰ بَرَکَةِ اللَّهِ', translit:'Bismillahi wa ala barakatillah.', meaning:'Allah ke naam se aur Allah ki barkat par (main khana shuru karta hoon).', ref:'Sahih Bukhari', ent:"Dua Before Eating", enm:"In the name of Allah, and with the blessings of Allah, I begin my meal."},
  {cat:'Khana', title:'Khane ka hisaab se bachne ki dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِی أَطْعَمَنِی هَذَا وَرَزَقَنِیهِ مِنْ غَیْرِ حَوْلٍ مِنِّی وَلَا قُوَّةٍ', translit:'Alhamdulillahillazi at\'amani haza wa razaqnihi min ghairi haulin minni wa la quwwatin.', meaning:'Tamam taarifain us Allah ke liye hain jisne mujhe yeh khana khilaya aur meri taqat ya qudrat na hone ke bawajood mujhe yeh ata farmaya.', ref:'Abu Dawood, Tirmidhi, Ibn Majah', info:'Hadees: Hazrat Mu\'adh bin Anas (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs khana khaye aur phir yeh dua padhe, uske pichle aur aainda ke gunah bakhsh diye jayenge. Yeh dua khane ki niamat par shukr ka izhaar hai, aur iss baat ka iqrar ki rizq Allah ki taraf se hai, apni taqat ya qudrat se nahi.', ent:"Dua After Eating", enm:"All praise is for Allah, who fed me this food and provided it to me without any might or power from me.", eninfo:"Hadith: Mu'adh bin Anas (RA) narrated that the Prophet ﷺ said: whoever eats food and then says this dua, his past and future sins will be forgiven. It is an expression of gratitude for the blessing of food, and an acknowledgement that provision comes from Allah, not from one's own strength."},
  {cat:'Safar', title:'Safar ki Dua', arabic:'سُبْحَانَ الَّذِی سَخَّرَ لَنَا هَذَا وَمَا کُنَّا لَهُ مُقْرِنِینَ', translit:'Subhanal-lazi sakhkhara lana haza wa ma kunna lahu muqrinin', meaning:'Pak hai woh Zaat jisne is sawari ko humare kaabu mein diya.', ref:'Sahih Muslim', ent:"Travel Dua", enm:"Glory be to the One who subjected this to us; we could never have controlled it by ourselves."},
  {cat:'Masjid', title:'Masjid Mein Dakhil Hone ki Dua', arabic:'اللَّهُمَّ افْتَحْ لِی أَبْوَابَ رَحْمَتِکَ', translit:'Allahummaf-tah li abwaba rahmatik', meaning:'Ae Allah, mere liye apni rehmat ke darwaze khol de.', ref:'Sahih Muslim', ent:"Dua Entering the Masjid", enm:"O Allah, open for me the doors of Your mercy."},
  {cat:'Masjid', title:'Masjid Se Nikalne ki Dua', arabic:'اللَّهُمَّ إِنِّی أَسْأَلُکَ مِنْ فَضْلِکَ', translit:'Allahumma inni as\'aluka min fadlik', meaning:'Ae Allah, main aapse aapke fazl ka sawal karta hoon.', ref:'Sahih Muslim', ent:"Dua Leaving the Masjid", enm:"O Allah, I ask You for Your bounty."},
  {cat:'Pareshani', title:'Pareshani Ke Waqt ki Dua', arabic:'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَکِیلُ', translit:"Hasbunallahu wa ni'mal wakil", meaning:'Allah humare liye kaafi hai aur woh behtareen kaarsaaz hai.', ref:'Qur’an 3:173', ent:"Dua in Hardship", enm:"Allah is sufficient for us, and He is the best disposer of affairs."},
  {cat:'Ghar', title:'Ghar Mein Dakhil Hone ki Dua', arabic:'بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَی رَبِّنَا تَوَکَّلْنَا', translit:"Bismillahi walajna wa bismillahi kharajna wa 'ala rabbina tawakkalna", meaning:'Allah ke naam se hum andar aaye aur Allah ke naam se nikle, aur apne Rab par bharosa kiya.', ref:'Abu Dawood', ent:"Dua Entering the Home", enm:"In the name of Allah we entered, and in the name of Allah we left, and upon our Lord we rely."},
  {cat:'Ramzan', title:'Iftar karne ki dua', arabic:'ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', translit:"Zahabaz-zama'u wabtallatil-'uruqu wa thabatal-ajru in sha Allah", meaning:'Pyaas chali gayi, rag-tarein tar ho gayi, aur agar Allah ne chaha to ajar sabit ho gaya.', ref:'Abu Dawood', ent:"Dua for Breaking the Fast", enm:"The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills."},
  {cat:'Rabbana', title:"Qabooliyat Ki Dua", arabic:"رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّکَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ", translit:"Rabbana taqabbal minna innaka antas Sami'ul 'Aleem", meaning:"Ae hamare Rab, hamari taraf se (yeh amal) qabool farma. Beshak Tu hi sunne wala aur jaanne wala hai.", ref:"Qur’an 2:127", tags:["Quranic", "Rabbana", "Qabooliyat"], ent:"Dua for Acceptance", enm:"Our Lord, accept this from us. Indeed You are the All-Hearing, the All-Knowing."},
  {cat:'Rabbana', title:"Islam Par Qaim Rehne Ki Dua", arabic:"رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَیۡنِ لَکَ وَمِن ذُرِّیَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّکَ وَأَرِنَا مَنَاسِکَنَا وَتُبۡ عَلَیۡنَآۖ إِنَّکَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِیمُ", translit:"Rabbana waj'alna muslimaini laka wa min zurriyyatina ummatam muslimatal laka wa arina manasikana wa tub 'alayna innaka antat Tawwabur Raheem", meaning:"Ae hamare Rab, humein apna farmabardar bana aur hamari aulad mein se bhi apni farmabardar ummat paida kar. Humein hamare ibadat ke tareeqe dikha aur hamari tauba qabool kar. Beshak Tu tauba qabool karne wala, meherbaan hai.", ref:"Qur’an 2:128", tags:["Quranic", "Rabbana", "Islam"], ent:"Dua to Remain Upon Islam", enm:"Our Lord, make us Muslims, submitting to You, and from our descendants a Muslim nation submitting to You. Show us our rites and accept our repentance. Indeed, You are the Accepting of Repentance, the Merciful."},
  {cat:'Rabbana', title:"Duniya Aur Aakhirat Ki Bhalai", arabic:"رَبَّنَآ ءَاتِنَا فِی ٱلدُّنۡیَا حَسَنَةٗ وَفِی ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana atina fid dunya hasanatanw wa fil akhirati hasanatanw wa qina 'adhaban Nar", meaning:"Ae hamare Rab, humein duniya mein bhalai de aur aakhirat mein bhi bhalai de, aur humein aag ke azaab se bacha le.", ref:"Qur’an 2:201", tags:["Quranic", "Rabbana", "Duniya Aur Aakhirat"], ent:"Good in This World and the Next", enm:"Our Lord, give us good in this world and good in the Hereafter, and save us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Sabr Aur Sabit Qadmi Ki Dua", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَیۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana afrigh 'alayna sabranw wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par sabr undel de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 2:250", tags:["Quranic", "Rabbana", "Sabr"], ent:"Dua for Patience and Victory", enm:"Our Lord, pour upon us patience, plant our feet firmly, and give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Bhool Chook Ki Maafi", arabic:"رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِینَآ أَوۡ أَخۡطَأۡنَاۚ", translit:"Rabbana la tu'akhidhna in nasina aw akhta'na", meaning:"Ae hamare Rab, agar hum bhool jayein ya ghalti kar baithein to hamari pakad na kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Tauba"], ent:"Forgiveness for Forgetting and Mistakes", enm:"Our Lord, do not hold us accountable if we forget or make mistakes."},
  {cat:'Rabbana', title:"Bhari Bojh Se Hifazat", arabic:"رَبَّنَا وَلَا تَحۡمِلۡ عَلَیۡنَآ إِصۡرٗا کَمَا حَمَلۡتَهُۥ عَلَی ٱلَّذِینَ مِن قَبۡلِنَاۚ", translit:"Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina", meaning:"Ae hamare Rab, hum par woh bojh na daal jo Tu ne hum se pehle logon par daala tha.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Protection from Heavy Burdens", enm:"Our Lord, lay not upon us a burden like that which You laid upon those before us."},
  {cat:'Rabbana', title:"Taqat Se Zyada Imtihan Na Ho", arabic:"رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَیٰنَا فَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par utna bojh na daal jitni humein taqat na ho. Humein maaf kar, bakhsh de aur hum par reham kar. Tu hi hamara Maula (kaarsaaz) hai, to kafir qaum par hamari madad kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Dua Not to Be Tested Beyond Our Strength", enm:"Our Lord, burden us not with what we have no ability to bear. Pardon us, forgive us and have mercy on us. You are our Protector, so give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Dil Ko Haq Par Qaim Rakh", arabic:"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَیۡتَنَا وَهَبۡ لَنَا مِن لَّدُنکَ رَحۡمَةًۚ إِنَّکَ أَنتَ ٱلۡوَهَّابُ", translit:"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal Wahhab", meaning:"Ae hamare Rab, hidayat dene ke baad hamare dilon ko seedhe raste se mat phera, aur apni taraf se hum par rehmat farma. Beshak Tu hi bahut ata karne wala hai.", ref:"Qur’an 3:8", tags:["Quranic", "Rabbana", "Hidayat"], ent:"Keep Our Hearts on the Truth", enm:"Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. Indeed, You are the Bestower."},
  {cat:'Rabbana', title:"Qiyamat Par Yaqeen Ki Dua", arabic:"رَبَّنَآ إِنَّکَ جَامِعُ ٱلنَّاسِ لِیَوْمٍ لَّا رَیْبَ فِیهِ ۚ إِنَّ ٱللَّهَ لَا یُخْلِفُ ٱلْمِیعَادَ", translit:"Rabbana innaka jami'un-nasi liyawmil la raiba fih, innal laha la yukhliful mi'ad", meaning:"Ae hamare Rab, beshak Tu hi tamam logon ko us din ke liye jama karega jis mein koi shak nahi. Beshak Allah apna wada khilaf nahi karta.", ref:"Qur’an 3:9", tags:["Quranic", "Rabbana", "Qiyamat"], ent:"Faith in the Day of Judgment", enm:"Our Lord, indeed You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."},
  {cat:'Rabbana', title:"Iman Aur Gunahon Ki Maafi", arabic:"رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban Nar", meaning:"Ae hamare Rab, hum emaan le aaye hain, to hamare gunah bakhsh de aur hamein aag ke azaab se bacha le.", ref:"Qur’an 3:16", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Forgiveness of Sins for Believers", enm:"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Gawahi Mein Shamil Hone Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱکۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ", translit:"Rabbana amanna bima anzalta wattaba'nar Rasula faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan laaye us par jo Tu ne nazil kiya aur Rasool ki pairwi ki, to hamein gawahon ke saath likh le.", ref:"Qur’an 3:53", tags:["Quranic", "Rabbana", "Iman"], ent:"Dua to Be Among the Witnesses", enm:"Our Lord, we have believed in what You revealed and followed the Messenger, so register us among the witnesses."},
  {cat:'Rabbana', title:"Gunah Aur Hadd Se Barhi Zyadati Ki Maafi", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِیٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana ghfir lana dhunubana wa israfana fi amrina wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hamare gunah aur hamare kaamon mein hui hadd se barhi zyadatiyan bakhsh de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 3:147", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Forgiveness of Sins and Excesses", enm:"Our Lord, forgive us our sins and the excesses in our affairs, plant our feet firmly, and give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Kainat Ki Hikmat Aur Jahannam Se Panah", arabic:"رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَکَ فَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana ma khalqta hadha batila, subhanaka faqina 'adhaban Nar", meaning:"Ae hamare Rab, Tu ne yeh sab kuch bekaar paida nahi kiya. Tu paak hai, to hamein aag ke azaab se bacha le.", ref:"Qur’an 3:191", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Wisdom of Creation and Protection from Hell", enm:"Our Lord, You did not create this aimlessly. Exalted are You; protect us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Ruswai Se Panah Ki Dua", arabic:"رَبَّنَآ إِنَّکَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَیۡتَهُۥۖ وَمَا لِلظَّٰلِمِینَ مِنۡ أَنصَارٖ", translit:"Rabbana innaka man tudkhilin Nara faqad akhzaytah, wa ma lizzalimina min ansar", meaning:"Ae hamare Rab, beshak jisko Tu aag mein daakhil kare, usay Tu ne rusva kar diya. Zalimon ke liye koi madadgar nahi.", ref:"Qur’an 3:192", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Protection from Disgrace", enm:"Our Lord, indeed whoever You admit to the Fire, You have disgraced him, and for the wrongdoers there are no helpers."},
  {cat:'Rabbana', title:"Pukarne Wale Ki Pukaar Par Iman", arabic:"رَبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِیٗا یُنَادِی لِلۡإِیمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّکُمۡ فَـَٔامَنَّاۚ", translit:"Rabbana innana sami'na munadiyany yunadi lil iymani an aminu bi rabbikum fa amanna", meaning:"Ae hamare Rab, hum ne ek pukarne wale ko suna jo iman ki taraf bula raha tha ki apne Rab par emaan lao, to hum emaan le aaye.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Iman"], ent:"Faith in the Caller's Call", enm:"Our Lord, indeed we heard a caller calling to faith, saying, 'Believe in your Lord,' and we believed."},
  {cat:'Rabbana', title:"Gunahon Ki Safai Aur Nek Logon Ke Saath Maut", arabic:"رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَکَفِّرۡ عَنَّا سَیِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ", translit:"Rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al abrar", meaning:"Ae hamare Rab, hamare gunah bakhsh de, hamari burayiyan mita de aur hamein nek logon ke saath maut de.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Nek Log"], ent:"Cleansing of Sins and a Righteous End", enm:"Our Lord, forgive us our sins, remove from us our misdeeds, and cause us to die with the righteous."},
  {cat:'Rabbana', title:"Wade Ki Pooran Ki Dua, Qiyamat Ki Ruswai Se Bachao", arabic:"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَیٰ رُسُلِکَ وَلَا تُخۡزِنَا یَوۡمَ ٱلۡقِیَٰمَةِۗ إِنَّکَ لَا تُخۡلِفُ ٱلۡمِیعَادَ", translit:"Rabbana wa atina ma wa'attana 'ala rusulika wa la tukhzina yawmal qiyamah, innaka la tukhlifu al-mi'ad", meaning:"Ae hamare Rab, jo wada Tu ne apne Rasoolon ke zariye kiya hai woh hamein ata kar aur qiyamat ke din hamein ruswa na kar. Beshak Tu wade ke khilaf nahi karta.", ref:"Qur’an 3:194", tags:["Quranic", "Rabbana", "Qiyamat"], ent:"Protection from Disgrace on the Day of Judgment", enm:"Our Lord, grant us what You promised through Your messengers, and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in Your promise."},
  {cat:'Rabbana', title:"Gawahi Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱکۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ", translit:"Rabbana amanna faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan le aaye, to hamein gawahon mein likh le.", ref:"Qur’an 5:83", tags:["Quranic", "Rabbana", "Iman"], ent:"Dua to Be Among the Witnesses", enm:"Our Lord, we have believed, so register us among the witnesses."},
  {cat:'Rabbana', title:"Rizq Ki Dua (Dastarkhwan)", arabic:"رَبَّنَآ أَنزِلۡ عَلَیۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَکُونُ لَنَا عِیدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَایَةٗ مِّنکَۖ وَٱرۡزُقۡنَا وَأَنتَ خَیۡرُ ٱلرَّٰزِقِینَ", translit:"Rabbana anzil 'alayna ma'idatam minas sama'i takunu lana 'idal li awwalina wa akhirina wa ayatan minka warzuqna wa anta khayrur raziqin", meaning:"Ae hamare Rab, hum par aasmaan se khaane ka dastarkhwan utaar, jo hamare liye, hamare pehlon aur baad waalon ke liye eid ho aur Teri taraf se ek nishani ho. Hamein rizq de, Tu behtareen rizq dene wala hai.", ref:"Qur’an 5:114", tags:["Quranic", "Rabbana", "Rizq"], ent:"Dua for Provision", enm:"Our Lord, send down to us a table spread from the heaven, to be a festival for the first and last of us and a sign from You. Provide for us, and You are the best of providers."},
  {cat:'Rabbana', title:"Apne Nafs Par Zulm Ka Iqrar", arabic:"رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَکُونَنَّ مِنَ ٱلۡخَٰسِرِینَ", translit:"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal khasirin", meaning:"Ae hamare Rab, hum ne apni jaanon par zulm kiya. Agar Tu hamein maaf na kare aur hum par reham na kare to hum yaqeenan nuqsan uthane walon mein se honge.", ref:"Qur’an 7:23", tags:["Quranic", "Rabbana", "Tauba"], ent:"Admitting Our Wrongs (Dua of Adam AS)", enm:"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be among the losers."},
  {cat:'Rabbana', title:"Zalim Logon Ki Sohbat Se Panah", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ", translit:"Rabbana la taj'alna ma'al qawmiz zalimin", meaning:"Ae hamare Rab, hamein zalim logon ke saath shumar na kar.", ref:"Qur’an 7:47", tags:["Quranic", "Rabbana", "Sohbat"], ent:"Protection from the Company of Wrongdoers", enm:"Our Lord, do not place us among the wrongdoing people."},
  {cat:'Rabbana', title:"Haq Ke Saath Faisla", arabic:"رَبَّنَا ٱفۡتَحۡ بَیۡنَنَا وَبَیۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَیۡرُ ٱلۡفَٰتِحِینَ", translit:"Rabbana iftah bayna wa bayna qawmina bil haqqi wa anta khayrul fatihin", meaning:"Ae hamare Rab, hamare aur hamari qaum ke darmiyan haq ke saath faisla kar de, aur Tu behtareen faisla karne wala hai. (Hazrat Shuaib AS ki dua)", ref:"Qur’an 7:89", tags:["Quranic", "Rabbana", "Haq"], ent:"Judgment in Truth (Dua of Shuaib AS)", enm:"Our Lord, decide between us and our people in truth, and You are the best of those who decide."},
  {cat:'Rabbana', title:"Sabr Aur Iman Par Maut", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَیۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِینَ", translit:"Rabbana afrigh 'alayna sabranw wa tawaffana muslimin", meaning:"Ae hamare Rab, hum par sabr undel de aur hamein musalman hone ki haalat mein maut de. (Hazrat Musa AS ki dua)", ref:"Qur’an 7:126", tags:["Quranic", "Rabbana", "Sabr"], ent:"Patience and a Muslim End (Dua of Musa AS)", enm:"Our Lord, pour upon us patience and let us die as Muslims."},
  {cat:'Rabbana', title:"Zalim Qaum Ke Fitne Se Nijaat", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ وَنَجِّنَا بِرَحۡمَتِکَ مِنَ ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana la taj'alna fitnatal lil qawmiz zalimin, wa najjina bi rahmatika minal qawmil kafirin", meaning:"Ae hamare Rab, hamein zalim qaum ke liye fitna na bana, aur apni rehmat se hamein kafir qaum se nijaat de.", ref:"Qur’an 10:85-86", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Rescue from an Unjust People", enm:"Our Lord, make us not a trial for the wrongdoing people, and save us by Your mercy from the disbelieving people."},
  {cat:'Rabbana', title:"Allah Se Kuch Chhupa Nahi", arabic:"رَبَّنَآ إِنَّکَ تَعۡلَمُ مَا نُخۡفِی وَمَا نُعۡلِنُۗ وَمَا یَخۡفَیٰ عَلَی ٱللَّهِ مِن شَیۡءٖ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَآءِ", translit:"Rabbana innaka ta'lamu ma nukhfi wa ma nu'lin, wa ma yakhfa 'alal lahi min shay'in fil ardi wa la fis sama'", meaning:"Ae hamare Rab, beshak Tu jaanta hai jo hum chhupate hain aur jo zahir karte hain. Zameen aur aasmaan mein koi cheez Allah se chhupi nahi.", ref:"Qur’an 14:38", tags:["Quranic", "Rabbana", "Ilm-e-Ilahi"], ent:"Nothing Is Hidden from Allah", enm:"Our Lord, You know what we conceal and what we declare, and nothing is hidden from Allah on earth or in heaven."},
  {cat:'Rabbana', title:"Namaz Qaim Karne Ki Dua (Hazrat Ibrahim AS)", arabic:"رَبِّ ٱجۡعَلۡنِی مُقِیمَ ٱلصَّلَوٰةِ وَمِن ذُرِّیَّتِیۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ", translit:"Rabbij 'alni muqimas salati wa min dhurriyyati, Rabbana wa taqabbal du'a", meaning:"Ae mere Rab, mujhe namaz qaim karne wala bana, aur meri aulad mein se bhi. Ae hamare Rab, meri dua qabool kar.", ref:"Qur’an 14:40", tags:["Quranic", "Rabbana", "Namaz"], ent:"Dua to Establish Prayer (Ibrahim AS)", enm:"My Lord, make me one who establishes prayer, and some of my descendants. Our Lord, accept my supplication."},
  {cat:'Rabbana', title:"Maghfirat Walidain Aur Momineen Ke Liye", arabic:"رَبَّنَا ٱغۡفِرۡ لِی وَلِوَٰلِدَیَّ وَلِلۡمُؤۡمِنِینَ یَوۡمَ یَقُومُ ٱلۡحِسَابُ", translit:"Rabbanagh-fir li wa li walidayya wa lil mu'minina yawma yaqumul hisab", meaning:"Ae hamare Rab, mujhe, mere walidain aur tamam momin logon ko us din bakhsh de jis din hisaab qaim hoga.", ref:"Qur’an 14:41", tags:["Quranic", "Rabbana", "Walidain"], ent:"Forgiveness for Parents and Believers", enm:"Our Lord, forgive me, my parents, and the believers on the Day the account is established."},
  {cat:'Rabbana', title:"Rehmat Aur Hidayat Ki Dua (Ashab-e-Kahf)", arabic:"رَبَّنَآ ءَاتِنَا مِن لَّدُنکَ رَحۡمَةٗ وَهَیِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا", translit:"Rabbana atina min ladunka rahmatan wa hayyi' lana min amrina rashada", meaning:"Ae hamare Rab, hamein apni taraf se rehmat ata kar aur hamare kaam mein hamein seedha raasta (hidayat) de. (Ashab-e-Kahf ki dua)", ref:"Qur’an 18:10", tags:["Quranic", "Rabbana", "Hidayat"], ent:"Mercy and Guidance (People of the Cave)", enm:"Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair."},
  {cat:'Rabbana', title:"Zulm Aur Sarkashi Ka Khauf", arabic:"رَبَّنَآ إِنَّنَا نَخَافُ أَن یَفۡرُطَ عَلَیۡنَآ أَوۡ أَن یَطۡغَیٰ", translit:"Rabbana innana nakhafu an yafruta 'alayna aw an yatgha", meaning:"Ae hamare Rab, hamein darr hai ki woh hum par jaldi saza na kar de ya sarkashi na kare. (Hazrat Harun aur Musa AS ki dua)", ref:"Qur’an 20:45", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Fear of Oppression and Transgression", enm:"Our Lord, we fear that He may hasten punishment against us, or that he may transgress."},
  {cat:'Rabbana', title:"Maghfirat Aur Reham Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَیۡرُ ٱلرَّٰحِمِینَ", translit:"Rabbana amanna faghfir lana warhamna wa anta khayrur rahimin", meaning:"Ae hamare Rab, hum emaan laaye, to hamein bakhsh de aur hum par reham kar, aur Tu sab se behtar reham karne wala hai.", ref:"Qur’an 23:109", tags:["Quranic", "Rabbana", "Rehmat"], ent:"Forgiveness and Mercy", enm:"Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful."},
  {cat:'Rabbana', title:"Jahannam Ke Azaab Se Panah", arabic:"رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا کَانَ غَرَامًا إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا", translit:"Rabbana isrif 'anna 'adhaba jahannam, inna 'adhabaha kana gharama, innaha sa'at mustaqarranw wa muqama", meaning:"Ae hamare Rab, humse Jahannam ka azaab door rakh. Beshak uska azaab laazmi aur chipakne wala hai. Woh bura thikana aur theharne ki jagah hai.", ref:"Qur’an 25:65-66", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Protection from the Punishment of Hell", enm:"Our Lord, avert from us the punishment of Hell. Its punishment is ever adhering; it is evil as a settlement and residence."},
  {cat:'Rabbana', title:"Aankhon Ki Thandak, Nek Aulad Aur Imam", arabic:"رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّیَّـٰتِنَا قُرَّةَ أَعۡیُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِینَ إِمَامًا", translit:"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil muttaqina imama", meaning:"Ae hamare Rab, hamein hamari biwiyon aur aulad se aankhon ki thandak ata kar aur hamein mutteqi logon ka imam (rehnumaa) bana.", ref:"Qur’an 25:74", tags:["Quranic", "Rabbana", "Aulad"], ent:"Comfort to the Eyes and Righteous Leadership", enm:"Our Lord, grant us from our spouses and offspring comfort to our eyes, and make us a leader for the righteous."},
  {cat:'Rabbana', title:"Shukr Aur Bakhshish", arabic:"رَبَّنَا لَغَفُورٌ شَکُورٌ", translit:"Rabbana la ghafurun shakur", meaning:"Ae hamare Rab, beshak Tu bakhshne wala aur qadar karne wala hai.", ref:"Qur’an 35:34", tags:["Quranic", "Rabbana", "Shukr"], ent:"Forgiveness and Appreciation", enm:"Our Lord is Forgiving and Appreciative."},
  {cat:'Rabbana', title:"Tauba Karne Walon Ki Maghfirat Aur Jahannam Se Hifazat", arabic:"رَبَّنَا وَسِعۡتَ کُلَّ شَیۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِینَ تَابُواْ وَٱتَّبَعُواْ سَبِیلَکَ وَقِهِمۡ عَذَابَ ٱلۡجَحِیمِ", translit:"Rabbana wasi'ta kulla shay'in rahmatanw wa 'ilman faghfir lilladhina taabu wattaba'u sabilaka wa qihim 'adhabal jahim", meaning:"Ae hamare Rab, Tu ne har cheez ko apni rehmat aur ilm mein samoya hua hai. Un logon ko bakhsh de jo tauba karte hain aur Tere raaste ki pairwi karte hain, aur unhein jahannam ke azaab se bacha le.", ref:"Qur’an 40:7", tags:["Quranic", "Rabbana", "Tauba"], ent:"Forgiveness for Those Who Repent", enm:"Our Lord, You have encompassed all things in mercy and knowledge. Forgive those who repent and follow Your way, and protect them from the punishment of Hellfire."},
  {cat:'Rabbana', title:"Jannat Mein Walidain, Aulad Aur Biwiyon Ke Saath", arabic:"رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّیَّـٰتِهِمۡۚ إِنَّکَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَکِیمُ وَقِهِمُ ٱلسَّیِّـَٔاتِۚ وَمَن تَقِ ٱلسَّیِّـَٔاتِ یَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِکَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ", translit:"Rabbana wa adkhilhum jannati 'adnin allati wa'attahum wa man salaha min aba'ihim wa azwajihim wa dhurriyyatihim, innaka antal 'Azizul Hakim. Wa qihimus sayyi'at, wa man taqis sayyi'ati yawma'idhin faqad rahimtah, wa dhalika huwal fawzul 'adhim", meaning:"Ae hamare Rab, unhein Adan ke baghon mein daakhil kar jo Tu ne unse wada kiya hai, aur unke baap-dada, biwiyon aur aulad mein se jo nek hain unhein bhi. Beshak Tu hi zabardast aur hikmat wala hai. Unhein buraiyon se bacha, aur jisko Tu us din buraiyon se bacha le, us par Tu ne reham kiya. Yehi badi kamyabi hai.", ref:"Qur’an 40:8-9", tags:["Quranic", "Rabbana", "Jannat"], ent:"Paradise with Family", enm:"Our Lord, admit them to gardens of perpetual residence which You promised them, along with the righteous among their forefathers, spouses and offspring. Protect them from evil consequences. That is the great success."},
  {cat:'Rabbana', title:"Bhai Bandon Ke Liye Maghfirat, Dil Mein Kina Na Ho", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِینَ سَبَقُونَا بِٱلۡإِیمَٰنِ وَلَا تَجۡعَلۡ فِی قُلُوبِنَا غِلّٗا لِّلَّذِینَ ءَامَنُواْ", translit:"Rabbana ghfir lana wa li ikhwanina alladhina sabaquna bil iman, wa la taj'al fi qulubina ghillal lilladhina amanu", meaning:"Ae hamare Rab, hamein aur hamare un bhaiyon ko bakhsh de jo hum se pehle emaan laaye, aur hamare dilon mein emaan walon ke liye kina na rakh.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Ukhuwwat"], ent:"Brotherhood Without Resentment", enm:"Our Lord, forgive us and our brothers who preceded us in faith, and put not in our hearts resentment toward those who believed."},
  {cat:'Rabbana', title:"Rauf Aur Raheem Rab Ki Pukaar", arabic:"رَبَّنَآ إِنَّکَ رَءُوفٞ رَّحِیمٞ", translit:"Rabbana innaka ra'ufur rahim", meaning:"Ae hamare Rab, beshak Tu bahut shafqat karne wala aur reham karne wala hai.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Rehmat"], ent:"Dua of Kindness and Mercy", enm:"Our Lord, indeed You are Kind and Merciful."},
  {cat:'Rabbana', title:"Tawakkul Aur Akhirat Ki Taraf Wapsi", arabic:"رَّبَّنَا عَلَیۡکَ تَوَکَّلۡنَا وَإِلَیۡکَ أَنَبۡنَا وَإِلَیۡکَ ٱلۡمَصِیرُ", translit:"Rabbana 'alayka tawakkalna wa ilayka anabna wa ilaykal masir", meaning:"Ae hamare Rab, hamne Tujh par tawakkul kiya, Teri taraf rujoo kiya aur Teri hi taraf lautna hai.", ref:"Qur’an 60:4", tags:["Quranic", "Rabbana", "Tawakkul"], ent:"Trust in Allah and Return to Him", enm:"Our Lord, upon You we have relied, to You we have returned, and to You is the destination."},
  {cat:'Rabbana', title:"Kafiron Ke Fitne Se Hifazat (Hazrat Ibrahim AS)", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِینَ کَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّکَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَکِیمُ", translit:"Rabbana la taj'alna fitnatal lilladhina kafaru waghfir lana rabbana, innaka antal 'Azizul Hakim", meaning:"Ae hamare Rab, hamein kafiron ke liye fitna (aazmaish ka zariya) na bana, aur hamein bakhsh de. Beshak Tu zabardast aur hikmat wala hai.", ref:"Qur’an 60:5", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Protection from the Trial of Disbelievers (Ibrahim AS)", enm:"Our Lord, make us not a trial for the disbelievers, and forgive us. Indeed, You are the Exalted in Might, the Wise."},
  {cat:'Rabbana', title:"Noor Ki Takmeel Aur Maghfirat", arabic:"رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّکَ عَلَیٰ کُلِّ شَیۡءٖ قَدِیرٞ", translit:"Rabbana atmim lana nurana waghfir lana, innaka 'ala kulli shay'in qadir", meaning:"Ae hamare Rab, hamare liye hamara noor mukammal kar de aur hamein bakhsh de. Beshak Tu har cheez par qadir hai.", ref:"Qur’an 66:8", tags:["Quranic", "Rabbana", "Noor"], ent:"Completion of Our Light and Forgiveness", enm:"Our Lord, perfect our light for us and forgive us. Indeed, You are over all things competent."},
  {cat:"Pareshani", title:"Gham, Susti Aur Qarz Se Panah Ki Dua", arabic:"اللَّهُمَّ إِنِّی أَعُوذُ بِکَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِکَ مِنَ الْعَجْزِ وَالْکَسَلِ، وَأَعُوذُ بِکَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِکَ مِنْ غَلَبَةِ الدَّیْنِ وَقَهْرِ الرِّجَالِ", translit:"Allahumma inni a'udhu bika minal-hammi wal-hazan, wa a'udhu bika minal-'ajzi wal-kasal, wa a'udhu bika minal-jubni wal-bukhl, wa a'udhu bika min ghalabatid-dayni wa qahrir-rijal.", meaning:"Ya Allah! Main Tujh se fikr aur gham se panah maangta hoon, aur be-basi aur susti se panah maangta hoon. Main Tujh se buzdili aur bukhl se panah maangta hoon, aur qarz ke bojh aur logon ke ghalib aa jane se Teri panah chahta hoon.", ref:"Sahih Bukhari", tags:["Sunnah", "Pareshani", "Hifazat"], ent:"Protection from Worry, Weakness and Debt", enm:"O Allah, I seek refuge in You from worry and grief, from weakness and laziness, from cowardice and miserliness, and from being overcome by debt and overpowered by men."},
  {cat:"Khana", title:"Khana khatam hone ki dua", arabic:"الْحَمْدُ لِلَّهِ الَّذِی أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مِنَ الْمُسْلِمِینَ", translit:"Alhamdu lillahil-lazi at'amana wa saqana wa ja'alana minal muslimin.", meaning:"Sab khubiyan Allah paak ke liye hain, jisne hamein khilaya aur pilaya aur musalman banaya.", ref:"Abu Dawood, Tirmidhi", info:"Hadees: Hazrat Abu Sa'eed Khudri (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs khana khane ke baad yeh dua padhe, uske pichle gunah bakhsh diye jayenge. Khana khatam karne ke baad shukr ka izhaar karna sunnat hai.", tags:["Sunnah", "Shukr"], ent:"Dua After Finishing Food", enm:"All praise is for Allah, who fed us, gave us drink, and made us Muslims.", eninfo:"Hadith: Abu Sa'eed Khudri (RA) narrated that the Prophet ﷺ said: whoever says this dua after eating, his past sins will be forgiven. Expressing gratitude after finishing a meal is a Sunnah."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Adam (AS): Gunah Ke Baad", ord:1, arabic:"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَکُونَنَّ مِنَ الْخَاسِرِینَ", translit:"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal khasirin", meaning:"Ae hamare Rab, humne apni jaanon par zulm kiya. Agar Tu humein maaf na kare aur humpar reham na farmaye, to hum zaroor nuqsaan uthane walon mein se ho jayenge.", ref:"Qur’an 7:23", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Jannat mein hui bhool ke baad Hazrat Adam (AS) aur Hazrat Hawwa (AS) ne yeh dua ki. Jab apni galti ka ehsaas ho, to bahana banane ke bajaye seedha iqrar aur tauba.", ent:"Prophet Adam (AS): After His Mistake", enm:"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy on us, we will surely be among the losers.", eninfo:"After his mistake in Jannah, Adam (AS) and Hawwa (AS) made this dua. When you realise your mistake, own it and turn to Allah in tauba instead of making excuses."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Nuh (AS): Qaum Ke Inkaar Par", ord:2, arabic:"أَنِّی مَغْلُوبٌ فَانتَصِرْ", translit:"Anni maghlubun fantasir", meaning:"(Ae mere Rab) main be-bas hoon, bas Tu meri madad farma.", ref:"Qur’an 54:10", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Nuh (AS) ne 950 saal tak dawat di aur qaum ne jhutlaya. Aakhir mein unhon ne Allah se madad maangi. Jab insaan ki koshish khatam ho jaye, to madad Allah se maangein.", ent:"Prophet Nuh (AS): When His People Rejected Him", enm:"I am overpowered, so help me.", eninfo:"Nuh (AS) called his people for 950 years and they rejected him. In the end he asked Allah for help. When your own efforts run out, ask Allah for help."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Ibrahim (AS): Aulad Aur Namaz Ke Liye", ord:3, arabic:"رَبِّ اجْعَلْنِی مُقِیمَ الصَّلَاةِ وَمِن ذُرِّیَّتِی ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ", translit:"Rabbij'alni muqimas-salati wa min zurriyyati, Rabbana wa taqabbal du'a", meaning:"Ae mere Rab, mujhe namaz qaim karne wala bana de, aur meri aulad mein se bhi (namaz qaim karne wale bana). Ae hamare Rab, meri dua qabool farma.", ref:"Qur’an 14:40", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Ibrahim (AS) ne apni biwi aur bete ko Makkah ki khaali, be-aab o giyah wadi mein Allah ke hawale kiya. Wahan unhon ne yeh dua ki.", ent:"Prophet Ibrahim (AS): For Prayer and Children", enm:"My Lord, make me an establisher of prayer, and from my descendants. Our Lord, accept my dua.", eninfo:"Ibrahim (AS) left his wife and son in the empty valley of Makkah, with no water and no people, and made this dua there."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Lut (AS): Qaum Ki Dhamki Par", ord:4, arabic:"رَبِّ نَجِّنِی وَأَهْلِی مِمَّا یَعْمَلُونَ", translit:"Rabbi najjini wa ahli mimma ya'malun", meaning:"Ae mere Rab, mujhe aur mere ghar walon ko us (buray amal) se nijat de jo yeh log karte hain.", ref:"Qur’an 26:169", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Jab Hazrat Lut (AS) ki qaum ne unhein shehar se nikaal dene ki dhamki di, to unhon ne Allah se apni aur apne ghar walon ki hifazat maangi.", ent:"Prophet Lut (AS): When His People Threatened Him", enm:"My Lord, save me and my family from what they do.", eninfo:"When Lut (AS) was threatened with expulsion by his own people, he asked Allah to save him and his family."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Yusuf (AS): Gunah Ki Taraf Bulawe Par", ord:5, arabic:"رَبِّ السِّجْنُ أَحَبُّ إِلَیَّ مِمَّا یَدْعُونَنِی إِلَیْهِ", translit:"Rabbis-sijnu ahabbu ilayya mimma yad'unani ilayh", meaning:"Ae mere Rab, qaid khana mujhe us cheez se zyada pasand hai jiski taraf yeh mujhe bulati hain.", ref:"Qur’an 12:33", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Jab Hazrat Yusuf (AS) ko gunah ki taraf bulaya gaya, to unhon ne gunah par qaid ko tarjeeh di aur Allah se madad maangi, taake woh gunah mein na girein.", ent:"Prophet Yusuf (AS): When Pushed Toward Sin", enm:"My Lord, prison is dearer to me than what they call me to.", eninfo:"When Yusuf (AS) was pushed toward sin, he chose prison over it and asked Allah for help so that he would not fall."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Ayyub (AS): Bimari Aur Takleef Mein", ord:6, arabic:"أَنِّی مَسَّنِیَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِینَ", translit:"Anni massaniyad-durru wa anta arhamur-rahimin", meaning:"Mujhe takleef ne aa liya hai, aur Tu sab reham karne walon se badh kar reham karne wala hai.", ref:"Qur’an 21:83", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Ayyub (AS) saalon bimaar rahe. Unhon ne shikayat ke bajaye Allah ki rehmat ka zikr karke dua ki, aur Allah ne unhein shifa di.", ent:"Prophet Ayyub (AS): In Sickness and Pain", enm:"Pain has touched me, and You are the Most Merciful of those who show mercy.", eninfo:"Ayyub (AS) was sick for years. He did not complain; he spoke of Allah's mercy, and Allah healed him."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Musa (AS): Akele Aur Bhooke Hone Par", ord:7, arabic:"رَبِّ إِنِّی لِمَا أَنزَلْتَ إِلَیَّ مِنْ خَیْرٍ فَقِیرٌ", translit:"Rabbi inni lima anzalta ilayya min khayrin faqir", meaning:"Ae mere Rab, jo bhi bhalai Tu mujh par naazil farmaye, main uska muhtaaj hoon.", ref:"Qur’an 28:24", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Musa (AS) Misr se nikal kar akele, bhooke aur ghar se door the. Madyan ke kuyein par logon ko paani pila kar saaye mein baithe aur yeh dua ki.", ent:"Prophet Musa (AS): Alone and Hungry", enm:"My Lord, I am in need of whatever good You send down to me.", eninfo:"Musa (AS) had left Egypt, alone, hungry and far from home. At the well of Madyan he watered the animals, sat in the shade and made this dua."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Yunus (AS): Andheron Mein", ord:8, arabic:"لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَکَ إِنِّی کُنتُ مِنَ الظَّالِمِینَ", translit:"La ilaha illa anta subhanaka inni kuntu minaz-zalimin", meaning:"Tere siwa koi ma'bood nahi, Tu paak hai, beshak main zalimon mein se tha.", ref:"Qur’an 21:87", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Yunus (AS) raat, samundar aur machli ke pet ke andheron mein the. Unhon ne tauba aur tasbeeh ke saath yeh dua ki.", ent:"Prophet Yunus (AS): In the Darkness", enm:"There is no god but You. Glory be to You. Indeed, I was among the wrongdoers.", eninfo:"Yunus (AS) was in the darkness of the night, the sea and the whale. He made this dua with tauba and tasbeeh."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Zakariya (AS): Aulad Ki Tamanna Mein", ord:9, arabic:"رَبِّ لَا تَذَرْنِی فَرْدًا وَأَنتَ خَیْرُ الْوَارِثِینَ", translit:"Rabbi la tazarni fardan wa anta khayrul-warithin", meaning:"Ae mere Rab, mujhe akela na chhod, aur Tu hi sab se behtar waaris hai.", ref:"Qur’an 21:89", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Hazrat Zakariya (AS) boorhe ho chuke the aur aulad nahi thi. Unhon ne Allah se wahi maanga jo asbaab ke lihaaz se mumkin nahi tha.", ent:"Prophet Zakariya (AS): Old and Without a Child", enm:"My Lord, do not leave me alone, and You are the best of inheritors.", eninfo:"Zakariya (AS) was old and had no child. He asked Allah for what seemed impossible by worldly means."},
  {cat:"Anbiya (Mushkil Waqt)", title:"Hazrat Muhammad ﷺ: Bade Lashkar Ki Khabar Par", ord:10, arabic:"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَکِیلُ", translit:"Hasbunallahu wa ni'mal wakil", meaning:"Humein Allah hi kaafi hai, aur woh behtareen kaarsaaz (bharose ke laayak) hai.", ref:"Qur’an 3:173", tags:["Quranic", "Anbiya", "Mushkil Waqt"], info:"Jab sahaba ko khabar di gayi ke dushman ne un ke khilaf bada lashkar jama kar liya hai, to unhon ne yeh kaha aur unka iman aur badh gaya.", ent:"Prophet Muhammad ﷺ: When Told of a Huge Army", enm:"Allah is enough for us, and He is the best One to trust.", eninfo:"When the Companions were told that a huge army had gathered against them, they said this and their faith increased."},
  {cat:"Jannat Aur Jahannam", title:"Jannat Maangne Ki Dua", arabic:"اللَّهُمَّ إِنِّی أَسْأَلُکَ الْجَنَّةَ", translit:"Allahumma inni as'alukal jannah", meaning:"Ae Allah, main Tujh se Jannat maangta hoon.", ref:"Jami Tirmidhi 2572", rep:3, tags:["Hadees", "Jannat"], info:"Hazrat Anas (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs Allah se teen baar Jannat maange, to Jannat kehti hai: \"Ae Allah, ise Jannat mein daakhil farma.\" Is hadees mein Jannat maangne ki tarbiyat hai; dua ke yeh chhote alfaaz isi maqsad ke liye padhe jaate hain. Teen baar padhna sunnat ka tareeqa hai.", ent:"Dua to Ask for Paradise", enm:"O Allah, I ask You for Paradise.", eninfo:"Anas (RA) narrated that the Prophet ﷺ said: whoever asks Allah for Paradise three times, Paradise says, \"O Allah, admit him into Paradise.\" The hadith teaches us to ask for Jannah; these short words are commonly recited for that purpose, three times."},
  {cat:"Jannat Aur Jahannam", title:"Jahannam Se Panah Ki Dua", arabic:"اللَّهُمَّ أَجِرْنِی مِنَ النَّارِ", translit:"Allahumma ajirni minan naar", meaning:"Ae Allah, mujhe (Jahannam ki) aag se panah de.", ref:"Jami Tirmidhi 2572", rep:3, tags:["Hadees", "Jahannam"], info:"Isi hadees mein hai: jo shakhs teen baar Jahannam se panah maange, to Jahannam kehti hai: \"Ae Allah, ise aag se bacha le.\" Yeh dua Jahannam se panah maangne ke liye padhi jaati hai, teen baar.", ent:"Dua for Protection from the Fire", enm:"O Allah, protect me from the Fire.", eninfo:"In the same hadith: whoever seeks refuge from the Fire three times, the Fire says, \"O Allah, save him from the Fire.\" This dua is recited three times to seek protection from the Fire."},
  {cat:"Istighfar", title:"Astaghfirullah", ord:1, ptarget:100, arabic:"أَسْتَغْفِرُ اللَّهَ", translit:"Astaghfirullah", meaning:"Main Allah se maafi maangta hoon.", ref:"Sahih Muslim 591", rep:3, tags:["Hadees","Istighfar"], info:"Hazrat Sauban (RA) farmate hain ki Nabi ﷺ namaz se salam pherte to teen baar istighfar karte (Astaghfirullah), phir \"Allahumma antas-salam...\" padhte. Namaz ke baad teen baar padhna sunnat hai.", ent:"Astaghfirullah", enm:"I seek forgiveness from Allah.", eninfo:"Thawban (RA) narrated that when the Prophet ﷺ finished his prayer he would seek forgiveness three times and then say \"Allahumma antas-salam...\". Saying it three times after the prayer is a Sunnah."},
  {cat:"Istighfar", title:"Momin Mard-Aurat Ke Liye Maghfirat", ord:2, arabic:"اللَّهُمَّ اغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ", translit:"Allahummaghfir lil mu'minina wal mu'minat, wal muslimina wal muslimat, al-ahya'i minhum wal amwat", meaning:"Ae Allah, tamam momin mard-aurat aur musalman mard-aurat ko bakhsh de, un mein se jo zinda hain unhein bhi aur jo guzar chuke unhein bhi.", ref:"Qur’an 47:19; Tabarani (Al-Mu’jam al-Kabir)", rep:3, tags:["Qur'an","Hadees","Istighfar"], info:"Qur'an (47:19) mein apne gunah aur momin mard-aurat ke liye istighfar ka hukm hai. Tabarani ki riwayat (Ubadah bin Samit RA) mein hai ki jo momin mard-aurat ke liye istighfar kare, Allah har momin ke badle uske liye ek neki likh deta hai; aalimon ne is riwayat ki sanad ko jayyid (achhi) kaha hai. Yeh alfaaz aam taur par padhe jaane wale hain.", ent:"Forgiveness for All Believers", enm:"O Allah, forgive the believing men and women and the Muslim men and women, the living among them and the dead.", eninfo:"The Qur'an (47:19) commands seeking forgiveness for oneself and for believing men and women. In a narration of Tabarani (from Ubadah ibn as-Samit RA) Allah records a good deed for the one who seeks forgiveness for each believer; scholars described its chain as good. These are the commonly recited words."},
  {cat:"Istighfar", title:"Maghfirat Aur Rahmat Ki Jaami Dua", ord:3, arabic:"اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاجْبُرْنِي وَاهْدِنِي وَارْزُقْنِي", translit:"Allahummaghfir li warhamni wa 'afini wajburni wahdini warzuqni", meaning:"Ae Allah, mujhe bakhsh de, mujh par reham farma, mujhe aafiyat de, meri kami poori farma, mujhe hidayat de aur mujhe rizq ata farma.", ref:"Sunan Abu Dawud 850, Jami Tirmidhi 284", rep:3, tags:["Hadees","Istighfar"], info:"Hazrat Ibn Abbas (RA) se riwayat hai ki Nabi ﷺ do sajdon ke darmiyan yeh dua padhte thay. Riwayaton mein alfaaz mein thoda farq hai, aur ise baqi auqaat mein bhi padha ja sakta hai.", ent:"A Comprehensive Dua for Forgiveness", enm:"O Allah, forgive me, have mercy on me, grant me well-being, make good my shortcomings, guide me and provide for me.", eninfo:"Ibn Abbas (RA) narrated that the Prophet ﷺ used to say this between the two prostrations. The wording differs slightly between narrations, and it can be recited at other times too."},
  {cat:"Istighfar", title:"Istighfar Aur Tauba", ord:4, ptarget:70, arabic:"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَیْهِ", translit:"Astaghfirullaha wa atoobu ilaih", meaning:"Main Allah se maafi maangta hoon aur usi ki taraf tauba karta hoon.", ref:"Sahih Bukhari 6307", rep:3, tags:["Hadees", "Tauba"], info:"Hazrat Abu Hurairah (RA) se riwayat hai ki Nabi ﷺ ne farmaya: \"Allah ki qasam, main din mein sattar (70) se zyada baar Allah se istighfar aur tauba karta hoon.\"", ent:"Seeking Forgiveness and Repenting", enm:"I seek Allah's forgiveness and turn to Him in repentance.", eninfo:"Abu Hurairah (RA) narrated that the Prophet ﷺ said: \"By Allah, I seek forgiveness from Allah and repent to Him more than seventy times a day.\""},
  {cat:"Istighfar", title:"Har Gunah Se Istighfar", ord:5, arabic:"أَسْتَغْفِرُ اللَّهَ رَبِّي مِنْ كُلِّ ذَنْبٍ وَأَتُوبُ إِلَيْهِ", translit:"Astaghfirullaha rabbi min kulli dhanbin wa atubu ilayh", meaning:"Main apne Rab Allah se har gunah ki maafi maangta hoon aur usi ki taraf tauba karta hoon.", ref:"Mashhoor istighfar; Sunnat: Sahih Muslim 2702", rep:3, tags:["Istighfar","Tauba"], info:"Yeh istighfar ke mashhoor alfaaz hain jo aam taur par padhe jaate hain. Nabi ﷺ khud din mein sau (100) baar istighfar karte thay (Sahih Muslim 2702).", ent:"Seeking Forgiveness for Every Sin", enm:"I seek forgiveness from Allah, my Lord, for every sin, and I turn to Him in repentance.", eninfo:"These are well-known words of istighfar. The Prophet ﷺ himself sought forgiveness a hundred times a day (Sahih Muslim 2702)."},
  {cat:"Istighfar", title:"Rabbighfir Warham (Qur’an)", ord:6, arabic:"رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرَّاحِمِينَ", translit:"Rabbighfir warham wa anta khayrur rahimin", meaning:"Ae mere Rab, mujhe bakhsh de aur reham farma, aur Tu sab se behtar reham karne wala hai.", ref:"Qur’an 23:118", rep:3, tags:["Quranic","Istighfar"], info:"Surah Al-Muminun ki aakhri ayat, jis mein Allah ne apne Nabi ﷺ ko yeh dua sikhayi.", ent:"Forgive and Have Mercy", enm:"My Lord, forgive and have mercy, and You are the best of those who show mercy.", eninfo:"The last verse of Surah Al-Mu'minun, in which Allah taught His Prophet ﷺ this dua."},
  {cat:"Istighfar", title:"Walidain Aur Momineen Ke Liye Maghfirat", ord:7, arabic:"رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", translit:"Rabbanagh fir li wa li walidayya wa lil mu'minina yawma yaqumul hisab", meaning:"Ae hamare Rab, mujhe, mere walidain ko aur sab imaan walon ko us din bakhsh de jis din hisaab qaim hoga.", ref:"Qur’an 14:41", rep:3, tags:["Quranic","Istighfar","Walidain"], info:"Surah Ibrahim mein Hazrat Ibrahim (AS) ki dua, jo apne liye, walidain ke liye aur tamam imaan walon ke liye hai.", ent:"Forgiveness for Me, My Parents and the Believers", enm:"Our Lord, forgive me, my parents and the believers on the Day the account is established.", eninfo:"The dua of Ibrahim (AS) in Surah Ibrahim, for himself, his parents and all the believers."},
  {cat:"Istighfar", title:"Kalma-e-Astaghfar", ord:8, arabic:"أَسْتَغْفِرُ اللَّهَ رَبِّي مِنْ كُلِّ ذَنْبٍ أَذْنَبْتُهُ عَمَدًا أَوْ خَطَأً سِرًّا أَوْ عَلَانِيَةً وَأَتُوبُ إِلَيْهِ مِنَ الذَّنْبِ الَّذِي أَعْلَمُ وَمِنَ الذَّنْبِ الَّذِي لَا أَعْلَمُ إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ وَسَتَّارُ الْعُيُوبِ وَغَفَّارُ الذُّنُوبِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ", translit:"Astaghfirullah rabbi min kulli dhanbin adhnabtuhu 'amadan aw khata'an sirran aw 'alaniyatan wa atubu ilayhi minadh dhanbilladhi a'lamu wa minadh dhanbilladhi la a'lamu innaka anta 'allamul ghuyubi wa sattarul 'uyubi wa ghaffarudh dhunubi wa la hawla wa la quwwata illa billahil 'aliyyil 'azim", meaning:"Main apne Rab Allah se har us gunah ki maafi maangta hoon jo maine jaan-boojh kar ya bhool kar, chhup kar ya khule aam kiya, aur tauba karta hoon un gunahon se jinhein main jaanta hoon aur jinhein nahin jaanta. Beshak Tu ghaib ko jaanne wala, aibon ko dhaanpne wala aur gunahon ko bakhshne wala hai. Gunah se bachne aur neki karne ki taqat sirf buland-o-azeem Allah hi se hai.", ref:"Kalma-e-Astaghfar (mashhoor kalima); \"La hawla...\" ka hissa Sahih Bukhari 6384", rep:3, tags:["Istighfar","Tauba"], info:"Yeh mashhoor kalima-e-astaghfar hai jo gunahon ke baare mein har tarah ki maafi (jaan-boojh kar, bhool kar, chhup kar, khule, maloom aur na-maloom) maangta hai. Akhri hissa \"La hawla wala quwwata illa billah\" hadees (Sahih Bukhari 6384) mein aaya hai.", ent:"Kalma-e-Astaghfar", enm:"I seek forgiveness from Allah, my Lord, for every sin I committed, intentionally or by mistake, in secret or in public, and I repent for the sin I know and the sin I do not know. You are the Knower of the unseen, the Concealer of faults and the Forgiver of sins. There is no power or strength except with Allah, the Most High, the Most Great.", eninfo:"The well-known Kalima of Astaghfar, asking forgiveness for every kind of sin, known and unknown. Its last part, \"La hawla wala quwwata illa billah\", is in a hadith (Sahih Bukhari 6384)."},
  {cat:"Istighfar", title:"Maghfirat Aur Tauba Qubool Hone Ki Dua", ord:9, arabic:"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", translit:"Rabbighfir li wa tub 'alayya innaka antat tawwabur rahim", meaning:"Ae mere Rab, mujhe bakhsh de aur meri tauba qubool farma, beshak Tu bohot tauba qubool karne wala, nihayat reham karne wala hai.", ref:"Jami Tirmidhi 3434, Sunan Abu Dawud 1516", rep:3, tags:["Hadees","Istighfar","Tauba"], info:"Hazrat Ibn Umar (RA) farmate hain ki hum ek hi majlis mein Nabi ﷺ ko yeh dua sau (100) baar padhte ginte thay. Imam Tirmidhi ne ise hasan sahih gharib kaha hai.", ent:"Forgive Me and Accept My Repentance", enm:"My Lord, forgive me and accept my repentance; indeed You are the Accepter of repentance, the Most Merciful.", eninfo:"Ibn Umar (RA) said they would count the Prophet ﷺ saying this a hundred times in a single sitting. Imam at-Tirmidhi graded it hasan sahih gharib."},
  {cat:"Pareshani", title:"La Hawla Wala Quwwata Illa Billah", arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", translit:"La hawla wala quwwata illa billah", meaning:"Allah ke bina na koi taqat hai aur na koi zor.", ref:"Sahih Bukhari 6384, Sahih Muslim 2704", rep:3, tags:["Hadees", "Sabr"], info:"Hazrat Abu Musa (RA) se riwayat hai ki Nabi ﷺ ne farmaya: \"Kya main tumhein Jannat ke khazanon mein se ek khazana na bataun?\" Phir farmaya: \"La hawla wala quwwata illa billah.\" Mushkil aur bebasi ke waqt yeh kalima bohot padha jaata hai.", ent:"There Is No Power Except with Allah", enm:"There is no power and no strength except with Allah.", eninfo:"Abu Musa (RA) narrated that the Prophet ﷺ said: \"Shall I not tell you of one of the treasures of Paradise?\" Then he said: \"La hawla wala quwwata illa billah.\" It is often recited in hardship and helplessness."},
  {cat:'Hifazat', title:"Ayat-ul-Kursi", arabic:"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", translit:"Allahu la ilaha illa huwal Hayyul Qayyum, la ta’khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa’u ’indahu illa bi-idhnih, ya’lamu ma bayna aydeehim wa ma khalfahum, wa la yuheetoona bishay’im min ’ilmihi illa bima sha’, wasi’a kursiyyuhus-samawati wal-ard, wa la ya’uduhu hifzuhuma, wa huwal ’Aliyyul ’Azeem.", meaning:"Allah, uske siwa koi ibadat ke laayak nahi. Wo hamesha zinda hai aur poori kainat ko thaamne wala hai. Use na oongh aati hai, na neend. Aasmanon aur zameen mein jo kuch hai, sab usi ka hai. Kaun hai jo uski ijazat ke baghair uske paas sifarish kar sake? Wo jaanta hai jo unke saamne hai aur jo unke peeche hai, aur log uske ilm mein se kisi cheez ko gher nahi sakte magar jitna wo chahe. Uski kursi aasmanon aur zameen par phaili hui hai, aur in dono ki hifazat use thakati nahi. Wahi sabse buland, bohat azmat wala hai.", ref:"Qur’an 2:255 (Surah Al-Baqarah)", info:"Ayat-ul-Kursi Qur’an ki sabse azeem aayat hai (Sahih Muslim, Ubayy bin Ka’b RA ki riwayat). Sone se pehle padhne wale ke saath Allah ki taraf se ek nigehbaan rehta hai aur subah tak shaitan uske qareeb nahi aata (Sahih Bukhari, Abu Hurairah RA). Har farz namaz ke baad padhne wale ke Jannat mein dakhil hone mein maut ke siwa koi cheez rukawat nahi (Sunan Nasai Kubra, Albani ne sahih kaha). Subah shaam aur ghar se nikalte waqt bhi padhna hifazat ke liye masnoon amal mein shamil hai.", ent:"Ayat-ul-Kursi", enm:"Allah! There is no god but He, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and the earth...", eninfo:"Ayat-ul-Kursi is the greatest verse of the Quran (Sahih Muslim). Whoever recites it before sleeping has a guardian from Allah and Shaytan will not come near until morning (Sahih Bukhari). Reciting it after every obligatory prayer is a means of entering Paradise (Sunan al-Nasa’i al-Kubra, graded sahih by al-Albani)."},
  {cat:'Hifazat', title:"Surah Al-Ikhlas", arabic:"قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", translit:"Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad.", meaning:"Kah do: wo Allah ek hai. Allah beniyaz hai (sab uske muhtaj hain). Na uski koi aulad hai, na wo kisi ki aulad hai. Aur koi uska hamsar nahi.", ref:"Qur’an 112 (Surah Al-Ikhlas)", info:"Nabi ﷺ ne farmaya: Surah Ikhlas Qur’an ke teesre hisse ke barabar hai (Sahih Bukhari, Sahih Muslim). Ek sahabi har rakat mein ise padhte the aur Nabi ﷺ ne farmaya ke Allah bhi unse mohabbat karta hai (Sahih Bukhari). Sone se pehle Ikhlas, Falaq aur Naas teen-teen baar padhkar haathon par phoonkna aur badan par pherna Nabi ﷺ ki sunnat hai (Sahih Bukhari).", ent:"Surah Al-Ikhlas", enm:"Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, and there is none comparable to Him.", eninfo:"The Prophet ﷺ said Surah al-Ikhlas equals a third of the Quran (Sahih Bukhari, Sahih Muslim). A companion who loved reciting it was told that Allah loves him too (Sahih Bukhari). Reciting the three Quls three times, blowing into the hands and wiping the body before sleep is a sunnah (Sahih Bukhari)."},
  {cat:'Hifazat', title:"Surah Al-Falaq", arabic:"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", translit:"Qul a’udhu bi Rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-’uqad. Wa min sharri hasidin idha hasad.", meaning:"Kah do: main subah ke Rab ki panah mangta hoon, har us cheez ke shar se jo usne paida ki, andheri raat ke shar se jab wo chha jaye, gaanthon mein phoonkne walon ke shar se, aur hasad karne wale ke shar se jab wo hasad kare.", ref:"Qur’an 113 (Surah Al-Falaq)", info:"Nabi ﷺ ne farmaya ke aisi aayatein utari gayi hain jinki misal nahi dekhi gayi: Falaq aur Naas (Sahih Muslim, Uqba bin Amir RA). Subah aur shaam teen-teen baar Ikhlas, Falaq aur Naas padhna har cheez se kaafi hai (Sunan Abu Dawood, Tirmidhi, hasan). Sone se pehle padhna aur haathon par phoonkkar badan par pherna masnoon hai (Sahih Bukhari).", ent:"Surah Al-Falaq", enm:"Say: I seek refuge in the Lord of daybreak, from the evil of what He has created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of the envier when he envies.", eninfo:"The Prophet ﷺ said that no verses like Falaq and Nas have been revealed (Sahih Muslim). Reciting the three Quls three times every morning and evening is sufficient for you against everything (Abu Dawood, Tirmidhi, hasan). Reciting them before sleep is a sunnah (Sahih Bukhari)."},
  {cat:'Hifazat', title:"Surah An-Naas", arabic:"قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ", translit:"Qul a’udhu bi Rabbin-naas. Malikin-naas. Ilahin-naas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-naas. Minal-jinnati wan-naas.", meaning:"Kah do: main logon ke Rab ki panah mangta hoon, logon ke badshah ki, logon ke ma’bood ki, us waswasa daalne wale ke shar se jo (Allah ka naam sunkar) peechhe hat jata hai, jo logon ke seenon mein waswase daalta hai, chahe wo jinnon mein se ho ya insaanon mein se.", ref:"Qur’an 114 (Surah An-Naas)", info:"Falaq aur Naas ko Nabi ﷺ ne panah maangne ki sabse behtareen surahein farmaya (Sahih Muslim, Sunan Abu Dawood). Nabi ﷺ jab bimar hote to ye Surahein padhkar apne upar dam karte (Sahih Bukhari, Sahih Muslim). Sone se pehle aur har namaz ke baad inhe padhna masnoon hai (Sunan Abu Dawood, Tirmidhi).", ent:"Surah An-Naas", enm:"Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the retreating whisperer who whispers in the hearts of mankind, from among jinn and mankind.", eninfo:"The Prophet ﷺ described Falaq and Nas as the best surahs for seeking refuge (Sahih Muslim, Abu Dawood). When ill, he would recite them over himself (Sahih Bukhari, Sahih Muslim). Reciting them before sleep and after each prayer is sunnah (Abu Dawood, Tirmidhi)."},
  {cat:'Qurbani', title:"Zabah ke waqt ki Dua", arabic:"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ", translit:"Bismillahi wallahu Akbar.", meaning:"Allah ke naam se, aur Allah sabse bada hai.", ref:"Sahih Bukhari, Sahih Muslim", info:"Har halal janwar ko zabah karte waqt Allah ka naam lena zaroori hai. Nabi ﷺ ne qurbani ke waqt ye alfaaz kahe (Anas RA, Sahih Bukhari aur Sahih Muslim). Jaan-boojh kar Bismillah chhodne se janwar halal nahi hota.", ent:"Dua When Slaughtering", enm:"In the name of Allah, and Allah is the Greatest.", eninfo:"Saying Allah’s name when slaughtering is required. The Prophet ﷺ said these words at the time of sacrifice (Anas RA, Bukhari and Muslim)."},
  {cat:'Qurbani', title:"Qurbani se pehle ki Dua", arabic:"إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ، اللَّهُمَّ مِنْكَ وَلَكَ", translit:"Inni wajjahtu wajhiya lilladhi fataras-samawati wal-arda hanifan wa ma ana minal-mushrikeen. Inna salati wa nusuki wa mahyaya wa mamati lillahi Rabbil-aalameen, la shareeka lah, wa bidhalika umirtu wa ana minal-muslimeen. Allahumma minka wa laka.", meaning:"Maine apna rukh us ki taraf kar liya jisne aasmanon aur zameen ko paida kiya, main ek Allah ka ho kar, aur main mushrikon mein se nahi. Meri namaz, meri qurbani, meri zindagi aur meri maut sab Allah, jahanon ke Rab, ke liye hai. Uska koi shareek nahi, mujhe isi ka hukm diya gaya aur main farmabardaron mein se hoon. Ae Allah, ye tujh hi se hai aur tere hi liye hai.", ref:"Sunan Abu Dawood; Surah Al-An’am 6:79, 162-163", info:"Ye dua zabah se pehle padhi jati hai, uske baad \"Bismillahi Allahu Akbar\" kehkar zabah karte hain (Sunan Abu Dawood, Jabir RA ki riwayat; aayatein Surah Al-An’am mein hain).", ent:"Dua Before Sacrifice", enm:"Indeed, I have turned my face towards the One who created the heavens and the earth... Indeed my prayer, my sacrifice, my living and my dying are for Allah, Lord of the worlds.", eninfo:"Recited before the sacrifice, followed by Bismillahi Allahu Akbar at the time of slaughter (Sunan Abu Dawood, Jabir RA; the verses are from Surah al-An’am)."},
  {cat:'Qurbani', title:"Qurbani qabool hone ki Dua", arabic:"اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ", translit:"Allahumma taqabbal min Muhammadin wa aali Muhammadin wa min ummati Muhammad.", meaning:"Ae Allah, ise Muhammad ﷺ ki taraf se, unki aal ki taraf se aur unki ummat ki taraf se qabool farma.", ref:"Sahih Muslim", info:"Nabi ﷺ ne qurbani ka mendha zabah karte waqt Bismillah kehkar ye dua padhi (Aisha RA, Sahih Muslim). Apni qurbani ke baad bhi Allah se qabooliyat ki dua karna achha amal hai.", ent:"Dua for Acceptance of Qurbani", enm:"O Allah, accept this from Muhammad, the family of Muhammad, and the ummah of Muhammad.", eninfo:"The Prophet ﷺ said this when sacrificing the ram (Aisha RA, Sahih Muslim)."},
];
const HADEES = [
  {cat:'Khawateen', src:"Ibn Majah, Ahmad (Hasan, An-Nawawi); An-Nasa'i mein Hazrat Aishah RA se bhi (number nahi diya gaya)", txt:"Hazrat Abu Hurairah (RA) se: Nabi ﷺ ne do kamzor tabqon, yateem aur aurat, ka haq maarne se sakht khabardar kiya.", en:"Narrated by Abu Hurairah (RA): the Prophet ﷺ gave a strong warning against wronging two vulnerable groups: orphans and women."},
  {cat:'Khawateen', src:"Sahih Muslim (number nahi diya gaya)", txt:"Hazrat Abu Hurairah (RA) se: Momin mard apni momina biwi se bughz na rakhe; agar uski ek aadat na pasand ho to doosri aadat pasand aa jayegi.", en:"Narrated by Abu Hurairah (RA): a believing man should not hate his believing wife; if he dislikes one of her traits, he will be pleased with another."},
  {cat:'Khawateen', src:"Sahih Muslim (number nahi diya gaya)", txt:"Jo aurat pehle shaadi-shuda reh chuki ho, wo apne maamle mein apne wali se zyada haq rakhti hai; aur kunwari ki ijazat uski khamoshi hai.", en:"A previously married woman has more right over her own affairs than her guardian, and a virgin's consent is her silence."},
  {cat:'Khawateen', src:"Sahih Bukhari, Sahih Muslim (number nahi diya gaya)", txt:"Hazrat Aishah (RA) se: ek aurat apni do betiyon ke saath aayi, uske paas sirf ek khajoor thi, usne wo bhi dono ko de di. Nabi ﷺ ne farmaya: jo betiyon ki achhi parwarish kare, wo uske liye Jahannam se parda banengi.", en:"Narrated by Aishah (RA): a woman came with her two daughters and had only one date, which she gave to them. The Prophet ﷺ said that whoever raises daughters well, they will be a shield for him from the Fire."},
  {cat:'Khawateen', src:"Sahih Muslim (number nahi diya gaya)", txt:"Hazrat Aishah (RA) se: Nabi ﷺ ne Allah ki raah mein jihad kiya, lekin kabhi kisi khaadim ya aurat ko haath se nahi maara.", en:"Narrated by Aishah (RA): the Prophet ﷺ fought in the cause of Allah, but never struck a servant or a woman."},
  {cat:'Khawateen', src:"Jami’ at-Tirmidhi (Sahih, Al-Albani) (number nahi diya gaya)", txt:"Hazrat Abu Hurairah (RA) se: Imaan mein sabse kamil momin wo hain jinke akhlaq sabse achhe hon, aur tum mein behtareen wo hain jo apni biwiyon ke saath sabse behtar hon.", en:"Narrated by Abu Hurairah (RA): the believers with the most complete faith are those with the best character, and the best of you are those who are best to their wives."},
  {cat:'Khawateen', src:"Sahih Muslim (number nahi diya gaya)", txt:"Hazrat Jabir bin Abdullah (RA) se: Auraton ke baare mein Allah se daro, kyunki tum ne unhe Allah ki amaan ke saath liya hai.", en:"Narrated by Jabir bin Abdullah (RA): fear Allah regarding women, for you have taken them under Allah's trust."},
  {cat:'Khawateen', src:"Sunan Abu Dawood (number nahi diya gaya)", txt:"Hazrat Mu'awiyah bin Haidah (RA) se: biwi ka haq ye hai ke jab tum khao to use khilao, jab pehno to use pehnao, uske chehre par na maaro, use bura na kaho, aur (naraazgi mein) uska bistar ghar ke andar hi chhodo.", en:"Narrated by Mu'awiyah bin Haidah (RA): the wife's right is that you feed her when you eat, clothe her when you dress, do not strike her face, do not insult her, and do not separate from her except within the house."},
  {cat:'Khawateen', src:"Sahih Bukhari (number nahi diya gaya)", txt:"Hazrat Aishah (RA) se: Hazrat Khadijah (RA) ki tareef Nabi ﷺ kasrat se karte, is par Hazrat Aishah (RA) ko ghairat hoti. Nabi ﷺ ne unke liye Jannat mein mahal ki basharat di.", en:"Narrated by Aishah (RA): the Prophet ﷺ often praised Khadijah (RA), which made Aishah (RA) jealous. He gave Khadijah (RA) the glad tidings of a palace in Paradise."},
  {cat:'Khawateen', src:"Sahih Bukhari (number nahi diya gaya)", txt:"Hazrat Abu Sa'id Khudri (RA) se: auraton ne Nabi ﷺ se kaha ke mard aapka sara waqt le lete hain, hamare liye bhi ek din tay kar dein. Aap ﷺ ne unke liye ek din tay kiya aur unhe naseehat farmayi.", en:"Narrated by Abu Sa'id al-Khudri (RA): women asked the Prophet ﷺ to set a day for them, as men took up most of his time. He agreed and taught them on that day."},
  {cat:'Khawateen', src:"Sahih Bukhari, Sahih Muslim (number nahi diya gaya)", txt:"Hazrat Abu Hurairah (RA) se: Nabi ﷺ ne auraton ke saath narmi aur bhalai ka hukm diya.", en:"Narrated by Abu Hurairah (RA): the Prophet ﷺ urged gentleness and kindness toward women."},
  {cat:'Khawateen', src:"Sunan Abu Dawood, Jami’ at-Tirmidhi (number nahi diya gaya)", txt:"Hazrat Aishah (RA) se: Aurtein mardon ki hamsar (jaisi) hain.", en:"Narrated by Aishah (RA): women are counterparts (like two halves) of men."},
  {cat:'Khawateen', src:"Musnad Ahmad (Al-Hakim ne sahih kaha, Hasan: Ahmad Shakir) (number nahi diya gaya)", txt:"Hazrat Abdullah bin Abbas (RA) se: jiski beti ho, wo use zinda dafan na kare, haqeer na jaane aur beton ko us par tarjeeh na de, to Allah use Jannat mein dakhil karega.", en:"Narrated by Abdullah ibn Abbas (RA): whoever has a daughter and does not bury her alive, belittle her, or prefer sons over her, Allah will admit him to Paradise."},
  {cat:'Khawateen', src:"Sahih Bukhari 5797, Sahih Muslim 2323 (Muttafaqun Alayhi)", txt:"Hazrat Anas bin Malik (RA) se: Nabi ﷺ ne apni azwaaj ke oont ke qafile ke saarbaan Anjasha se farmaya: aahista chalo, ye shishon (naazuk cheezon) ki tarah hain.", en:"Narrated by Anas ibn Malik (RA): the Prophet ﷺ told Anjasha, who was driving the camels carrying some of his wives, to go slowly, as they were like fragile glass."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 644 (Sahih)", txt:"Hazrat Abu Sa'id al-Khudri (RA) se: Azaan dete waqt awaaz buland karo. Jo bhi cheez us awaaz ko sunegi (insaan, jinn ya koi bhi cheez) woh Qayamat ke din tumhare liye gawahi degi.", en:"Narrated by Abu Sa'id al-Khudri (RA): raise your voice when calling the Adhan; everything that hears it will testify for you on the Day of Resurrection."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 645 (Sahih)", txt:"Hazrat Abu Hurairah (RA) se: Muazzin ki maghfirat uski awaaz ke pahunchne ki had tak ki jaati hai.", en:"Narrated by Abu Hurairah (RA): the muadhdhin is forgiven as far as his voice reaches."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 646 (Sahih)", txt:"Hazrat Bara bin Azib (RA) se: Allah aur uske farishte pehli safon par rehmat bhejte hain, aur muazzin ko un sab namaziyon jaisa ajr milta hai jo uski pukaar par namaz padhte hain.", en:"Narrated by al-Bara bin Azib (RA): Allah and His angels send blessings on the front rows, and the muadhdhin receives a reward like that of those who pray in response."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 647 (Sahih)", txt:"Hazrat Abu Mahdhurah (RA) se: Fajr ki Azaan mein 'As-salatu khayrum minan-naum' (namaz neend se behtar hai) ka izafa hai.", en:"Narrated by Abu Mahdhurah (RA): the Fajr Adhan includes the added phrase 'prayer is better than sleep'."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 670 (Sahih)", txt:"Hazrat Abu Hurairah (RA) se: Shaitan Azaan aur Iqamat sunkar bhaag jaata hai, phir namaz mein lagne wale ko bahkane wapas aa jaata hai.", en:"Narrated by Abu Hurairah (RA): the Shaytan flees when the Adhan and Iqamah are called, then returns to distract the worshipper."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 671 (Sahih)", txt:"Hazrat Abu Hurairah (RA) se: Agar log Azaan aur pehli saf ka sawab jaan lete aur qur'a daalne ke siwa koi raasta na paate, to qur'a daalte.", en:"Narrated by Abu Hurairah (RA): if people knew the reward of the Adhan and the first row, and found no way except drawing lots, they would draw lots."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 673 (Sahih)", txt:"Hazrat Abu Sa'id al-Khudri (RA) se: Jab tum Azaan suno to wahi kaho jo muazzin kehta hai.", en:"Narrated by Abu Sa'id al-Khudri (RA): when you hear the call to prayer, say what the muadhdhin says."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 674 (Hasan)", txt:"Hazrat Abu Hurairah (RA) se: Jo yaqeen ke saath muazzin ki tarah Azaan ke alfaaz dohraye, woh Jannat mein dakhil hoga.", en:"Narrated by Abu Hurairah (RA): whoever repeats the Adhan with certainty will enter Paradise."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 677 (Sahih)", txt:"Hazrat Muawiyah (RA) ka amal: jab muazzin 'Hayya alas-salah' aur 'Hayya alal-falah' kehta to woh 'La hawla wa la quwwata illa billah' kehte.", en:"The practice of Mu'awiyah (RA): at the two 'Hayya' phrases he would say 'La hawla wa la quwwata illa Billah'."},
  {cat:'Azaan', src:"Sunan an-Nasa'i 678", txt:"Hazrat Abdullah bin Amr (RA) se: Azaan ka jawab do, phir Nabi ﷺ par durood bhejo, phir Allah se Nabi ﷺ ke liye 'Waseela' maango.", en:"Narrated by Abdullah bin Amr (RA): repeat the Adhan, then send blessings on the Prophet ﷺ, then ask Allah for al-Wasilah for him."},
  {cat:'Azaan', src:"Sahih al-Bukhari 614", txt:"Hazrat Jabir bin Abdullah (RA) se: Jo Azaan sunkar 'Allahumma Rabba hazihid-da'watit-tammah...' wali dua padhe, uske liye Qayamat ke din Nabi ﷺ ki shafa'at jaiz ho jaati hai.", en:"Narrated by Jabir bin Abdullah (RA): whoever says the supplication 'Allahumma Rabba hazihid-da'watit-tammah...' on hearing the Adhan will receive the Prophet's ﷺ intercession on the Day of Resurrection."},
  {cat:'Namaz', src:'Sahih Bukhari', txt:'Namaz Deen ka sutoon hai. Jisne isko qayam kiya usne Deen ko qayam kiya, aur jisne isko chhod diya usne Deen ko gira diya.', en:"Establishing prayer is the pillar of the religion. Whoever establishes it has established the religion, and whoever abandons it has destroyed the religion."},
  {cat:'Namaz', src:'Sahih Muslim', txt:'Qayamat ke din banda ke aamaal mein sabse pehle Namaz ka hisaab liya jayega. Agar woh theek hui to baaki sab aamaal theek honge.', en:"On the Day of Judgment, the first deed a servant will be questioned about is prayer. If it is sound, the rest of his deeds will be sound."},
  {cat:'Akhlaq', src:'Sahih Bukhari', txt:'Tum mein sabse behtareen woh hai jo apne akhlaq mein sabse achha ho.', en:"The best of you is the one with the best character."},
  {cat:'Akhlaq', src:'Tirmidhi', txt:'Musalman woh hai jiski zabaan aur haath se doosre Musalman mehfooz rahein.', en:"A Muslim is the one from whose tongue and hand other Muslims are safe."},
  {cat:'Ilm', src:'Ibn Majah', txt:'Ilm haasil karna har Musalman mard aur aurat par farz hai.', en:"Seeking knowledge is an obligation upon every Muslim, man and woman."},
  {cat:'Sadqa', src:'Sahih Bukhari', txt:'Muskuraana bhi sadqa hai.', en:"Smiling is also charity."},
  {cat:'Ramzan', src:'Sahih Bukhari', txt:'Jab Ramzan aata hai to Jannat ke darwaze khol diye jaate hain aur Jahannam ke darwaze band kar diye jaate hain.', en:"When Ramadan comes, the gates of Paradise are opened, the gates of Hell are closed, and the devils are chained."},
  {cat:'Ramzan', src:'Sahih Muslim', txt:'Jisne Ramzan ke roze imaan ke saath aur sawaab ki niyyat se rakhe, uske pichhle gunaah maaf kar diye jaate hain.', en:"Whoever fasts Ramadan with faith and seeking its reward, his past sins will be forgiven."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 413", txt:"Qayamat ke din bande se sabse pehle uski namaz ka hisaab liya jayega. Agar namaz theek nikli to wo kamyaab aur nijaat paane wala hoga, aur agar namaz mein kami nikli to wo nakaam aur nuqsan mein hoga.", en:"On the Day of Resurrection the first deed a servant will be called to account for is his Salat. If it is complete, he is successful and saved, but if it is defective, he has failed and lost."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 413", txt:"Agar bande ke farz mein kuch kami hogi to Rab, buland aur azmat wala, farmayega: dekho, kya mere bande ke paas kuch nafl bhi hain? To un nafl se uske farz ki kami poori kar di jayegi. Phir baaki aamaal ka bhi isi tarah muamla hoga.", en:"If something is deficient in his obligatory prayers, the Lord, Mighty and Sublime, says: Look, does My servant have any voluntary prayers? With them, what was deficient in his obligatory prayers will be completed. Then the rest of his deeds will be treated the same way."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 221", txt:"Jo shakhs Isha ki namaz jamaat ke saath padhe, goya usne aadhi raat qiyam kiya. Aur jo Isha aur Fajr jamaat ke saath padhe, goya usne poori raat qiyam kiya.", en:"Whoever attends Isha in congregation has the reward as if he had stood half the night in prayer. And whoever prays Isha and Fajr in congregation has the reward as if he had stood the entire night."},
  {cat:'Namaz', src:"Sahih Bukhari, Sahih Muslim (Riyad as-Salihin 1073)", txt:"Munafiqon par Fajr aur Isha ki namaz se zyada bhaari koi namaz nahi. Agar wo in dono namazon ki fazilat jaan lein to ghutnon ke bal ghistate hue bhi aayen.", en:"No prayer is more burdensome to the hypocrites than the Fajr and the Isha prayers; if they knew their merits, they would come to them even if they had to crawl."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 170", txt:"Nabi ﷺ se poochha gaya: sabse behtareen amal kaun sa hai? Aap ﷺ ne farmaya: namaz ko uske awwal waqt par padhna.", en:"The Prophet ﷺ was asked: Which deed is the best? He said: Salat at the beginning of its time."},
  {cat:'Namaz', src:"Sahih Muslim (Riyad as-Salihin 1102)", txt:"Fajr se pehle ki do rakaat (sunnat) duniya aur jo kuch is mein hai, sab se behtar hain.", en:"The two rak’ah before the dawn prayer are better than this world and all it contains."},
  {cat:'Namaz', src:"Sunan Ibn Majah 1140 (Hasan)", txt:"Jo shakhs pabandi se 12 rakaat sunnat padhe, uske liye Jannat mein ghar banaya jayega: Zuhr se pehle 4, Zuhr ke baad 2, Maghrib ke baad 2, Isha ke baad 2 aur Fajr se pehle 2.", en:"Whoever persists in performing twelve rak’ah of the Sunnah, a house will be built for him in Paradise: four before Zuhr, two after Zuhr, two after Maghrib, two after Isha and two before Fajr."},
  {cat:'Namaz', src:"Sunan Abu Dawood, Jami’ at-Tirmidhi (Riyad as-Salihin 1116)", txt:"Jo shakhs Zuhr se pehle 4 aur Zuhr ke baad 4 rakaat ki pabandi kare, Allah use (Jahannam ki) aag se bacha lega.", en:"Whoever observes four rak’ah before Zuhr and four after it, Allah will shield him from the Fire."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 4 (Hasan)", txt:"Jannat ki kunji namaz hai, aur namaz ki kunji wuzu hai.", en:"The key to Paradise is Salat, and the key to Salat is Wudu."},
  {cat:'Namaz', src:"Jami’ at-Tirmidhi 2618", txt:"Insaan aur kufr ke darmiyan namaz chhod dene ka (hi) fasla hai.", en:"Between disbelief and faith is abandoning the Salat."},
  {cat:'Namaz', src:"Qur’an 29:45", txt:"Beshak namaz be-hayai aur burai se rokti hai.", en:"Indeed, prayer prohibits immorality and wrongdoing."},
  {cat:'Namaz', src:"Qur’an 23:1-2", txt:"Yaqeenan wo momin kamyaab ho gaye, jo apni namaz mein khushu (aajizi) ikhtiyar karte hain.", en:"Successful indeed are the believers: those who humble themselves in prayer."},
  {cat:'Namaz', src:"Qur’an 2:153", txt:"Ae imaan walo! Sabr aur namaz se madad maango. Beshak Allah sabr karne walon ke saath hai.", en:"O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient."},
  {cat:'Namaz', src:"Sunan Ibn Majah 1399 (Anas RA)", txt:"Allah ne shuru mein roz 50 namazein farz keen. Musa (AS) ke mashware par Nabi ﷺ baar-baar kami ki darkhwast karte rahe, yahan tak ke 5 namazein reh gayin, aur unka sawab 50 hi ka hai.", en:"Allah first made fifty prayers a day obligatory. On the advice of Musa (AS) the Prophet ﷺ kept asking for a reduction until five remained, with the reward of fifty."},
  {cat:'Namaz', src:"Sahih Bukhari 631 (Malik bin Huwairith RA)", txt:"Namaz isi tarah padho jaise tum mujhe padhte dekhte ho. Jab namaz ka waqt aa jaye to tum mein se ek azaan de, aur tum mein sabse bade imamat karein.", en:"Pray as you have seen me pray. When the time for prayer comes, let one of you call the adhan, and let the eldest lead you."},
  {cat:'Namaz', src:"Sahih Bukhari 528 (Abu Hurairah RA)", txt:"Batao, agar tum mein se kisi ke darwaze par nehar ho jis mein wo roz paanch baar nahaye, kya uske badan par mail reh jayega? Sahaba ne kaha: nahi. Farmaya: yahi paanchon namazon ki misaal hai, Allah inke zariye gunah mita deta hai.", en:"If one of you had a river at his door in which he bathed five times a day, would any dirt remain on him? They said no. He said: That is the example of the five prayers; Allah erases sins through them."},
  {cat:'Namaz', src:"Sahih Bukhari 527 (Abdullah bin Mas’ud RA)", txt:"Poochha gaya: Allah ko sabse pyara amal kaun sa hai? Farmaya: namaz ko uske waqt par padhna. Phir kaun sa? Farmaya: walidain ke saath achha sulook. Phir? Farmaya: Allah ki raah mein jihad.", en:"He was asked: Which deed is most beloved to Allah? He said: Prayer at its proper time. Then? Kindness to parents. Then? Striving in the way of Allah."},
  {cat:'Namaz', src:"Sahih Bukhari 391 (Anas RA)", txt:"Jo hamari tarah namaz padhe, hamare qibla ki taraf rukh kare aur hamara zabeeha khaye, wo Musalman hai, jise Allah aur uske Rasool ﷺ ki panah hasil hai.", en:"Whoever prays as we pray, faces our Qiblah and eats our slaughtered animals is a Muslim, under the protection of Allah and His Messenger."},
  {cat:'Namaz', src:"Sahih Bukhari 717, 719, 723 (Nu’man bin Bashir RA, Anas RA)", txt:"Namaz mein safein seedhi rakho aur mil kar khade ho. Safein seedhi karna namaz ko theek tarah qayam karne ka hissa hai. Warna Allah tumhare chehron ke darmiyan (dilon mein) ikhtilaf daal dega.", en:"Straighten the rows and stand close together; straightening the rows is part of establishing the prayer properly. Otherwise Allah will create discord among you."},
  {cat:'Namaz', src:"Sahih Bukhari 586 (Abu Sa’id al-Khudri RA)", txt:"Fajr ke baad sooraj nikalne tak aur Asr ke baad sooraj doobne tak koi (nafl) namaz nahi.", en:"There is no voluntary prayer after Fajr until the sun rises, and none after Asr until the sun sets."},
  {cat:'Namaz', src:"Sahih Bukhari 477, 645, 646 (Abu Hurairah RA, Ibn Umar RA, Abu Sa’id RA)", txt:"Jamaat ki namaz akele ki namaz se 25 ya 27 guna afzal hai. Masjid ki taraf har qadam par ek darja buland hota aur ek gunah mitaya jata hai, aur jab tak banda namaz ke intezar mein baitha rehta hai, farishte uske liye dua karte hain.", en:"Prayer in congregation is 25 or 27 times better than praying alone. Each step toward the mosque raises a degree and erases a sin, and angels pray for him while he waits for the prayer."},
  {cat:'Akhlaq', src:"Sunan Abu Dawood 4799, Jami’ at-Tirmidhi 2002", txt:"Qayamat ke din mizaan mein achhe akhlaq se zyada bhaari koi cheez nahi hogi.", en:"Nothing will be heavier on the Scale on the Day of Resurrection than good character."},
  {cat:'Akhlaq', src:"Sahih Bukhari 3559, Sahih Muslim 2321", txt:"Tum mein sabse behtar wo hain jinke akhlaq sabse achhe hain.", en:"The best of you are those with the best character."},
  {cat:'Akhlaq', src:"Sahih Muslim 2553", txt:"Nekki achhe akhlaq ka naam hai, aur gunah wo hai jo tere dil mein khatke aur tu ye pasand na kare ke logon ko pata chale.", en:"Righteousness is good character, and sin is what wavers in your heart and you dislike people finding out about it."},
  {cat:'Akhlaq', src:"Sahih Bukhari 6018, Sahih Muslim 47", txt:"Jo Allah aur aakhirat ke din par imaan rakhta hai, wo ya to achhi baat kahe ya khamosh rahe.", en:"Whoever believes in Allah and the Last Day should speak good or keep silent."},
  {cat:'Akhlaq', src:"Jami’ at-Tirmidhi 2317 (Hasan)", txt:"Insaan ke islam ki khoobi ye hai ke wo be-maqsad aur faltu cheezein chhod de.", en:"Part of the excellence of a person’s Islam is leaving what does not concern him."},
  {cat:'Akhlaq', src:"Sahih Bukhari 6116", txt:"Ek shakhs ne Nabi ﷺ se naseehat maangi. Aap ﷺ ne farmaya: ghussa na kiya karo. Usne kai baar poochha, aap ﷺ ne har baar yahi farmaya: ghussa na kiya karo.", en:"A man asked the Prophet ﷺ for advice. He said: Do not become angry. The man repeated it several times, and each time he said: Do not become angry."},
  {cat:'Akhlaq', src:"Sahih Bukhari 13, Sahih Muslim 45", txt:"Tum mein se koi us waqt tak (kamil) momin nahi hota jab tak apne bhai ke liye wahi pasand na kare jo apne liye pasand karta hai.", en:"None of you truly believes until he loves for his brother what he loves for himself."},
  {cat:'Akhlaq', src:"Jami’ at-Tirmidhi 1919", txt:"Jo hamare chhoton par raham na kare aur hamare badon ka haq na pehchane, wo humse (hamare tareeqe par) nahi.", en:"He is not one of us who does not show mercy to our young ones and recognize the right of our elders."},
  {cat:'Akhlaq', src:"Sahih Bukhari 5971, Sahih Muslim 2548", txt:"Ek shakhs ne poochha: meri achhi sohbat ka sabse zyada haqdar kaun hai? Farmaya: teri maa. Usne poochha: phir? Farmaya: teri maa. Usne poochha: phir? Farmaya: teri maa. Usne poochha: phir? Farmaya: tera baap.", en:"A man asked: Who deserves my good company the most? He said: Your mother. He asked: Then? Your mother. Then? Your mother. Then? Your father."},
  {cat:'Akhlaq', src:"Sahih Bukhari 5973", txt:"Kabeera gunahon mein se ye bhi hai ke aadmi apne walidain ko bura-bhala kahe. Poochha gaya: koi apne walidain ko kaise bura kahega? Farmaya: wo kisi ke baap ko bura kehta hai to wo uske baap ko bura kehta hai.", en:"Among the major sins is a man cursing his parents. It was asked: How can he curse his parents? He said: He insults another man’s father, and that man insults his father."},
  {cat:'Akhlaq', src:"Jami’ at-Tirmidhi 1924, Sunan Abu Dawood 4941", txt:"Raham karne walon par Rahman raham farmata hai. Zameen walon par raham karo, aasman wala tum par raham karega.", en:"The Most Merciful shows mercy to those who are merciful. Show mercy to those on earth, and the One above the heavens will show mercy to you."},
  {cat:'Akhlaq', src:"Sahih Bukhari 7376, Sahih Muslim 2319", txt:"Jo logon par raham nahi karta, Allah us par raham nahi karta.", en:"Allah does not show mercy to the one who does not show mercy to people."},
  {cat:'Akhlaq', src:"Sahih Muslim 54", txt:"Tum Jannat mein us waqt tak dakhil nahi hoge jab tak imaan na lao, aur tum us waqt tak momin nahi ho sakte jab tak ek doosre se mohabbat na karo. Kya main tumhein wo cheez na bataun jis par amal karne se tum mein mohabbat badh jaye? Apne darmiyan salam ko aam karo.", en:"You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you something that, if you do it, you will love one another? Spread salam among yourselves."},
  {cat:'Akhlaq', src:"Sahih Bukhari 2989, Sahih Muslim 1009", txt:"Achhi baat bhi sadqa hai.", en:"A good word is charity."},
  {cat:'Akhlaq', src:"Sahih Bukhari 6117, Sahih Muslim 37", txt:"Haya sirf bhalai hi lekar aati hai.", en:"Modesty brings nothing but good."},
  {cat:'Akhlaq', src:"Jami’ at-Tirmidhi 1977 (Hasan)", txt:"Momin taana dene wala, laanat karne wala, fahish aur bad-zabaan nahi hota.", en:"The believer is not one who taunts, curses, or uses foul and vulgar speech."},
  {cat:'Akhlaq', src:"Sahih Bukhari 5985, Sahih Muslim 2557", txt:"Jo chahta hai ke uske rizq mein kushaadgi aur umr mein barkat ho, wo silah-rehmi (rishtedaron se achha sulook) kare.", en:"Whoever wishes for his provision to be expanded and his life to be extended should keep good ties with his relatives."},
  {cat:'Akhlaq', src:"Sahih Muslim 2564", txt:"Ek doosre se hasad na karo, dhoka na do, nafrat na rakho, aur ek doosre se munh na phero. Ae Allah ke bando, aapas mein bhai bhai ban jao. Musalman Musalman ka bhai hai, na us par zulm kare, na use be-yaar-o-madadgaar chhode, na use haqeer jaane.", en:"Do not envy one another, do not cheat one another, do not hate one another, and do not turn away from one another. Be servants of Allah, brothers. A Muslim is the brother of a Muslim: he does not wrong him, abandon him, or despise him."},
  {cat:"Zikr", src:"Sahih Bukhari, Sahih Muslim", txt:"Do kalimaat zubaan par halke hain, mizaan mein bhaari hain aur Rahman ko bohat pyare hain: SubhanAllahi wa bihamdihi, SubhanAllahil Azeem.", en:"Two phrases are light on the tongue, heavy on the scale and beloved to the Most Merciful: SubhanAllahi wa bihamdihi, SubhanAllahil Azeem.", exp:"Zikr bolne mein aasaan hai magar sawab bohat hai. Chhota amal bhi Allah ki rehmat se bada ban jata hai.", enexp:"Dhikr is easy to say but its reward is great. By Allah's mercy even a small deed becomes heavy.", sc:"beads"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Bad-gumani se bacho, kyunki bad-gumani sabse jhooti baat hai.", en:"Avoid suspicion, for suspicion is the most false of speech.", exp:"Bina tehqeeq ke kisi ke baare mein bura gumaan rishte aur dil kharab karta hai. Doosron ke baare mein achha gumaan rakhein.", enexp:"Unverified assumptions about others damage hearts and relationships. Give people the benefit of the doubt.", sc:"cloudBreak"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Insaan kabhi bina soche aisi baat keh deta hai jo Allah ko pasand aati hai, to Allah uske darje buland karta hai. Aur kabhi bina soche aisi baat keh deta hai jo Allah ko naraaz karti hai, to wo jahannam mein gir jata hai.", en:"A person may say a word without thinking that pleases Allah and is raised in rank, and another that displeases Allah and sinks into Hell because of it.", exp:"Bolne se pehle sochein. Zubaan ek lamha mein nek bhi bana sakti hai aur tabah bhi.", enexp:"Think before you speak. The tongue can bring either success or ruin in a moment.", sc:"speech"},
  {cat:"Imaan", src:"Sahih Bukhari, Sahih Muslim", txt:"Allah ko ghairat aati hai, aur Allah ki ghairat ye hai ke momin wo kaam kare jo Allah ne haram kiya hai.", en:"Allah has ghayrah (sacred protectiveness), and His ghayrah is that a believer does what Allah has forbidden.", exp:"Momin jaanta hai isliye use gunah se aur zyada bachna chahiye. Allah ki sifaat ko bina kisi makhlooq se mushabihat ke maanein.", enexp:"A believer knows better, so he should guard against sin even more. Affirm Allah's attributes without comparing them to creation.", sc:"lock"},
  {cat:"Ramzan", src:"Sahih Bukhari, Sahih Muslim", txt:"Jo imaan aur sawab ki ummeed se Ramzan mein raat ki namaz (Taraweeh) padhe, uske pichle gunah maaf kar diye jate hain.", en:"Whoever prays at night in Ramadan out of faith and hoping for reward will have his past sins forgiven.", exp:"Shart imaan aur ikhlas hai. Ye maafi Allah ke haqooq ki hai, bandon ke haq ke liye wapsi ya maafi zaroori hai.", enexp:"Faith and sincerity are required. This covers rights of Allah; wrongs to people need restitution or pardon.", sc:"bookNight"},
  {cat:"Ibadat", src:"Sahih Bukhari, Sahih Muslim", txt:"Ek Umrah doosre Umrah tak ke gunahon ka kaffara hai, aur maqbool Hajj ka badla Jannat ke siwa kuch nahi.", en:"One Umrah to the next expiates what is between them, and an accepted Hajj has no reward but Paradise.", exp:"Chhote gunah maaf hote hain; bade gunahon ke liye sachchi tauba zaroori hai. Maqbool Hajj wo hai jo ikhlas se aur gunah se bach kar kiya jaye.", enexp:"Minor sins are forgiven; major sins need sincere repentance. An accepted Hajj is done sincerely and without sin.", sc:"kaaba"},
  {cat:"Aadaab", src:"Sahih Bukhari, Sahih Muslim", txt:"Jamhai (ubasi) shaitan ki taraf se hai, to jahan tak ho sake use rokein.", en:"Yawning is from Shaytan, so suppress it as much as you can.", exp:"Jamhai susti ki alaamat hai jisse shaitan faida uthata hai. Nek kaamon ke liye chust rahein.", enexp:"Yawning shows laziness, which Shaytan exploits. Stay energetic for good deeds.", sc:"sleep"},
  {cat:"Sadqa", src:"Sahih Bukhari, Sahih Muslim", txt:"Bewa aur miskeen ki madad ke liye koshish karne wala Allah ki raah mein jihad karne wale jaisa hai, ya us jaisa jo raat bhar namaz padhe aur hamesha roza rakhe.", en:"One who strives to help the widow and the poor is like a fighter in Allah's cause, or like one who prays all night and fasts continually.", exp:"Kamzoron ki madad ka sawab bohat bada hai. Jo khud nahi kar sakta wo doosron ki madad karke ye ajr pa sakta hai.", enexp:"Helping the vulnerable has great reward. Even those who cannot do much can earn it by helping others.", sc:"hands"},
  {cat:"Imaan", src:"Sahih Bukhari, Sahih Muslim", txt:"Musalman ko jo bhi takleef pahunche, yahan tak ke kaanta bhi chubhe, Allah uske badle uske gunah mita deta hai.", en:"Whatever hardship befalls a Muslim, even a thorn prick, Allah erases some of his sins because of it.", exp:"Sabr aur sawab ki ummeed ke saath takleef bhi rehmat ban jati hai.", enexp:"Hardship met with patience and hope for reward becomes a mercy.", sc:"rainBreak"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Musalman ke Musalman par paanch haq hain: salam ka jawab dena, beemar ki iyadat karna, janaze ke saath jana, dawat qabool karna aur chheenk ka jawab dena.", en:"A Muslim has five rights over another: returning the greeting, visiting the sick, following funerals, accepting invitations and replying to a sneeze.", exp:"Ye haq aapas ki mohabbat aur ittehad badhate hain. Har haq ke masail apne aalim se poochh sakte hain.", enexp:"These rights build love and unity among Muslims.", sc:"hands"},
  {cat:"Ibadat", src:"Sahih Bukhari, Sahih Muslim", txt:"Jo janaze ki namaz padhe use ek qirat sawab milta hai, aur jo dafan tak ruke use do qirat, jo do bade pahaadon ke barabar hain.", en:"Whoever prays the funeral prayer earns one qirat, and whoever stays until burial earns two, like two great mountains.", exp:"Thodi si mehnat par bada sawab. Janaze mein shirkat mayyit aur uske ghar walon ka haq hai.", enexp:"A small effort earns a great reward. Attending a funeral honors the deceased and the family.", sc:"mountain"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Nabi ﷺ ne kabhi khane mein ayb nahi nikala. Pasand aaya to kha liya, nahi to chhod diya.", en:"The Prophet ﷺ never criticized any food. If he liked it he ate it, and if not he left it.", exp:"Allah ki di hui rozi ki qadar karein. Pasand na aaye to chhod dein ya kisi ko de dein, burai na karein.", enexp:"Respect Allah's provision. If you dislike a food, leave it or give it away without criticizing it.", sc:"plate"},
  {cat:"Imaan", src:"Sahih Bukhari, Sahih Muslim", txt:"Jahannam ko khwahishaat se aur Jannat ko mushkilon se gher diya gaya hai.", en:"Hell is surrounded by desires and Paradise is surrounded by hardships.", exp:"Haram khwahishon se rukna aur ibadat ki mushkil bardasht karna Jannat ka raasta hai. Sirf tamanna kaafi nahi.", enexp:"Resisting forbidden desires and enduring the effort of obedience lead to Paradise. Wishing alone is not enough.", sc:"path"},
  {cat:"Namaz", src:"Sahih Bukhari, Sahih Muslim", txt:"Juma ke khutba ke dauran agar tune apne saathi se 'chup raho' kaha, to tune lagv (faltu) baat ki.", en:"If you tell your companion 'Be quiet' while the imam is giving the Friday sermon, you have engaged in idle talk.", exp:"Khutba ke dauran baat karna mana hai, isharay se chup karana behtar hai. Ulama is hukm ki sakhti mein kuch ikhtilaf rakhte hain.", enexp:"Speaking during the sermon is discouraged. Scholars differ on how strict the ruling is.", sc:"masjidIn"},
  {cat:"Namaz", src:"Sahih Bukhari, Sahih Muslim", txt:"Agar meri ummat par mushkil na hoti to main har namaz ke saath miswak ka hukm deta.", en:"Had it not been hard on my ummah, I would have ordered the siwak with every prayer.", exp:"Munh ki safai ka shauq dilaya gaya. Nabi ﷺ ne ibadat ko ummat par bojh banne se bachaya.", enexp:"It encourages oral hygiene. The Prophet ﷺ avoided making worship burdensome.", sc:"tap"},
  {cat:"Namaz", src:"Sahih Bukhari, Sahih Muslim", txt:"Nabi ﷺ ne ek shakhs ko dekha jisne wuzu mein apni edi sookhi chhod di thi, to farmaya: in edion ke liye aag ki tabahi hai.", en:"The Prophet ﷺ saw a man who had left his heels dry in wudu and said: Woe to the heels from the Fire.", exp:"Wuzu mein har hissa poori tarah dhona zaroori hai. Seekhne wale ko dohrana aur sakhti se samjhana jaiz hai.", enexp:"Every required part must be washed fully. Teaching with repetition and firmness is allowed.", sc:"tap"},
  {cat:"Namaz", src:"Sahih Bukhari, Sahih Muslim", txt:"Kya wo shakhs jo imam se pehle sar uthata hai is baat se nahi darta ke Allah uska sar gadhe ka sar bana de?", en:"Does the one who raises his head before the imam not fear that Allah may turn his head into the head of a donkey?", exp:"Namaz mein imam ki pairwi zaroori hai, usse aage nikalna mana hai. Gadha susti aur na-samajhi ki misaal hai.", enexp:"One must follow the imam, not precede him. The donkey is a symbol of dullness.", sc:"rows"},
  {cat:"Namaz", src:"Sahih Bukhari, Sahih Muslim", txt:"Jo shakhs subah ya shaam masjid jaye, Allah uske liye har baar Jannat mein mehmaani ka saamaan taiyyar karta hai.", en:"Whoever goes to the mosque morning or evening, Allah prepares for him a place in Paradise each time he goes.", exp:"Masjid ki pabandi se Jannat mein izzat wala maqam milta hai.", enexp:"Regular mosque attendance earns an honored place in Paradise.", sc:"masjidOut"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Munafiq ki teen nishaniyan hain: baat kare to jhoot bole, wada kare to tod de, aur amanat di jaye to khayanat kare.", en:"The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, and when trusted he betrays.", exp:"Ye amali nifaq hai, imaan se nikal dene wala kufr nahi. Momin ko in aadaton se bachna chahiye.", enexp:"This refers to hypocrisy in conduct, not disbelief. A believer must avoid these traits.", sc:"lock"},
  {cat:"Akhlaq", src:"Sahih Bukhari", txt:"Tehband (izaar) ka jo hissa takhnon se neeche ho wo aag mein hai.", en:"The part of the lower garment that hangs below the ankles is in the Fire.", exp:"Is hukm ki tafseel mein ulama ka ikhtilaf hai, baaz ke nazdeek takabbur ki shart ke saath hai. Apne aalim se poochh lein.", enexp:"Scholars differ on the details of this ruling; many link it to arrogance. Ask your scholar.", sc:"mirror"},
  {cat:"Namaz", src:"Sahih Bukhari", txt:"Banda jab tak apni namaz ki jagah par wuzu ke saath baitha rehta hai, farishte uske liye dua karte rehte hain: ae Allah ise bakhsh de, ae Allah is par raham farma.", en:"Angels keep praying for one who stays in his place of prayer in a state of wudu: O Allah forgive him, O Allah have mercy on him.", exp:"Namaz ke intezar ki fazilat. Maghfirat gunahon ko dhak deti hai aur rehmat Allah ki meherbani hai.", enexp:"The virtue of waiting for prayer. Forgiveness covers sins and mercy is Allah's kindness.", sc:"lamp"},
  {cat:"Imaan", src:"Sahih Bukhari", txt:"Meri poori ummat Jannat mein jayegi magar jisne inkaar kiya. Poochha gaya: inkaar kaun karega? Farmaya: jisne meri itaa'at ki wo Jannat mein gaya, aur jisne meri nafarmani ki usne inkaar kiya.", en:"All my ummah will enter Paradise except those who refuse. They asked: Who would refuse? He said: Whoever obeys me enters Paradise, and whoever disobeys me has refused.", exp:"Nabi ﷺ ki itaa'at Jannat ka raasta hai. Ulama ne 'ummat' ke mafhoom par baat ki hai.", enexp:"Obeying the Prophet ﷺ leads to Paradise.", sc:"gate"},
  {cat:"Akhlaq", src:"Sahih Bukhari", txt:"Jo apne bhai ko kafir kahe to ye baat un dono mein se ek par laut aati hai.", en:"If a man calls his brother a disbeliever, the charge returns to one of them.", exp:"Bina daleel kisi par kufr ka hukm na lagayein. Naseehat narmi se karein, galat ilzaam kehne wale par palat sakta hai.", enexp:"Do not judge anyone without proof. Advise gently; a false accusation returns to the accuser.", sc:"scale"},
  {cat:"Tauba", src:"Sahih Muslim", txt:"Allah ko bande ki tauba se us musafir ki khushi se bhi zyada khushi hoti hai jise sehra mein apna khoya hua oont mil jaye.", en:"Allah is more pleased with the repentance of His servant than a traveler who finds his lost camel in the desert.", exp:"Tauba ka darwaza maut ya sooraj maghrib se nikalne tak khula hai.", enexp:"The door of repentance stays open until death or until the sun rises from the west.", sc:"rain"},
  {cat:"Namaz", src:"Sahih Muslim", txt:"Paanch namazein, ek Juma doosre Juma tak, aur ek Ramzan doosre Ramzan tak, beech ke gunahon ka kaffara hain, jab tak bade gunahon se bacha jaye.", en:"The five prayers, Friday to Friday and Ramadan to Ramadan expiate what is between them, as long as major sins are avoided.", exp:"Ye chhote gunahon ka kaffara hain. Bade gunahon ke liye tauba zaroori hai.", enexp:"These expiate minor sins; major sins need repentance.", sc:"cloudBreak"},
  {cat:"Ibadat", src:"Sahih Muslim", txt:"Ramzan ke baad sabse afzal roza Allah ke mahine Muharram ka hai, aur farz ke baad sabse afzal namaz raat ki namaz hai.", en:"The best fasting after Ramadan is in Allah's month of Muharram, and the best prayer after the obligatory is the night prayer.", exp:"Pehle farz, phir nafl. Muharram muhtaram mahina hai. Raat ki namaz zyada ikhlas aur dil jami ki hoti hai.", enexp:"Obligations come first. Muharram is a sacred month. Night prayer is more sincere and focused.", sc:"calendar"},
  {cat:"Tauba", src:"Sahih Muslim", txt:"Jo sooraj ke maghrib se nikalne se pehle tauba kare, Allah uski tauba qabool farmata hai.", en:"Whoever repents before the sun rises from the west, Allah accepts his repentance.", exp:"Tauba mein jaldi karein. Is nishani ke baad ya jaan nikalte waqt tauba qabool nahi hoti.", enexp:"Hasten to repent. Repentance is not accepted after that sign or at the moment of death.", sc:"rain"},
  {cat:"Aadaab", src:"Sahih Muslim", txt:"Moonchhein kaato, daadhi badhao aur majoosiyon ki mukhalifat karo.", en:"Trim the mustache, let the beard grow, and differ from the Magians.", exp:"Musalmanon ko apni alag pehchan rakhni chahiye. Daadhi ki miqdar mein ulama ka ikhtilaf hai; Hanafi fiqh mein ek muththi tak rakhna wajib hai.", enexp:"Muslims should keep a distinct identity. Scholars differ on the beard's measure; Hanafi fiqh requires at least a fist's length.", sc:"mirror"},
  {cat:"Zikr", src:"Sahih Muslim", txt:"SubhanAllah, Alhamdulillah, La ilaha illallah aur Allahu Akbar kehna mujhe un sab cheezon se zyada pyara hai jin par sooraj nikalta hai.", en:"Saying SubhanAllah, Alhamdulillah, La ilaha illallah and Allahu Akbar is dearer to me than everything the sun rises upon.", exp:"In chaar kalimon mein Allah ki paaki, hamd, tauheed aur badai sab aa jati hai.", enexp:"These four phrases gather Allah's glorification, praise, oneness and greatness.", sc:"beads"},
  {cat:"Akhlaq", src:"Sahih Muslim", txt:"Jo hum par hathiyar uthaye wo hum mein se nahi, aur jo hamein dhoka de wo bhi hum mein se nahi.", en:"Whoever carries arms against us is not one of us, and whoever deceives us is not one of us.", exp:"Khoon-reizi bohat bada gunah hai, aur Musalmanon ko dhoka dena bhi sakht gunah hai.", enexp:"Bloodshed is a grave sin, and deceiving Muslims is also gravely condemned.", sc:"scale"},
  {cat:"Sadqa", src:"Sahih Muslim", txt:"Insaan mar jata hai to uske amal ruk jate hain magar teen: sadqa-e-jaariya, wo ilm jisse faida uthaya jaye, aur nek aulad jo uske liye dua kare.", en:"When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, and a righteous child who prays for him.", exp:"Faida mand ilm aur nek aulad ki dua marne ke baad bhi pahunchti hai.", enexp:"Beneficial knowledge and a child's prayers continue to benefit a person after death.", sc:"sprout"},
  {cat:"Ibadat", src:"Sahih Muslim", txt:"Apne marne wale (qareeb-ul-marg) ko 'La ilaha illallah' ki talqeen karo.", en:"Prompt your dying ones to say La ilaha illallah.", exp:"Qareeb-ul-marg ko narmi se kalima yaad dilayein. Baar-baar kehkar pareshan na karein.", enexp:"Remind the dying gently. Do not distress him by repeating too much.", sc:"dove"},
  {cat:"Ilm", src:"Sahih Muslim", txt:"Jo jaan-boojh kar mujh par jhoot bandhe wo apna thikana jahannam mein bana le.", en:"Whoever deliberately lies about me should take his seat in the Fire.", exp:"Nabi ﷺ ke naam se jhooti baat kehna bohat bada gunah hai. Be-tehqeeq hadees aage na bhejein.", enexp:"Lying about the Prophet ﷺ is a grave sin. Do not pass on unverified hadith.", sc:"book"},
  {cat:"Ilm", src:"Sahih Muslim", txt:"Jo hidayat ki taraf bulaye use un sab ke barabar ajr milta hai jo uski pairwi karein, aur jo gumrahi ki taraf bulaye use un sab ke barabar gunah milta hai.", en:"Whoever calls to guidance gets a reward like those who follow him, and whoever calls to misguidance bears a sin like those who follow him.", exp:"Achhi baat phailayein aur bure raaste ki taraf na bulayein. Asar bohat door tak jata hai.", enexp:"Spread good and never invite to wrong. Influence travels far.", sc:"lanterns"},
  {cat:"Imaan", src:"Sahih Muslim", txt:"Allah farmata hai: main shirk se sabse zyada be-niyaz hoon. Jo koi amal kare aur usme mere saath kisi aur ko shareek kare, main use aur uske shirk ko chhod deta hoon.", en:"Allah says: I am the most free of partners. Whoever does a deed and associates another with Me in it, I leave him and that partner.", exp:"Dikhawa chhota shirk hai. Ibadat sirf Allah ke liye ikhlas se karein.", enexp:"Showing off is minor shirk. Worship for Allah alone, sincerely.", sc:"light"},
  {cat:"Zikr", src:"Sahih Muslim", txt:"Jo mujh par ek baar durood bheje, Allah us par das rehmatein bhejta hai.", en:"Whoever sends one blessing upon me, Allah sends ten upon him.", exp:"Durood ka sawab kai guna badh kar milta hai.", enexp:"The reward of durood is multiplied many times.", sc:"dove"},
  {cat:"Akhlaq", src:"Sahih Muslim", txt:"Har Musalman ka khoon, maal aur izzat doosre Musalman par haram hai.", en:"A Muslim's blood, wealth and honor are forbidden to another Muslim.", exp:"Zubaan aur haath dono se takleef dena mana hai. Musalman ki hurmat bohat badi hai.", enexp:"Harming by tongue or hand is forbidden. The sanctity of a Muslim is great.", sc:"lock"},
  {cat:"Sadqa", src:"Sahih Muslim", txt:"Sadqa maal ko kam nahi karta, maaf karne se Allah izzat badhata hai, aur jo Allah ke liye aajzi kare Allah use buland karta hai.", en:"Charity does not decrease wealth, forgiveness increases honor, and whoever humbles himself for Allah, Allah raises him.", exp:"Sadqa maal ko paak karta hai. Maaf karne wala izzat pata hai. Aajzi takabbur ki ulti hai.", enexp:"Charity purifies wealth, forgiveness earns esteem, and humility is the opposite of arrogance.", sc:"coins"},
  {cat:"Akhlaq", src:"Sahih Muslim", txt:"Gheebat ye hai ke tum apne bhai ka zikr aise tareeqe se karo jo use bura lage. Agar baat sach ho to gheebat hai, aur jhooti ho to buhtaan hai.", en:"Backbiting is mentioning your brother in a way he dislikes. If it is true, it is backbiting, and if false, it is slander.", exp:"Gheebat kabeera gunah hai, kuch jaiz soortein bhi hain. Qur'an 49:12 mein is se mana kiya gaya hai.", enexp:"Backbiting is a major sin with a few permitted exceptions. It is forbidden in Qur'an 49:12.", sc:"speech"},
  {cat:"Zikr", src:"Sahih Muslim", txt:"Mufarridoon aage nikal gaye: wo mard aur auratein jo Allah ko bohat yaad karte hain.", en:"The mufarridun have gone ahead: men and women who remember Allah often.", exp:"Zikr ki kasrat se insaan ka maqam buland hota hai. Zikr ki kai soortein hain.", enexp:"Frequent remembrance raises a person's rank. Dhikr takes many forms.", sc:"beads"},
  {cat:"Imaan", src:"Sahih Muslim", txt:"Allah tumhari shakalon aur maal ko nahi dekhta, wo tumhare dilon aur amal ko dekhta hai.", en:"Allah does not look at your faces or wealth, but at your hearts and deeds.", exp:"Taqwa asal mayaar hai. Fakhr na karein, niyyat aur ikhlas par tawajjoh dein.", enexp:"Piety is the true measure. Do not boast; focus on intention and sincerity.", sc:"heart"},
  {cat:"Zikr", src:"Sahih Muslim", txt:"Apne gharon ko qabristan na banao. Shaitan us ghar se bhaagta hai jis mein Surah Baqarah padhi jati hai.", en:"Do not make your houses graves. Shaytan flees from the house in which Surah al-Baqarah is recited.", exp:"Gharon mein ibadat aur Qur'an ki tilawat rakhein.", enexp:"Keep worship and Qur'an recitation in your homes.", sc:"house"},
  {cat:"Akhlaq", src:"Sahih Muslim", txt:"Wo Jannat mein dakhil nahi hoga jiska padosi uske shar se mehfooz na ho.", en:"He will not enter Paradise whose neighbor is not safe from his harm.", exp:"Padosi ke haq bohat bade hain, chahe rishtedar ho ya ajnabi, Musalman ho ya nahi. Ye sakht tambeeh hai.", enexp:"Neighbors' rights are great, whether relatives or strangers, Muslim or not. This is a severe warning.", sc:"house"},
  {cat:"Namaz", src:"Sahih Muslim", txt:"Banda apne Rab ke sabse qareeb sajde mein hota hai, to sajde mein bohat dua karo.", en:"A servant is closest to his Lord when he is prostrating, so make plenty of supplication in it.", exp:"Sajda aajzi ka maqam hai aur dua ki qabooliyat ka khaas waqt.", enexp:"Prostration is the station of humility and a prime time for accepted supplication.", sc:"mat"},
  {cat:"Ilm", src:"Sahih Muslim", txt:"Jo ilm ki talash mein raasta chale, Allah uske liye Jannat ka raasta aasan kar deta hai.", en:"Whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise.", exp:"Safar karna ya khaas ilm hasil karna dono shaamil hain. Allah nek kaam asaan farmata hai.", enexp:"This includes both physical journeys and the pursuit of learning. Allah eases righteous deeds.", sc:"path"},
  {cat:"Akhlaq", src:"Sahih Muslim", txt:"Qayamat ke din Allah farmayega: wo log kahan hain jo mere jalaal ke liye ek doosre se mohabbat karte the? Aaj main unhe apne saaye mein rakhunga, jis din mere saaye ke siwa koi saaya nahi.", en:"On the Day of Resurrection Allah will say: Where are those who loved each other for My glory? Today I shade them in My shade, when there is no shade but Mine.", exp:"Allah ke liye mohabbat bohat mazboot rishta hai. Ye Arsh ke saaye ki taraf ishara hai.", enexp:"Love for Allah's sake is a strong bond. The shade refers to the shade of His Throne.", sc:"hands"},
  {cat:"Namaz", src:"Sahih Muslim", txt:"Jab farz namaz ki iqamat ho jaye to uske siwa koi (nafl) namaz nahi.", en:"When the iqamah for the obligatory prayer is called, there is no prayer except the obligatory one.", exp:"Farz ko pehle ahmiyat dein. Hanafi fiqh mein Fajr ki sunnat ka alag hukm hai, apne aalim se poochh lein.", enexp:"The obligatory prayer takes priority. Hanafi fiqh has a special ruling for the Fajr sunnah; ask a scholar.", sc:"clock"},
  {cat:"Imaan", src:"Sahih Muslim", txt:"Duniya momin ke liye qaid-khana aur kafir ke liye Jannat hai.", en:"The world is a prison for the believer and a paradise for the disbeliever.", exp:"Momin imaan ki hudood aur azmaishon mein rehta hai, aur asal maqsad aakhirat hai.", enexp:"The believer lives within the limits of faith and trials; the real goal is the Hereafter.", sc:"gate"},
  {cat:"Ibadat", src:"Sahih Bukhari, Sahih Muslim", txt:"Poori koshish karo aur darmiyani raah apnao. Koi shakhs sirf apne amal se Jannat mein nahi jayega. Allah ko sabse pyara amal wo hai jo hamesha kiya jaye, chahe thoda ho.", en:"Strive and be moderate. No one enters Paradise by his deeds alone. The most beloved deed to Allah is the most regular, even if small.", exp:"Amal Jannat ka sabab hai, qeemat nahi; Allah ki rehmat zaroori hai. Lagataar chhota amal behtar hai.", enexp:"Deeds are a cause, not a price; Allah's mercy is needed. Consistency matters more than quantity.", sc:"path"},
  {cat:"Imaan", src:"Sahih Bukhari, Sahih Muslim", txt:"Amal ka daaromadar niyyaton par hai, aur har shakhs ko wahi milta hai jis ki usne niyyat ki.", en:"Actions are judged by intentions, and each person gets what he intended.", exp:"Achhe kaam ke saath achhi niyyat zaroori hai, warna sawab nahi milta.", enexp:"A good deed needs a good intention to earn reward.", sc:"heart"},
  {cat:"Aadaab", src:"Sahih Bukhari, Sahih Muslim", txt:"Paaki aadha imaan hai.", en:"Cleanliness is half of faith.", exp:"Badan, kapde aur jagah ki safai ibadat ka hissa hai.", enexp:"Cleanliness of body, clothes and place is part of worship.", sc:"tap"},
  {cat:"Aadaab", src:"Sahih Bukhari, Sahih Muslim", txt:"Momin najis nahi hota.", en:"A believer is never impure.", exp:"Momin ko napaak samajh kar door na karein. Insaan ka badan napaak nahi hota jab tak koi najasat na lagi ho.", enexp:"Do not avoid a believer as if he were unclean. A person's body is not impure unless something impure touches it.", sc:"tap"},
  {cat:"Namaz", src:"Sahih Muslim", txt:"Namaz noor hai.", en:"Prayer is light.", exp:"Namaz dil ko roshni aur raasta deti hai.", enexp:"Prayer brings light and guidance to the heart.", sc:"lamp"},
  {cat:"Ilm", src:"Sahih Bukhari", txt:"Tum mein sabse behtar wo hai jo Qur'an seekhe aur doosron ko seekhaye.", en:"The best of you are those who learn the Qur'an and teach it.", exp:"Qur'an seekhna aur sikhana sabse badi fazilat hai.", enexp:"Learning and teaching the Qur'an is among the greatest virtues.", sc:"book"},
  {cat:"Imaan", src:"Sahih Bukhari", txt:"Surah Ikhlas Qur'an ke teesre hisse ke barabar hai.", en:"Surah al-Ikhlas equals a third of the Qur'an.", exp:"Is mein tauheed ka poora bayan hai, isliye iska sawab bohat bada hai.", enexp:"It fully declares Allah's oneness, so its reward is great.", sc:"light"},
  {cat:"Imaan", src:"Sahih Muslim", txt:"Deen khair-khwahi (naseehat) ka naam hai.", en:"Religion is sincere well-wishing.", exp:"Allah, uski kitab, Rasool ﷺ, hukmranon aur aam Musalmanon ke liye sachchi khair-khwahi karein.", enexp:"Be sincere toward Allah, His Book, His Messenger ﷺ, the leaders and all Muslims.", sc:"hands"},
  {cat:"Sadqa", src:"Sahih Bukhari, Sahih Muslim", txt:"Har nek kaam sadqa hai.", en:"Every good deed is charity.", exp:"Muskurana, achhi baat kehna, raaste se kaanta hataana, sab sadqa hain.", enexp:"A smile, a kind word, removing a thorn from the road are all charity.", sc:"smile"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Chugal-khor Jannat mein nahi jayega.", en:"The slanderer (namimah) will not enter Paradise.", exp:"Ek ki baat doosre tak fasad ke liye pahunchana bohat bura hai.", enexp:"Carrying words between people to cause strife is a grave sin.", sc:"speech"},
  {cat:"Ilm", src:"Sahih Bukhari", txt:"Meri taraf se (meri baat) pahuncha do, chahe ek aayat hi ho.", en:"Convey from me, even if it is one verse.", exp:"Jitna jaante ho utna doosron tak sahi tareeqe se pahunchao.", enexp:"Convey what you know to others, accurately.", sc:"lanterns"},
  {cat:"Ramzan", src:"Sahih Bukhari, Sahih Muslim", txt:"Roza dhaal hai.", en:"Fasting is a shield.", exp:"Roza gunahon aur burai se bachata hai. Roze mein bad-zabani aur ladai se bhi bachein.", enexp:"Fasting protects from sin. Avoid foul speech and quarrels while fasting.", sc:"iftar"},
  {cat:"Ibadat", src:"Sahih Muslim", txt:"Qayamat ke din muazzinon ki gardanein sabse lambi hongi.", en:"On the Day of Resurrection the muezzins will have the longest necks.", exp:"Azaan dene ki bohat badi fazilat hai.", enexp:"Calling the adhan has great virtue.", sc:"call"},
  {cat:"Aadaab", src:"Sahih Bukhari", txt:"Raaston par baithne se bacho. Agar baithna hi ho to raaste ka haq adaa karo: nazar jhukao, takleef na do, salam ka jawab do aur achhai ka hukm do.", en:"Avoid sitting on the roads. If you must, give the road its right: lower your gaze, avoid harming others, return the greeting and enjoin good.", exp:"Raaste mein baithne se aane jaane walon ko takleef ho sakti hai. Haq adaa karna zaroori hai.", enexp:"Sitting on roads can trouble passers-by, so the road's rights must be observed.", sc:"road"},
  {cat:"Sadqa", src:"Sahih Bukhari", txt:"Aag se bacho, chahe khajoor ke ek tukde se hi ho.", en:"Protect yourself from the Fire, even with half a date.", exp:"Chhote sadqe ko haqeer na samjhein.", enexp:"Never think a small charity is too little.", sc:"coins"},
  {cat:"Aadaab", src:"Sahih Muslim", txt:"Zamane ko bura na kaho, kyunki sab kuch Allah ke hukm se hota hai.", en:"Do not curse time, for everything happens by Allah's command.", exp:"Museebat ya muddat ko bura kehna asal mein taqdeer ko bura kehna hai.", enexp:"Cursing time or hardship is really complaining about Allah's decree.", sc:"hourglass"},
  {cat:"Aadaab", src:"Sahih Bukhari", txt:"Nabi ﷺ tek lagakar khana nahi khaate the.", en:"The Prophet ﷺ did not eat while reclining.", exp:"Khane mein aajzi aur sunnat ka khayal rakhein.", enexp:"Eat humbly and follow the sunnah.", sc:"plate"},
  {cat:"Aadaab", src:"Sahih Muslim", txt:"Seedhe haath se khao.", en:"Eat with your right hand.", exp:"Khane pine mein seedha haath istemal karna sunnat hai.", enexp:"Using the right hand for eating and drinking is sunnah.", sc:"plate"},
  {cat:"Imaan", src:"Sahih Muslim", txt:"Allah khoobsurat hai aur khoobsurati ko pasand karta hai.", en:"Allah is beautiful and loves beauty.", exp:"Saaf-suthre rehna, achhe kapde aur achha rawayya sab khoobsurati hai. Takabbur ek alag cheez hai.", enexp:"Cleanliness, tidy clothes and good conduct are beauty. Arrogance is something else.", sc:"flower"},
  {cat:"Aadaab", src:"Sahih Bukhari", txt:"Nabi ﷺ ne qabron ko pakka (chuna) karne se mana farmaya.", en:"The Prophet ﷺ forbade plastering graves.", exp:"Qabron ko saada rakhna chahiye.", enexp:"Graves should be kept simple.", sc:"cloudBreak"},
  {cat:"Aadaab", src:"Sahih Bukhari", txt:"Allah ke siwa kisi aur ki qasam na khao.", en:"Do not swear by anything except Allah.", exp:"Qasam sirf Allah ke naam ki khayi jati hai. Jhooti qasam se bachein.", enexp:"Oaths are only taken in Allah's name. Avoid false oaths.", sc:"scale"},
  {cat:"Sadqa", src:"Sahih Bukhari", txt:"Yateem ki parwarish karne wala aur main Jannat mein aise saath honge. Aur Aap ﷺ ne shahadat aur beech ki ungli milakar dikhayi.", en:"The one who cares for an orphan and I will be together in Paradise like this, and he held his index and middle fingers together.", exp:"Yateem ki parwarish ka bohat bada ajr hai, Nabi ﷺ ka saath.", enexp:"Caring for an orphan has immense reward: closeness to the Prophet ﷺ.", sc:"hands"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Haya imaan ka hissa hai.", en:"Modesty is part of faith.", exp:"Haya insaan ko burai se rokti hai.", enexp:"Modesty keeps a person from wrongdoing.", sc:"light"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Zulm Qayamat ke din andheron ka sabab hoga.", en:"Oppression will be darkness on the Day of Resurrection.", exp:"Kisi par zulm na karein, ye aakhirat mein andhere ki soorat mein saamne aayega.", enexp:"Never oppress anyone; it will appear as darkness in the Hereafter.", sc:"storm"},
  {cat:"Sadqa", src:"Sahih Bukhari, Sahih Muslim", txt:"Upar wala (dene wala) haath neeche wale (lene wale) haath se behtar hai.", en:"The upper hand is better than the lower hand.", exp:"Mehnat se kamayein aur doosron ko dene wale banein.", enexp:"Earn by effort and be among those who give.", sc:"coins"},
  {cat:"Aadaab", src:"Sahih Muslim", txt:"Tum mein se koi khade hokar na piye.", en:"None of you should drink while standing.", exp:"Ye adab ka hukm hai. Kuch riwayaton mein khade ho kar peena bhi aaya hai, isliye ulama ise narmi se samjhte hain.", enexp:"This is a matter of etiquette. Some reports mention drinking standing, so scholars see it as a gentle guidance.", sc:"cup"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Musalman ko gaali dena fisq hai aur usse ladna kufr jaisa (sakht gunah) hai.", en:"Reviling a Muslim is wickedness and fighting him is disbelief-like conduct.", exp:"Musalman ki hurmat bohat badi hai. Ulama ise kufr-e-amali (sakht tambeeh) kehte hain.", enexp:"A Muslim's sanctity is great. Scholars call this practical, not literal, disbelief; it is a severe warning.", sc:"storm"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Rishta todne wala Jannat mein dakhil nahi hoga.", en:"The one who cuts family ties will not enter Paradise.", exp:"Silah-rehmi (rishte jodna) bohat zaroori hai. Ye sakht tambeeh hai.", enexp:"Keeping family ties is essential; this is a severe warning.", sc:"kinship"},
  {cat:"Akhlaq", src:"Sahih Bukhari", txt:"Mazloom ki bad-dua se bacho, kyunki uske aur Allah ke beech koi parda nahi.", en:"Beware the supplication of the oppressed, for there is no veil between it and Allah.", exp:"Zulm se bachein. Mazloom ki dua jaldi qabool hoti hai.", enexp:"Avoid oppression. The prayer of the oppressed is quickly answered.", sc:"hands"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Musalman wo hai jis ki zubaan aur haath se doosre Musalman mehfooz rahein.", en:"A Muslim is one from whose tongue and hand other Muslims are safe.", exp:"Zubaan aur haath se kisi ko takleef na dein.", enexp:"Do not harm anyone with your tongue or hand.", sc:"dove"},
  {cat:"Akhlaq", src:"Sahih Bukhari, Sahih Muslim", txt:"Kisi Musalman ke liye jaiz nahi ke apne bhai se teen din se zyada baat chhod de.", en:"It is not lawful for a Muslim to boycott his brother for more than three days.", exp:"Naraazgi jaldi khatam karke salam se shuruaat karein.", enexp:"End disputes quickly and start with salam.", sc:"hands"},
  {cat:"Ilm", src:"Sahih Muslim", txt:"Jo bhalai ki taraf rehnumai kare use bhalai karne wale ke barabar ajr milta hai.", en:"Whoever guides to good gets a reward like the one who does it.", exp:"Kisi ko nek kaam bata dena bhi sawab ka kaam hai.", enexp:"Pointing someone to a good deed is itself rewarded.", sc:"path"},
];
