const MYTH_BUSTERS = [{"level": "Level 1: Basic Islamic Myths", "q": "Raat ko nakhun kaatna mana hai?", "optA": "Bilkul sahi baat hai.", "optB": "Aisi koi baat nahi hai.", "correctIdx": 1, "explain": "Islam mein raat ko nakhun kaatne ki koi sahih manaahi nahi milti. Nakhun kaatna din ya raat dono waqt jaiz hai.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is it forbidden to cut nails at night?", "enA": "That is absolutely true.", "enB": "There is no such thing.", "enExplain": "No authentic prohibition on cutting nails at night is found in Islam. Cutting nails is permissible both during the day and at night."}, {"level": "Level 1: Basic Islamic Myths", "q": "Nakhun kaat kar unhein zaroor zameen mein dafn karna chahiye?", "optA": "Bilkul sahi baat hai.", "optB": "Aisi koi lazmi baat nahi hai.", "correctIdx": 1, "explain": "Nakhun dafn karna wajib ya zaroori nahi hai.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Must cut nails be buried in the ground?", "enA": "That is absolutely true.", "enB": "There is no such obligation.", "enExplain": "Burying nail clippings is not obligatory or necessary."}, {"level": "Level 1: Basic Islamic Myths", "q": "Baal ya nakhun phenkne se pehle 3 martaba Bismillah padhna zaroori hai?", "optA": "Bilkul zaroori hai.", "optB": "Aisi koi sahih daleel nahi hai.", "correctIdx": 1, "explain": "Aisi koi sahih daleel nahi hai.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is it necessary to recite Bismillah three times before throwing away hair or nails?", "enA": "That is absolutely necessary.", "enB": "There is no authentic evidence for this.", "enExplain": "There is no authentic evidence for this."}, {"level": "Level 1: Basic Islamic Myths", "q": "Islam mein har kaali billi ko manhoos samjha jata hai?", "optA": "Bilkul sahi baat hai.", "optB": "Islam mein kaali billi ko manhoos samajhne ki koi bunyaad nahi.", "correctIdx": 1, "explain": "Islam mein kaali billi ko manhoos samajhne ki koi bunyaad nahi.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Does Islam regard every black cat as unlucky?", "enA": "That is absolutely true.", "enB": "Islam has no basis for regarding a black cat as unlucky.", "enExplain": "Islam has no basis for regarding a black cat as unlucky."}, {"level": "Level 1: Basic Islamic Myths", "q": "Kisi din ya mahine ko apne aap mein manhoos samajhna Islam ka hissa hai?", "optA": "Haan, kuch din aur mahine manhoos hote hain.", "optB": "Nahi, aisi bad-shuguni Islami aqeede ka hissa nahi.", "correctIdx": 1, "explain": "Nahi, aisi bad-shuguni Islami aqeede ka hissa nahi.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Does being unlucky about a day or month belong to Islamic belief?", "enA": "Yes, some days and months are unlucky.", "enB": "No, such superstition is not part of Islamic belief.", "enExplain": "No, such superstition is not part of Islamic belief."}, {"level": "Level 1: Basic Islamic Myths", "q": "Safar ka mahina manhoos hota hai?", "optA": "Haan, Safar manhoos mahina hai.", "optB": "Nahi, Safar ko manhoos samajhna durust nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is the month of Safar unlucky?", "enA": "Yes, Safar is an unlucky month.", "enB": "No, it is not correct to consider Safar unlucky.", "enExplain": "No."}, {"level": "Level 1: Basic Islamic Myths", "q": "Ghar mein jhaadu raat ko dena mana hai?", "optA": "Haan, raat ko jhaadu dena mana hai.", "optB": "Aisi koi shar'i manaahi nahi hai.", "correctIdx": 1, "explain": "Aisi koi shar'i manaahi nahi hai.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is it forbidden to sweep the house at night?", "enA": "Yes, sweeping at night is forbidden.", "enB": "There is no legal prohibition for this.", "enExplain": "There is no legal prohibition for this."}, {"level": "Level 1: Basic Islamic Myths", "q": "Islam mein chheenkne ke baad \"Alhamdulillah\" kehna Sunnat hai?", "optA": "Haan.", "optB": "Nahi.", "correctIdx": 0, "explain": "Yeh un authentic Islamic etiquettes mein se hai jo aam zindagi se mutalliq hain.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is saying \"Alhamdulillah\" after sneezing a Sunnah in Islam?", "enA": "Yes.", "enB": "No.", "enExplain": "This is one of the authentic Islamic etiquettes related to everyday life."}, {"level": "Level 1: Basic Islamic Myths", "q": "Islam mein sirf masjid mein hi Namaz padhi ja sakti hai?", "optA": "Haan, ghar mein Namaz nahi ho sakti.", "optB": "Nahi, farz Namaz masjid ke alawa bhi ada ki ja sakti hai.", "correctIdx": 1, "explain": "Masjid ki jamaat ki apni fazilat hai, lekin Namaz ko sirf masjid tak mahdood nahi kiya gaya.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Can prayer be offered only in the masjid in Islam?", "enA": "Yes, prayer cannot be offered at home.", "enB": "No, the obligatory prayer can also be offered outside the masjid.", "enExplain": "The congregation in the masjid has its own virtue, but prayer is not restricted to the masjid alone."}, {"level": "Level 1: Basic Islamic Myths", "q": "Har Namaz ke liye Azaan dena har shakhs par lazmi hai?", "optA": "Haan, har shakhs ko apni Namaz ke liye Azaan deni hoti hai.", "optB": "Nahi, Azaan ka hukm is tarah har individual par nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 1: Basic Islamic Myths", "enq": "Is it compulsory for every person to give the Azaan for their own prayer?", "enA": "Yes, each person must give the Azaan for his own prayer.", "enB": "No, the ruling of Azaan does not apply to every individual in this way.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Wuzu tootne ke baad sirf haath-munh dhona kaafi hai?", "optA": "Haan, hamesha sirf haath-munh dhona kaafi hai.", "optB": "Nahi, wuzu ke apne muqarrar faraiz hain.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is it enough to wash only the hands and face after wudu breaks?", "enA": "Yes, washing the hands and face is always enough.", "enB": "No, wudu has its own set obligations.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Har baar Qur’an padhne se pehle ghusl karna zaroori hai?", "optA": "Haan, har baar ghusl zaroori hai.", "optB": "Nahi, har tilawat ke liye ghusl lazmi nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is ghusl necessary every time before reciting the Quran?", "enA": "Yes, ghusl is necessary every time.", "enB": "No, ghusl is not necessary for every recitation.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Islam mein har dua Arabic mein hi karna zaroori hai?", "optA": "Haan, sirf Arabic mein ki gayi dua qabool hoti hai.", "optB": "Nahi, Allah har zubaan samajhta hai.", "correctIdx": 1, "explain": "Allah bandon ki zubaan se zyada unke dil aur haal ko jaanta hai.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Must every dua be made in Arabic in Islam?", "enA": "Yes, only a dua made in Arabic is accepted.", "enB": "No, Allah understands every language.", "enExplain": "Allah knows the hearts and states of His servants more than their language."}, {"level": "Level 2: Daily Life & Worship", "q": "Sirf lambi dua hi zyada afzal hoti hai?", "optA": "Haan, dua jitni lambi ho utni behtar.", "optB": "Nahi, dua ki qabooliyat ka ta'alluq sirf lambai se nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is a longer dua always better?", "enA": "Yes, the longer the dua, the better.", "enB": "No, the acceptance of a dua is not tied to its length.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Sirf buzurg ya Alim hi Allah se dua kar sakte hain?", "optA": "Haan.", "optB": "Nahi, har Musalman Allah se seedha dua kar sakta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Can only elders or scholars make dua to Allah?", "enA": "Yes.", "enB": "No, every Muslim can make dua to Allah directly.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Allah se maangne ke liye kisi insaan ko lazmi waseela banana zaroori hai?", "optA": "Haan, Allah se seedha nahi maang sakte.", "optB": "Nahi, banda Allah se seedha dua kar sakta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is it necessary to make someone a means between oneself and Allah in order to ask Allah?", "enA": "Yes, we cannot ask Allah directly.", "enB": "No, a servant can make dua to Allah directly.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Namaz sirf budhape mein pabandi se padhna kaafi hai?", "optA": "Haan, jawani mein zaroori nahi.", "optB": "Nahi, Namaz ki zimmedari sirf budhape ke liye nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is regular prayer only needed in old age?", "enA": "Yes, it is not necessary in youth.", "enB": "No, the responsibility of prayer is not only for old age.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Nafl Namaz na padhne par gunah hota hai?", "optA": "Haan, har Nafl chhorne par gunah hota hai.", "optB": "Nahi, Nafl farz nahi hoti.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is it a sin to not offer voluntary prayer?", "enA": "Yes, every voluntary prayer missed is a sin.", "enB": "No, voluntary prayer is not obligatory.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Witr ko bilkul aam Nafl samajhna sahi hai?", "optA": "Haan, Witr ka koi khaas maqam nahi.", "optB": "Nahi, Witr ki khaas ahmiyat hai aur iske hukm ki tafseel fiqhi madhahib mein mukhtalif hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is Witr simply an ordinary voluntary prayer?", "enA": "Yes, Witr has no special status.", "enB": "No, Witr has a special importance, and the details of its ruling differ among the schools of fiqh.", "enExplain": "No."}, {"level": "Level 2: Daily Life & Worship", "q": "Roza sirf bhooka aur pyasa rehne ka naam hai?", "optA": "Haan.", "optB": "Nahi, Roza ibadat aur taqwa ka amal hai jo insan ko gunahon se bachne ki tarbiyat deta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 2: Daily Life & Worship", "enq": "Is fasting merely abstaining from hunger and thirst?", "enA": "Yes.", "enB": "No, fasting is an act of worship and taqwa that trains a person to avoid sins.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Ramzan mein sirf khana peena chhorna hi kaafi hai?", "optA": "Haan.", "optB": "Nahi, Roza insan ke akhlaaq aur amal ko bhi behtar karne ki tarbiyat deta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Is it enough during Ramadan simply to stop eating and drinking?", "enA": "Yes.", "enB": "No, fasting also improves a person's character and actions.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Haiz wali aurat ko Islam mein har tarah se logon se alag rehna chahiye?", "optA": "Haan, use logon se bilkul alag rehna chahiye.", "optB": "Nahi, haiz ki wajah se aurat ko social isolation mein rehna zaroori nahi.", "correctIdx": 1, "explain": "Qur’an 2:222 mein khaas manaahi sexual intercourse ke hawale se hai, na ke aurat ko poori tarah social life se alag karne ke liye.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Is a woman in her menses required to be completely separated from people in every way?", "enA": "Yes, she must completely stay apart from people.", "enB": "No, a woman in menses need not be kept in total social isolation.", "enExplain": "The Quran 2:222 refers to the specific prohibition of intercourse, not to completely removing a woman from social life."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Haiz ke dauran aurat ko Qur’an ki koi bhi ayat padhna bilkul har surat mein haram hai?", "optA": "Haan, is par koi ikhtilaf nahi.", "optB": "Nahi, is masle mein ulama ka ikhtilaf hai.", "correctIdx": 1, "explain": "Is masle ko absolute “sab ke nazdeek haram” kehna durust nahi. Kuch ulama mana karte hain aur kuch ulama daleel ki bunyaad par tilawat ki ijazat dete hain.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Is it absolutely forbidden for a woman in menses to recite any verse of the Quran in every case?", "enA": "Yes, there is no disagreement on this.", "enB": "No, scholars differ on this issue.", "enExplain": "It is not correct to call this an absolute prohibition agreed by all. Some scholars forbid it, while others permit recitation based on evidence."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Haiz ke dauran aurat Allah se Dua nahi kar sakti?", "optA": "Haan, dua nahi kar sakti.", "optB": "Nahi, Dua aur zikr kar sakti hai.", "correctIdx": 1, "explain": "Nahi, Dua aur zikr kar sakti hai.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Can a woman in menses not make dua to Allah?", "enA": "Yes, she cannot make dua.", "enB": "No, she can make dua and remember Allah.", "enExplain": "No, she can make dua and remember Allah."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein beti ko virasat mein koi hissa nahi milta?", "optA": "Bilkul nahi milta.", "optB": "Nahi, Islam ne auraton ke liye bhi virasat ke huqooq muqarrar kiye hain.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "In Islam, does a daughter get no share of inheritance?", "enA": "Certainly not.", "enB": "No, Islam gave women rights of inheritance as well.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein walidain ki har baat maanna lazmi hai, chahe woh gunah ka hukm dein?", "optA": "Haan, walidain ki har baat maanna lazmi hai.", "optB": "Nahi, Allah ki na-farmani mein kisi ki ita'at nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "In Islam, must one obey parents in everything, even if they order a sin?", "enA": "Yes, every command of parents must be obeyed.", "enB": "No, there is no obedience to anyone in disobedience of Allah.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein nikah ke liye sirf parents ki raza-mandi kaafi hai?", "optA": "Haan, dulhan ki raza zaroori nahi.", "optB": "Nahi, nikah mein aurat ki raza-mandi ki bhi ahmiyat hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "In Islam, is parental consent enough for marriage?", "enA": "Yes, the bride's consent is not necessary.", "enB": "No, the woman's consent is also important in marriage.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein biwi ko apne shohar ki har baat bina kisi sawal ke maanna hota hai?", "optA": "Haan, har baat.", "optB": "Nahi, ita'at Allah ki na-farmani mein nahi hoti.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "In Islam, must a wife accept every word of her husband without question?", "enA": "Yes, every word.", "enB": "No, obedience is not due in disobedience to Allah.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein bachchon ke saath sirf sakhti se tarbiyat karna Sunnat hai?", "optA": "Haan, bachchon ko sirf sakhti se palna chahiye.", "optB": "Nahi, Islam mein rehmat, shafqat aur achhi tarbiyat ki bhi ahmiyat hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Is it a Sunnah in Islam to raise children only with harshness?", "enA": "Yes, children should be raised only with harshness.", "enB": "No, mercy, kindness and good upbringing are also important in Islam.", "enExplain": "No."}, {"level": "Level 3: Ramzan, Women & Family", "q": "Islam mein aurat ka har ghar se bahar nikalna mana hai?", "optA": "Haan, aurat ghar se bahar nahi nikal sakti.", "optB": "Nahi, is tarah ki absolute manaahi Islam ka qaida nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 3: Ramadan, Women & Family", "enq": "Is it absolutely forbidden in Islam for a woman to leave the house?", "enA": "Yes, a woman cannot leave the house.", "enB": "No, this kind of absolute prohibition is not a rule of Islam.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Gheebat sirf jhoot bolne ka naam hai?", "optA": "Haan, sirf jhoot ko Gheebat kehte hain.", "optB": "Nahi, kisi shakhs ki ghair-maujoodgi mein uski aisi baat karna jo use na-pasand ho Gheebat ho sakti hai.", "correctIdx": 1, "explain": "Qur’an 49:12 mein Gheebat se wazeh taur par mana kiya gaya hai.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Is backbiting only the same as telling lies?", "enA": "Yes, only lies are called backbiting.", "enB": "No, saying something about a person in their absence that they would dislike can be backbiting.", "enExplain": "The Quran 49:12 clearly forbids backbiting."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Agar baat sach ho to woh Gheebat nahi hoti?", "optA": "Bilkul, sach baat kabhi Gheebat nahi hoti.", "optB": "Nahi, sach baat bhi Gheebat ho sakti hai.", "correctIdx": 1, "explain": "Yahi Gheebat aur Buhtan ka ek important farq hai: sach baat kisi ki ghair-maujoodgi mein uski na-pasand surat mein kehna Gheebat ho sakta hai; jhooti baat ho to Buhtan ka gunah hota hai.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "If a statement is true, is it not backbiting?", "enA": "Certainly, a true statement is never backbiting.", "enB": "No, even a true statement can be backbiting.", "enExplain": "This is the key difference between backbiting and slander: a true statement that is said in someone's absence in a way they would dislike can be backbiting; if it is false, it is the sin of slander."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Dil mein kisi ke baare mein har shak gunah hota hai?", "optA": "Haan, har shak gunah hai.", "optB": "Nahi, Qur’an \"bahut se gumaan\" se bachne ka hukm deta hai; har khayal ko ek hi hukm nahi diya gaya.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Is every suspicion about someone a sin in the heart?", "enA": "Yes, every suspicion is a sin.", "enB": "No, the Quran forbids much suspicion; not every thought carries the same ruling.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Islam mein kisi ke aib ki talaash karna jaiz hai?", "optA": "Haan, doosron ke private matters check karna jaiz hai.", "optB": "Nahi, Qur’an tajassus yani spying se mana karta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Is it permissible in Islam to search for other people's faults?", "enA": "Yes, it is permissible to check others' private matters.", "enB": "No, the Quran forbids spying.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Sirf badi quantity mein maal churaane par hi gunah hota hai?", "optA": "Haan.", "optB": "Nahi, chori ki hurmat quantity se khatam nahi hoti.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Is a theft a sin only when a large amount is stolen?", "enA": "Yes.", "enB": "No, the prohibition of theft is not removed by the amount.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Islam mein kisi ko maaf karna kamzori ki nishani hai?", "optA": "Haan.", "optB": "Nahi, maafi aur dar-guzar Islam mein fazilat ho sakti hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "In Islam, is forgiving someone a sign of weakness?", "enA": "Yes.", "enB": "No, forgiveness and overlooking wrongs can be a virtue in Islam.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Sabr ka matlab yeh hai ke insan zulm ko hamesha chup-chaap bardasht kare?", "optA": "Haan.", "optB": "Nahi, Sabr ka matlab zulm ko har surat mein accept karna nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Does patience mean that a person must always quietly bear oppression?", "enA": "Yes.", "enB": "No, patience does not mean accepting oppression in every case.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Shukr ka matlab sirf \"Alhamdulillah\" keh dena hai?", "optA": "Haan.", "optB": "Nahi, Shukr mein Allah ki ne'mat ko tasleem karna aur uska durust istemal bhi shamil hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Does gratitude mean only saying \"Alhamdulillah\"?", "enA": "Yes.", "enB": "No, gratitude includes acknowledging Allah's blessing and using it rightly.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Agar koi gunah bohat chhota ho to uski koi ahmiyat nahi?", "optA": "Haan, chhote gunah matter nahi karte.", "optB": "Nahi, Musalman ko gunahon ko halka nahi samajhna chahiye.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "If a sin is very small, does it have no importance?", "enA": "Yes, small sins do not matter.", "enB": "No, a Muslim should not treat sins lightly.", "enExplain": "No."}, {"level": "Level 4: Gunah, Akhlaaq & Social Myths", "q": "Sirf doosron ko Islam ki baatein batana hi Neki hai?", "optA": "Haan, sirf da'wah hi Neki hai.", "optB": "Nahi, Neki ke bohat se forms hain: ibadat, sadaqah, achha akhlaaq, walidain se husn-e-sulook, madad aur doosre nek aamaal.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 4: Sin, Character & Social Myths", "enq": "Is telling others about Islam the only form of good deed?", "enA": "Yes, only calling to Islam is a good deed.", "enB": "No, there are many forms of good deeds: worship, charity, good character, kindness to parents, helping others and other good actions.", "enExplain": "No."}, {"level": "Level 5: Deeper Islamic Myths", "q": "\"Allah mujhe kabhi maaf nahi karega\" kehna sahi hai agar gunah bohat bada ho?", "optA": "Haan, kuch gunah itne bade hain ke maafi mumkin nahi.", "optB": "Nahi, Allah ki rahmat se mayoos nahi hona chahiye.", "correctIdx": 1, "explain": "Qur’an 39:53 mein Allah ki rahmat se mayoosi se mana kiya gaya hai. Yeh taubah aur maghfirat ki umeed ka bohat important principle hai.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "\"Allah will never forgive me\" is it right to say this if the sin is very great?", "enA": "Yes, some sins are too great to be forgiven.", "enB": "No, one should not despair of Allah's mercy.", "enExplain": "The Quran 39:53 forbids despair of Allah's mercy. This is a very important principle of hope for repentance and forgiveness."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Jo insan bohat gunahgaar raha ho uske liye Taubah ka darwaza band ho jata hai?", "optA": "Haan, ek hadd ke baad Taubah qabool nahi hoti.", "optB": "Nahi, zindagi mein Taubah ka darwaza khula rehta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "Is the door of repentance closed for a person who has committed many sins?", "enA": "Yes, after a certain limit repentance is not accepted.", "enB": "No, the door of repentance remains open throughout life.", "enExplain": "No."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Allah sirf Arab logon se zyada mohabbat karta hai?", "optA": "Haan.", "optB": "Nahi, Islam mein kisi qaum ki nasli ya zabani bunyaad par Allah ke qareeb hone ki guarantee nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "Does Allah love only the Arabs more?", "enA": "Yes.", "enB": "No, Islam gives no guarantee of nearness to Allah based on a people's lineage or language.", "enExplain": "No."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Islam mein kisi insan ki izzat uske maal aur khandan se tay hoti hai?", "optA": "Haan.", "optB": "Nahi, maal aur nasab Allah ke nazdeek asli mayaar nahi.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "In Islam, is a person's honour decided by his wealth and family?", "enA": "Yes.", "enB": "No, wealth and lineage are not the true measure in the sight of Allah.", "enExplain": "No."}, {"level": "Level 5: Deeper Islamic Myths", "q": "\"Allah mere liye kuch nahi kar raha, isliye Allah mujhse mohabbat nahi karta\", kya yeh soch durust hai?", "optA": "Haan, agar mushkil aaye to iska matlab Allah naraz hai.", "optB": "Nahi, Musibat hamesha Allah ki narazgi ka saboot nahi hoti.", "correctIdx": 1, "explain": "Mushkilaat aazmaish, tanbeeh, tarbiyat, ya doosri hikmaton ka hissa ho sakti hain. Kisi individual mushkil ko automatically Allah ki narazgi keh dena durust nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "\"Allah is not doing anything for me, so Allah does not love me\" is this thinking correct?", "enA": "Yes, if hardship comes it means Allah is displeased.", "enB": "No, a hardship is not always proof of Allah's displeasure.", "enExplain": "Hardships may be a test, a warning, training, or part of other wisdom. It is not correct to automatically call an individual's hardship Allah's displeasure."}, {"level": "Level 5: Deeper Islamic Myths", "q": "\"Allah jis se mohabbat karta hai usko kabhi koi mushkil nahi deta\"?", "optA": "Haan, Allah ke nek bande hamesha mushkil se mehfooz rehte hain.", "optB": "Nahi, Ambiya aur nek log bhi aazmaishon se guzre.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "\"Allah never gives hardship to those He loves\"?", "enA": "Yes, the righteous servants of Allah are always protected from hardship.", "enB": "No, the Prophets and righteous people also passed through trials.", "enExplain": "No."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Islam mein har bimari sirf gunah ki saza hoti hai?", "optA": "Haan, bimari ka matlab zaroor gunah ki saza hai.", "optB": "Nahi, bimari ko har haal mein gunah ki saza kehna durust nahi.", "correctIdx": 1, "explain": "Bimari aazmaish bhi ho sakti hai aur us par sabr ka ajr bhi mil sakta hai.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "Does every illness in Islam come only as a punishment for sin?", "enA": "Yes, illness always means a punishment for sin.", "enB": "No, it is not correct to call every illness a punishment for sin.", "enExplain": "An illness can also be a test, and patience with it can earn reward."}, {"level": "Level 5: Deeper Islamic Myths", "q": "\"Allah kisi jaan ko uski capacity se zyada takleef deta hai\", kya Islam yeh sikhata hai?", "optA": "Haan.", "optB": "Nahi, Qur’an ke mutabiq Allah kisi jaan ko uski wus'at se zyada mukallaf nahi karta.", "correctIdx": 1, "explain": "Qur’an 2:286 mein yeh principle wazeh hai ke Allah kisi jaan ko uski capacity se zyada burden nahi karta.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "\"Allah does not burden a soul beyond its capacity\", does Islam teach this?", "enA": "Yes.", "enB": "No, according to the Quran Allah does not burden a soul beyond its capacity.", "enExplain": "The Quran 2:286 clearly states that Allah does not burden a soul beyond its capacity."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Islam mein Deen qabool karwane ke liye har insan ko zabardasti Muslim banana chahiye?", "optA": "Haan, Islam zabardasti qabool karwaya ja sakta hai.", "optB": "Nahi, Qur’an mein hai: \"Deen mein koi zabardasti nahi.\"", "correctIdx": 1, "explain": "Qur’an 2:256 mein \"Laa ikraaha fid-deen\" ka zikr hai. Is ayat ki tafsir aur historical application par classical scholarship mein discussion milti hai, lekin ayat ka lafzi principle “Deen mein koi zabardasti nahi” hai.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "In Islam, should people be forced to become Muslim to accept the religion?", "enA": "Yes, Islam can be accepted by force.", "enB": "No, the Quran says: \"There is no compulsion in religion.\"", "enExplain": "The Quran 2:256 mentions \"la ikraha fid-deen\". Classical scholars have discussed this verse and its application, but its clear principle is \"there is no compulsion in religion\"."}, {"level": "Level 5: Deeper Islamic Myths", "q": "Islam mein sirf apni ibadat kaafi hai, doosron ke huqooq ki koi khaas ahmiyat nahi?", "optA": "Haan, agar Namaz aur Roza sahi hain to logon ke huqooq secondary hain.", "optB": "Nahi, Islam ibadat ke saath logon ke huqooq, akhlaaq aur muamalaat par bhi zor deta hai.", "correctIdx": 1, "explain": "Nahi.", "enLevel": "Level 5: Deeper Islamic Myths", "enq": "In Islam, is one's own worship enough, with no special importance for the rights of others?", "enA": "Yes, if Salah and fasting are correct, the rights of others are secondary.", "enB": "No, Islam also stresses people's rights, character and dealings alongside worship.", "enExplain": "No."}];

