const AADAAB_TOPICS = [
  { id:"bas-5-minute-ka-jhoot", title:"'Bas 5 Minute' Ka Jhoot", tags:["Waqt","Phone","Zimmedari"], ic:"⏱️", cat:"waqt", color:"#c79a2e",
    en:{"title": "The 'Just 5 Minutes' Lie", "tags": ["Time", "Phone", "Responsibility"], "scene": "Opened the phone, watched one reel, then another, then a third. 'Just 5 minutes', and an hour was gone.", "masla": "We protect time as if it were money, but time is even more limited than money. Once it passes, it never comes back.", "islam": "Keeping an account of your time and not wasting it on pointless things is wisdom.", "nabi": null, "galti": "We think, 'What difference will 5 minutes make?' But these 5 minutes add up to hours every day.", "tabdeeli": "The next time you open an app for just 5 minutes, set a timer and see how much time it really takes."},
    scene:"Phone khola, ek reel dekhi, phir doosri, phir teesri, 'bas 5 minute' kehte kehte ek ghanta nikal gaya.",
    masla:"Hum waqt ko paisa samajh kar protect karte hain, lekin waqt paison se bhi zyada limited hai, ek baar guzar jaaye toh wapas nahi aata.",
    islam:"Apne waqt ka hisaab rakhna aur usay fuzool kaamon mein zaya na karna aqalmandi hai.",
    nabi:null,
    galti:"Hum sochte hain '5 minute se kya farq padega', lekin yehi 5 minute roz kai ghanton mein badal jaate hain.",
    tabdeeli:"Jab kisi app ko sirf 5 minute ke liye kholein, timer laga kar dekhiye ke asal mein kitna waqt ja raha hai." },
  { id:"main-aisa-hi-hoon", title:"'Main Aisa Hi Hoon' Excuse Nahi", tags:["Islah","Shakhsiyat","Koshish"], ic:"🪞", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "'I'm Just Like This' Is Not an Excuse", "tags": ["Reform", "Personality", "Effort"], "scene": "'I have a short temper.' 'I'm never on time.' 'I just talk like this.' 'It's just my nature.'", "masla": "There is a difference between personality and a bad habit. If a habit keeps hurting you or others, calling it 'my nature' to avoid change is avoiding self-improvement.", "islam": "Islam invites a person to improve his character and habits. This is an ongoing effort.", "nabi": null, "galti": "We treat our habits as a fixed personality, so we stop trying to change them at all.", "tabdeeli": "Identify one habit that hurts others. Instead of saying 'it's my nature', make an effort to improve it."},
    scene:"'Main gusse wala hoon.' 'Main punctual nahi hoon.' 'Main aisa hi bolta hoon.' 'Mera nature hi aisa hai.'",
    masla:"Shakhsiyat aur buri aadat mein farq hai. Agar koi aadat aapko ya doosron ko musalsal takleef de rahi hai, toh usay 'mera nature' kehkar bachaav karna khud-islahi se bachna hai.",
    islam:"Islam insan ko apne akhlaaq aur aadaat ko behtar banane ki dawat deta hai, yeh ek jaari rehne wala amal hai.",
    nabi:null,
    galti:"Hum apni aadaton ko 'fixed personality' samajh kar unko badalne ki koshish hi chhod dete hain.",
    tabdeeli:"Apni ek aisi aadat identify kijiye jo doosron ko takleef deti hai, aur usay 'mera nature hai' kehne ke bajaye behtar banane ki koshish kijiye." },
  { id:"aaram-sustee-farq", title:"Aaram Aur Sustee Mein Farq Hai", tags:["Rest","Zimmedari","Self-Care"], ic:"🛌", cat:"sehat", color:"#e0893f",
    en:{"title": "Rest and Laziness Are Different", "tags": ["Rest", "Responsibility", "Self-Care"], "scene": "Tired? Rest. Not enough sleep? Sleep. Does the body need recovery? Take a break. But 'I don't feel like it' and 'I really need rest' are not the same thing.", "masla": "Healthy rest makes you productive again. Laziness keeps you away from your responsibilities, and we forget the difference between the two.", "islam": "Islam teaches us to care for both rest and responsibility: neither to abuse the body, nor to use it as an excuse to abandon work.", "nabi": null, "galti": "We call laziness 'self-care', while real self-care is what makes us better and more responsible.", "tabdeeli": "Keep your rest guilt-free, but do not call your laziness 'self-care'."},
    scene:"Thak gaye hain? Aaram kijiye. Neend poori nahi hui? Soyiye. Body ko recovery chahiye? Rest kijiye. Lekin 'mera mood nahi hai' aur 'mujhe waqai rest chahiye', dono ek cheez nahi.",
    masla:"Healthy rest aapko dobara productive banata hai. Sustee aapko apni zimmedariyon se door karti rehti hai, aur hum dono mein farq karna bhool jaate hain.",
    islam:"Islam mein aaram aur zimmedari dono ka khayal rakhna sikhaya gaya hai, na jism par zulm karna, na usay bahana bana kar kaam chhod dena.",
    nabi:null,
    galti:"Hum susti ko 'self-care' ka naam de dete hain, jabke asal self-care woh hai jo hamein behtar aur zimmedar banaye.",
    tabdeeli:"Apne rest ko guilt-free rakhiye, lekin apni laziness ko 'self-care' ka naam mat dijiye." },
  { id:"allah-sirf-namaz-waqt-nahi", title:"Allah Ko Sirf Namaz Ke Waqt Yaad Na Karein", tags:["Zikr","Taqwa","Rozmarra Ibadat"], ic:"🕋", cat:"ibadat", color:"#9b6fd6",
    en:{"title": "Do Not Remember Allah Only at Prayer Time", "tags": ["Remembrance", "Taqwa", "Daily Worship"], "scene": "Prayer is an obligatory and central act of worship. But should the rest of life be completely disconnected from Allah?", "masla": "Intention while working, gratitude while eating, seeking Allah's pleasure while helping someone, fear of Allah when a wrong opportunity comes, trust in Allah in hardship: these too are part of the Deen.", "islam": "Deen and daily life are not two separate things. Every permissible action done with a good intention can become worship.", "nabi": null, "galti": "We limit Allah to prayer, fasting and the masjid, and keep the rest of life apart from the Deen, thinking of it as 'worldly'.", "tabdeeli": "Today, start one daily task with a good intention, keeping in mind that it too is for Allah."},
    scene:"Namaz apni jagah farz aur markazi ibadat hai. Lekin kya baaki zindagi Allah se bilkul disconnected honi chahiye?",
    masla:"Kaam karte waqt niyyat, khate waqt shukr, kisi ki madad karte waqt Allah ki raza, galat mauka aaye toh Allah ka khauf, kisi mushkil mein Allah par tawakkul, yeh sab bhi Deen ka hissa hain.",
    islam:"Deen aur rozmarra zindagi do alag khaane nahi. Har jaayez kaam agar achhi niyyat se kiya jaaye, toh woh bhi ibadat ban sakta hai.",
    nabi:null,
    galti:"Hum Allah ko sirf namaz, roza aur masjid tak mehdood kar dete hain, aur baaki zindagi ko 'duniyawi' samajh kar Deen se alag rakh dete hain.",
    tabdeeli:"Apne rozmarra ke kisi ek kaam ko aaj achhi niyyat ke saath shuru kijiye, is khayal ke saath ke yeh bhi Allah ke liye hai." },
  { id:"amanat-wapas-kijiye", title:"Amanat Wapas Kijiye", tags:["Amanat","Trust","Zimmedari"], ic:"📦", cat:"maal", color:"#b8860b",
    en:{"title": "Return the Trust (Amanat)", "tags": ["Trust", "Trustworthiness", "Responsibility"], "scene": "A friend lent you a book, a relative gave you money, the office gave you equipment, someone handed you an important document. You kept it and then forgot about it.", "masla": "A trust is not only about big things. Even small things must be treated as a trust.", "islam": "Protecting a trust and returning it on time is a sign of faith.", "nabi": null, "galti": "We think 'I'll give it back when I remember', and then the matter is put off forever.", "tabdeeli": "Look around your home: is there something that belongs to someone else which you have been keeping without reason? Make a plan to return it today."},
    scene:"Friend ne book di, relative ne paisa diya, office ne equipment diya, kisi ne important document aapko diya, aapne rakha aur phir bhool gaye.",
    masla:"Amanat ka matlab sirf badi cheez nahi. Chhoti cheez ko bhi amanat samajhna zaroori hai.",
    islam:"Amanat ki hifazat aur waqt par wapas karna Imaan ki ek nishani hai.",
    nabi:null,
    galti:"Hum sochte hain 'yaad aane par de dunga', aur phir yeh baat hamesha ke liye taal jaati hai.",
    tabdeeli:"Ghar mein dekhiye: kya kisi aur ki koi cheez aapke paas be-wajah padi hui hai? Usay aaj hi wapas karne ka iraada kijiye." },
  { id:"ammi-abbu-baad-mein", title:"Ammi/Abbu Ko 'Baad Mein' Kehte Rehna", tags:["Walidain","Waqt","Husn-e-Sulook"], ic:"👴", cat:"ghar", color:"#d6708f",
    en:{"title": "Telling Mum and Dad 'Later' Again and Again", "tags": ["Parents", "Time", "Good Conduct"], "scene": "'I'm busy.' 'I'll talk later.' 'I'm in a meeting.' 'One minute.' Sometimes parents are only asking for a little of our time.", "masla": "Not every call is urgent, but every relationship needs attention, and the relationship with parents needs it most.", "islam": "Good treatment of parents and respect for them is a very important theme in the Quran.", "nabi": null, "galti": "We think 'they will understand, I'll talk to them later', and that 'later' never comes.", "tabdeeli": "Today, sit with your parents for 10 minutes without a phone."},
    scene:"'Abhi busy hoon.' 'Baad mein baat karta hoon.' 'Abhi meeting hai.' 'Ek minute.' Kabhi parents humse sirf thoda waqt maang rahe hote hain.",
    masla:"Har call urgent nahi hoti, lekin har rishta tawajjo chahta hai, aur waalidain ka rishta sabse zyada.",
    islam:"Walidain ke saath husn-e-sulook aur unki izzat Qur'an ka bohot ahem mauzu hai.",
    nabi:null,
    galti:"Hum sochte hain 'woh samajh jaayenge, main baad mein baat kar lunga', aur yeh 'baad mein' kabhi aata hi nahi.",
    tabdeeli:"Aaj walidain ke saath bina phone ke sirf 10 minute baithiye." },
  { id:"bachon-ko-example-chahiye", title:"Bachon Ko Sirf Lecture Nahi, Example Chahiye", tags:["Tarbiyat","Kirdaar","Walidain"], ic:"🧒", cat:"ghar", color:"#d6708f",
    en:{"title": "Children Need Examples, Not Just Lectures", "tags": ["Upbringing", "Character", "Parents"], "scene": "You tell your child 'use your phone less', and then you are on the phone for six hours. You say 'don't lie', and on the phone you say 'tell them Dad is not at home'.", "masla": "Children observe our behaviour much more than our words, and they learn from it.", "islam": "Parents are the first example for their children. Upbringing comes not only from advice but from one's own actions.", "nabi": null, "galti": "We think 'this rule is only for the child', while children always copy what we actually do.", "tabdeeli": "Whatever habit you want to teach your child, first practise it yourself."},
    scene:"Aap bachche se kehte hain 'phone kam use karo', aur khud 6 ghante phone par. Aap kehte hain 'jhoot nahi bolna', aur phone par kehte hain 'bol dena papa ghar par nahi hain'.",
    masla:"Bachche hamari baatein kam aur hamara rawayya (behaviour) zyada observe karte hain, aur wahi seekhte hain.",
    islam:"Walidain apni aulad ke liye sabse pehla example hote hain; tarbiyat sirf nasihat se nahi, apne amal se hoti hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sirf bache ke liye rule hai', jabke bachche hamesha hamare amal ko hi copy karte hain.",
    tabdeeli:"Bachche ko jo ek aadat sikhani hai, usay pehle khud apnaiye." },
  { id:"bargain-zulm-nahi", title:"Bargain Karte Waqt Zulm Mat Kijiye", tags:["Insaaf","Tijarat","Haq"], ic:"🤝", cat:"maal", color:"#b8860b",
    en:{"title": "Do Not Oppress While Bargaining", "tags": ["Justice", "Trade", "Rights"], "scene": "An item costs ₹500, and you say 'I'll take it for ₹100'. The seller is forced to agree. You know the price is higher, yet you take full advantage of his need.", "masla": "There is a difference between bargaining and exploitation. Buying cheaply is no achievement if it means taking away someone else's rights.", "islam": "Trade requires the consent and fairness of both sides. Taking unfair advantage of someone's need is forbidden in Islam.", "nabi": null, "galti": "We call this 'smart bargaining', when in fact it becomes taking advantage of someone's need.", "tabdeeli": "When bargaining, ask yourself: 'Is this price fair, or am I just taking advantage of the seller's need?'"},
    scene:"₹500 ki cheez, aapne kaha 'main ₹100 mein lunga'. Seller majboor hai, aapko pata hai item ki qeemat zyada hai, phir bhi uski majboori ka poora fayda uthaya.",
    masla:"Bargaining aur zyadti (exploitation) mein farq hota hai. Sasta khareedna koi achievement nahi agar uske liye kisi aur ka haq dabana pade.",
    islam:"Tijarat mein dono taraf ki raza aur insaaf zaroori hai, kisi ki majboori ka ghalat fayda uthana Islam mein mana hai.",
    nabi:null,
    galti:"Hum isay 'smart bargaining' samajh lete hain, jabke asal mein yeh kisi ki majboori ka istemal ban jaata hai.",
    tabdeeli:"Bargain karte waqt socha kijiye: 'Kya yeh qeemat insaaf wali hai, ya main sirf uski majboori ka fayda utha raha hoon?'" },
  { id:"biwi-shauhar-emotional-dustbin-nahi", title:"Biwi/Shauhar Aapka Emotional Dustbin Nahi", tags:["Rishta","Sabr","Mohabbat"], ic:"💞", cat:"ghar", color:"#d6708f",
    en:{"title": "Your Spouse Is Not Your Emotional Dustbin", "tags": ["Marriage", "Patience", "Love"], "scene": "Stress from the office, anger from traffic, frustration with the boss, financial pressure. And as soon as you get home, you take it out on your spouse. Then: 'But you are my own.'", "masla": "Being close is not a licence to hurt someone. A spouse is a person with whom you build peace and companionship, not someone to dump every frustration on.", "islam": "Gentleness, love and respect for each other in the relationship between husband and wife is an important part of Islamic teaching.", "nabi": "The Prophet ﷺ said: the best of you is the one who is best to his family.", "galti": "We bring outside anger inside, and make our closest relationships the target of it.", "tabdeeli": "Before coming home, recognise your day's stress, and do not make your household the target of it without reason."},
    scene:"Office ka stress, traffic ka gussa, boss ki frustration, financial tension, aur ghar aate hi spouse par nikal diya. Phir: 'Tum toh mere apne ho.'",
    masla:"Apna hona kisi ko takleef pahunchane ka license nahi. Spouse woh insaan hai jiske saath sukoon aur rifaqat banani hai, har frustration dump karne ke liye nahi.",
    islam:"Shauhar aur biwi ke rishte mein narmi, mohabbat aur ek doosre ki qadr karna Islami taleem ka ahem hissa hai.",
    nabi:"Nabi ﷺ ne farmaya ke tum mein behtareen woh hai jo apne ghar walon ke saath behtareen ho.",
    galti:"Hum bahar ka gussa andar le aate hain aur sabse qareebi rishte ko hi uska target bana dete hain.",
    tabdeeli:"Ghar aane se pehle apne din ka stress pehchaniye, aur ghar walon ko bila wajah uska nishana mat banaiye." },
  { id:"bolne-se-pehle-sochiye", title:"Bolne Se Pehle Sochiye", tags:["Guftugu","Khamoshi","Tahammul"], ic:"🤐", cat:"zubaan", color:"#7e6fd6",
    en:{"title": "Think Before You Speak", "tags": ["Speech", "Silence", "Tolerance"], "scene": "Not everything we know needs to be said. Not every opinion needs to be given. Not every argument needs a reply. Not every secret needs to be shared.", "masla": "We often speak simply because we get the chance, without thinking whether it is needed.", "islam": "Using the tongue thoughtfully is a basic part of Islamic etiquette.", "nabi": "The Prophet ﷺ taught: say something good or remain silent (Sahih Bukhari 6475).", "galti": "Sometimes we keep talking just to prove our point, whether or not it is necessary.", "tabdeeli": "Before saying anything, ask yourself three questions: Is it true? Is it necessary? Is it beneficial to someone? If not, silence is the better answer."},
    scene:"Har baat jo hum jaante hain, bolna zaroori nahi. Har opinion dena zaroori nahi. Har argument ka jawab dena zaroori nahi. Har secret share karna zaroori nahi.",
    masla:"Hum aksar sirf isliye bol dete hain kyunke mauka mil gaya, bina yeh socha ke uski zarurat bhi hai ya nahi.",
    islam:"Zaban ka istemal sochh samajh kar karna Islami adab ka bunyadi hissa hai.",
    nabi:"Nabi ﷺ ki taleem hai ke insan achhi baat kahe ya khamosh rahe (Sahih Bukhari 6475).",
    galti:"Hum kabhi-kabhi sirf apni baat sahi sabit karne ke liye bolte rehte hain, chahe woh zaroori ho ya na ho.",
    tabdeeli:"Kisi bhi baat se pehle teen sawal khud se poochiye: kya yeh sach hai? Kya yeh zaroori hai? Kya yeh kisi ke liye faida-mand hai? Agar nahi, toh khamoshi behtar jawab hai." },
  { id:"buffet-muqabala-nahi", title:"Buffet Hai, Muqabala Nahi", tags:["Israf","Aitedaal","Khana"], ic:"🍱", cat:"khana", color:"#c0563f",
    en:{"title": "It's a Buffet, Not a Competition", "tags": ["Extravagance", "Moderation", "Food"], "scene": "'I have to get my money's worth', so 15 items on the plate, then dessert, then a cold drink, then ice cream. And at home: 'I ate far too much today.'", "masla": "The purpose of a buffet is choice, not a licence to overeat.", "islam": "The Quran's principle is simple: eat and drink, but do not be extravagant.", "nabi": null, "galti": "We put the thought of 'getting our money's worth' above our own health, when the real loss is to our own body.", "tabdeeli": "At a buffet, first look at the whole table, then take only the things you will really eat."},
    scene:"'Paisa vasool karna hai', isliye plate par 15 items, phir dessert, phir cold drink, phir ice cream. Aur ghar jaakar: 'Aaj toh bahut kha liya.'",
    masla:"Buffet ka purpose choice hai, overeating ka license nahi.",
    islam:"Qur'an ka usool simple hai: khaaiye, peejiye, lekin israf na kijiye.",
    nabi:null,
    galti:"Hum 'paisa vasool' ki soch ko apni sehat se upar rakh dete hain, jabke asal nuqsan apne hi jism ka hota hai.",
    tabdeeli:"Buffet mein pehle poori table dekh lijiye, phir woh cheezein lijiye jo waqai khani hain." },
  { id:"business-mein-sach", title:"Business Mein Sach Bolna", tags:["Diyanat","Tijarat","Amanat"], ic:"🧾", cat:"maal", color:"#b8860b",
    en:{"title": "Speak the Truth in Business", "tags": ["Honesty", "Trade", "Trust"], "scene": "The product is faulty and you know it, but the customer is not told. The photo shows one thing, the reality is another. 'Original' is written when it is not. Fake urgency: 'Last piece!' when the stock is full.", "masla": "Earning a profit in business is permissible, but deception cannot be a substitute for profit.", "islam": "Telling the truth in trade, and not selling goods while hiding their faults, are basic principles of Islamic trade.", "nabi": "The Prophet ﷺ said that an honest and trustworthy trader will be with the Prophets, the truthful and the martyrs on the Day of Judgment.", "galti": "We think 'a little overpromising is part of business', when in fact it betrays the customer's trust.", "tabdeeli": "Tell your next customer one true thing about the product that you would normally hide."},
    scene:"Product mein defect hai, aapko pata hai lekin customer ko nahi bataya. Photo mein kuch aur, reality mein kuch aur. 'Original' likh diya jab original nahi. Fake urgency: 'Last piece!' jab actually stock full hai.",
    masla:"Business mein profit kamaana jaayez hai, lekin dhoka profit ka substitute nahi ban sakta.",
    islam:"Tijarat mein sach bolna aur maal ka aib chhupa kar na bechna Islami tijarat ke bunyadi usool hain.",
    nabi:"Nabi ﷺ ne farmaya ke sachcha aur amanatdar tajir Qiyamat ke din Anbiya, Siddiqeen aur Shuhada ke saath hoga.",
    galti:"Hum sochte hain 'thoda overpromise karna business ka hissa hai', jabke yeh customer ke trust ke saath dhoka hai.",
    tabdeeli:"Apne agle customer ko product ke baare mein ek aisi sach baat bataiye jo aap normally chhupa dete." },
  { id:"der-se-aana-rawayya", title:"Der Se Aana Bhi Ek Rawayya Hai", tags:["Waqt Ki Pabandi","Doosron Ka Haq","Zimmedari"], ic:"⏰", cat:"waqt", color:"#c79a2e",
    en:{"title": "Arriving Late Is Also a Behaviour", "tags": ["Punctuality", "Others' Rights", "Responsibility"], "scene": "'Just 5 minutes.' 'There was traffic.' 'I'm on my way.' And meanwhile someone else has been waiting for 30 minutes.", "masla": "Time does not belong only to us. When someone is waiting for us, their time is also affected by our decision.", "islam": "Keeping promises and respecting others' time is part of Islamic character.", "nabi": null, "galti": "We always justify our lateness as 'being forced', when most of the time it is a lack of planning.", "tabdeeli": "For appointments, meetings, prayers, classes and work, make an effort to arrive on time."},
    scene:"'Bas 5 minute.' 'Traffic tha.' 'Bas nikal raha hoon.', aur doosra insaan 30 minute se intezar kar raha hai.",
    masla:"Waqt sirf hamara nahi hota. Jab koi hamara intezar kar raha hai, toh uska waqt bhi hamare faisle se mutasir ho raha hai.",
    islam:"Waade ki pabandi aur doosron ke waqt ki izzat karna Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum apni derri ko hamesha 'majboori' keh kar justify kar dete hain, jabke zyada tar waqt yeh planning ki kami hoti hai.",
    tabdeeli:"Appointments, meetings, namaz, classes, kaam, har jagah waqt par pahunchne ki koshish kijiye." },
  { id:"tasveer-property-nahi", title:"Dusre Ki Tasveer Aapki Property Nahi", tags:["Permission","Izzat","Digital Adab"], ic:"🖼️", cat:"digital", color:"#5c7cfa",
    en:{"title": "Someone Else's Picture Is Not Your Property", "tags": ["Permission", "Dignity", "Digital Manners"], "scene": "You find someone's photo, a funny video of someone, an embarrassing picture of a friend, and immediately think 'I'll send it to the group'.", "masla": "Stop and ask: did they give permission? Digital technology has made sharing photos easy, but the need for permission has not gone away.", "islam": "Using someone's picture or information without their dignity and consent violates their rights.", "nabi": null, "galti": "We think 'it's just a joke', when for the other person it can be a cause of embarrassment.", "tabdeeli": "Before using someone's picture to embarrass them, stop."},
    scene:"Kisi ki photo mili, kisi ka funny video mila, kisi friend ki embarrassing picture mili, aur foran khayal aaya 'group mein bhej deta hoon'.",
    masla:"Rukiye, kya usne permission di? Digital technology ne photo share karna aasan bana diya hai, lekin permission ki zarurat khatam nahi hui.",
    islam:"Kisi ki izzat aur raza ke bagair uski tasveer ya maloomat istemal karna uske haq ki khilaf-warzi hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sirf mazaak hai', jabke saamne wale ke liye woh embarrassment ka sabab ban sakta hai.",
    tabdeeli:"Kisi ko embarrass karne ke liye uski tasveer istemal karne se pehle ruk jaiye." },
  { id:"dusron-ka-sadqah", title:"Dusron Ka Sadqah Mat Giniye", tags:["Posheedgi","Ikhlaas","Apne Aamaal"], ic:"🙈", cat:"ibadat", color:"#9b6fd6",
    en:{"title": "Do Not Count Other People's Charity", "tags": ["Privacy", "Sincerity", "Your Own Deeds"], "scene": "You are sitting in the masjid. Someone next to you walks towards the donation box. Your eyes move on their own to their hand, and you watch how much they take out and how much they put in.", "masla": "The issue here is not just 'looking', but the calculation that runs in the heart: 'Is that all they gave?' or 'So much, is it just for show?' When we weigh someone else's charity, we interfere where we have no business in the matter between them and Allah, and we become heedless of our own deeds.", "islam": "The value of charity is measured not by the amount but by intention and sincerity. Each person is responsible for their own deeds; on the Day of Judgment each will be questioned about their own actions, not someone else's.", "nabi": "The Prophet ﷺ so loved giving charity in secret that he said: when you give charity with your right hand, let your left hand not know, so that the charity is only for Allah and not to be seen by people.", "galti": "Most of us do not even realise that we are counting someone else's charity. It is a habit that creeps in quietly, not from a sinful intention, but from a wandering of attention.", "tabdeeli": "Next time someone is giving quietly, lower your gaze or turn to your own remembrance of Allah, and stop watching their hand."},
    scene:"Aap masjid mein baithe hain. Bagal mein koi shakhs donation box ki taraf badh raha hai. Aapki nazar khud-ba-khud uske haath ki taraf chali jaati hai, dekhte hain kitna note nikaal raha hai, kitna box mein daal raha hai.",
    masla:"Yahan masla sirf 'dekhna' nahi, balki dil mein chalne wala hisaab hai, 'itna hi diya?' ya 'itna zyada, dikhawa toh nahi?' Jab hum kisi doosre ke sadqe ko tolte hain, toh uske aur Allah ke darmiyan ke maamle mein be-ja dakhal de dete hain, aur apne hi aamaal se ghafil ho jaate hain.",
    islam:"Sadqah ki qadr raqam ki miqdar se nahi, niyyat aur ikhlaas se hoti hai. Har shakhs apne amal ka khud zimmedar hai; Qiyamat ke din bhi har ek se uske apne amal ka hisaab hoga, kisi doosre ke amal ka nahi.",
    nabi:"Nabi ﷺ ne chhup kar sadqah karne ko itna pasand farmaya ke irshad farmaya: jab daahine haath se sadqah karein to baayein haath ko bhi khabar na ho, sadqah sirf Allah ke liye ho, kisi ko dikhane ke liye nahi.",
    galti:"Hum mein se aksar ko yeh ehsaas tak nahi hota ke hum kisi ke sadqe ko gin rahe hain, yeh ek khamoshi se ban jaane wali aadat hai, gunah ki niyyat se nahi, balki tawajjo bhatakne se.",
    tabdeeli:"Agli baar jab koi khamoshi se de raha ho, apni nazrein jhuka lijiye ya apne zikr mein masroof ho jaiye, uske haath ki taraf dekhna chhod dijiye." },
  { id:"dusron-zindagi-mat-khaiye", title:"Dusron Ki Zindagi Ko Mat Khaaiye", tags:["Tajassus","Privacy","Ikhlaas"], ic:"🕵️", cat:"zubaan", color:"#7e6fd6",
    en:{"title": "Do Not Pry Into Other People's Lives", "tags": ["Spying", "Privacy", "Sincerity"], "scene": "'What is his salary?' 'How much is her rent?' 'How much did they pay for the house?' 'How much did the wedding cost?' 'What is going on in their home?' It is not necessary to know everything.", "masla": "There is a difference between curiosity and prying. Digging into someone's private matters without reason takes away their right to privacy.", "islam": "The Quran gives clear guidance to avoid prying and suspicion (Al-Hujurat 49:12).", "nabi": null, "galti": "We justify it by saying 'I just asked', when that question can be uncomfortable for the other person.", "tabdeeli": "Before asking any personal question today, ask yourself: 'Do I really need this information?'"},
    scene:"'Uski salary kitni hai?' 'Uska rent kitna hai?' 'Kitne mein ghar liya?' 'Shaadi mein kitna kharcha hua?' 'Unke ghar mein kya chal raha hai?', har cheez jaan lena zaroori nahi.",
    masla:"Curiosity aur tajassus mein farq hota hai. Kisi ke private maamlaat ko bila wajah khodna uski privacy ka haq cheenna hai.",
    islam:"Qur'an mein tajassus aur bad-gumaani se bachne ki wazeh hidayat di gayi hai (Al-Hujurat 49:12).",
    nabi:null,
    galti:"Hum isay 'bas waise hi pooch liya' keh kar justify kar dete hain, jabke saamne wale ko woh sawal asahaj kar sakta hai.",
    tabdeeli:"Aaj kisi personal sawal se pehle khud se poochiye: 'Kya mujhe waqai is maloomat ki zaroorat hai?'" },
  { id:"forward-se-pehle-tasdeeq", title:"Forward Karne Se Pehle Tasdeeq", tags:["Tahqeeq","Sach","Zimmedari"], ic:"🔍", cat:"digital", color:"#5c7cfa",
    en:{"title": "Verify Before You Forward", "tags": ["Research", "Truth", "Responsibility"], "scene": "'The Hadith says...' 'The doctor said...' 'NASA proved...' 'In Islam this is forbidden...' 'From tomorrow this rule applies...' And we simply forward it.", "masla": "Passing something on without checking can spread false information, especially when it concerns the Deen or a person.", "islam": "The Quran stresses the importance of verifying information, especially when its effects fall on others.", "nabi": null, "galti": "In haste, or with the intention of 'earning reward', we forward things without checking, and they turn out to be false.", "tabdeeli": "Before calling something an Islamic statement a 'Hadith', check its correct source."},
    scene:"'Hadith mein likha hai...' 'Doctor ne kaha hai...' 'NASA ne prove kiya...' 'Islam mein yeh haraam hai...' 'Kal se yeh rule lag raha hai...', aur hum bas forward kar dete hain.",
    masla:"Bina tasdeeq kiye koi baat aage badhana ghalat maloomat failane ka sabab ban sakta hai, khaas kar jab baat Deen ya kisi insaan se mutaliq ho.",
    islam:"Qur'an maloomat ki tasdeeq karne ki ahmiyat batata hai, khaas kar jab uske asraat kisi aur par parte hon.",
    nabi:null,
    galti:"Jaldi mein ya 'sawab ki niyyat' se hum bina check kiye hi aisi baatein forward kar dete hain jo ghalat nikalti hain.",
    tabdeeli:"Kisi Islami baat ko 'Hadith' kehne se pehle uska sahi hawala check kijiye." },
  { id:"gaadi-chala-rahe-gussa-nahi", title:"Gaadi Chala Rahe Hain, Gussa Nahi", tags:["Sabr","Driving","Akhlaq"], ic:"🚘", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "Driving, Not Getting Angry", "tags": ["Patience", "Driving", "Character"], "scene": "Someone overtook us, someone did not signal, an auto suddenly came in front of us, a bike cut in. And our mood is spoiled: the horn, abuse, chasing, aggressive driving.", "masla": "We cannot always control other people's mistakes on the road, but we can control our own reaction.", "islam": "Controlling anger and dealing with things patiently, whether on the road or at home, is part of Islamic character.", "nabi": null, "galti": "We make another driver's small mistake a matter of our honour, when it is only an ordinary human error.", "tabdeeli": "Today, when someone irritates you on the road, consciously take a deep breath and say to yourself: 'I need to control my reaction.'"},
    scene:"Kisi ne overtake kar diya, kisi ne indicator nahi diya, auto suddenly saamne aa gaya, bike beech mein aa gayi, aur hamara mood kharab, horn, abuse, chasing, aggressive driving.",
    masla:"Road par doosron ki galtiyan hamesha hamare control mein nahi, lekin apna reaction control karna hamare haath mein hota hai.",
    islam:"Gussa zabt karna aur sabr se kaam lena har halat mein, chahe road par ho ya ghar mein, Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum road par dusron ki chhoti galti ko bhi apni izzat ka sawal bana lete hain, jabke woh sirf ek aam insani ghalti hoti hai.",
    tabdeeli:"Aaj road par koi irritate kare, consciously ek lambi saans lijiye aur khud se kahiye: 'Mujhe apna reaction control karna hai.'" },
  { id:"ghar-bahar-achha-bartao", title:"Ghar Walon Se Achha Bartao Bahar Walon Se Bhi Zaroori Hai", tags:["Akhlaq","Ghar","Rishtey"], ic:"❤️", cat:"ghar", color:"#d6708f",
    en:{"title": "Good Treatment at Home Is Even More Important Than Outside", "tags": ["Character", "Home", "Family"], "scene": "At the office, 'Thank you!'; at a restaurant, 'Please'; with friends, 'Brother!'; and at home, 'Be quiet!' Sometimes we show our best side to strangers and our worst to our own family.", "masla": "The real test is often where we feel most comfortable: at home.", "islam": "Good character with family is just as important as with people outside, and their right comes first.", "nabi": null, "galti": "We think 'my family is 'mine', so harshness is fine with them', when this very thinking weakens relationships.", "tabdeeli": "Today, show someone at home the same gentleness you show a guest."},
    scene:"Office mein 'Thank you!', restaurant mein 'Please', friends ke saath 'Bhai jaan!', aur ghar mein 'Chup karo!' Kabhi hum ajnabiyon ko apna best version dikhate hain aur apne ghar walon ko apna worst.",
    masla:"Asal imtihan aksar wahi hota hai jahan hum sabse zyada comfortable hote hain, apne ghar mein.",
    islam:"Ghar walon ke saath husn-e-akhlaq utna hi zaroori hai jitna bahar ke logon ke saath, balki unka haq pehle hai.",
    nabi:null,
    galti:"Hum sochte hain ghar wale toh 'apne' hain, isliye unke saath sakhti chalti hai, jabke yehi soch rishton ko kamzor kar deti hai.",
    tabdeeli:"Aaj ghar mein kisi ek shakhs se wohi narmi dikhaiye jo aap kisi mehmaan ke saath dikhate hain." },
  { id:"gheebat-forwarded-message", title:"Gheebat Ka Naya Naam: 'Forwarded Message'", tags:["Gheebat","Zubaan","Amanat"], ic:"🗣️", cat:"digital", color:"#5c7cfa",
    en:{"title": "Backbiting's New Name: 'Forwarded Message'", "tags": ["Backbiting", "Speech", "Trust"], "scene": "In the past, people sat face to face and spoke badly of someone. Today we send screenshots, forward voice notes, circulate private photos, and then say: 'I'm just passing it on.'", "masla": "If someone's faults are discussed in their absence in a way they would dislike if they knew, that is backbiting, whatever the medium.", "islam": "The Quran describes backbiting as eating the flesh of one's dead brother. It is a strictly forbidden act.", "nabi": null, "galti": "We justify it as 'just sharing information', when often the intention is simply to describe someone's faults.", "tabdeeli": "Before forwarding anything, ask yourself: 'Is this turning into backbiting?'"},
    scene:"Pehle log saamne baith kar kisi ki burai karte the. Aaj hum screenshot bhejte hain, voice note forward karte hain, private photo circulate karte hain, aur phir kehte hain: 'Bas bata raha hoon.'",
    masla:"Agar kisi ki ghair-maujoodgi mein uski aisi baat discuss ho rahi hai jo usay maloom ho toh bura lage, toh yeh gheebat hi hai, chahe medium koi bhi ho.",
    islam:"Gheebat ko Qur'an mein apne mare hue bhai ka gosht khane jaisa bataya gaya hai, yeh ek sakht mana amal hai.",
    nabi:null,
    galti:"Hum isay 'sirf information share karna' samajh kar justify kar dete hain, jabke niyyat aksar burai bayan karna hi hoti hai.",
    tabdeeli:"Koi forward karne se pehle poochiye: 'Kya yeh gheebat toh nahi ban rahi?'" },
  { id:"glass-paani-chhodna", title:"Glass Mein Paani Chhodna Bhi Sochiye", tags:["Israf","Wasail","Zimmedari"], ic:"🥛", cat:"maahol", color:"#4caf7d",
    en:{"title": "Think Before Leaving Water in the Glass", "tags": ["Wastefulness", "Resources", "Responsibility"], "scene": "At a restaurant you ask for water, drink two glasses, leave half a glass, and then order a fresh one.", "masla": "Water seems unlimited because it comes as soon as the tap is opened, but resources are not unlimited.", "islam": "The principle of avoiding wastefulness applies not only to food, but to every daily use.", "nabi": null, "galti": "We think of water as a 'free' resource, when it too is a blessing of Allah that deserves gratitude and protection.", "tabdeeli": "Pour only as much water into your glass as you can drink."},
    scene:"Restaurant mein paani manga, do glass piya, aadha glass chhod diya, phir naya le liya.",
    masla:"Paani unlimited lagta hai kyunke nal kholte hi aa jaata hai, lekin resources unlimited nahi hain.",
    islam:"Israf se bachne ka usool sirf khane par nahi, rozana ki har consumption par lagu hota hai.",
    nabi:null,
    galti:"Hum paani ko 'free' resource samajh lete hain, jabke yeh bhi Allah ki ek nemat hai jiska shukr aur hifazat zaroori hai.",
    tabdeeli:"Glass mein utna hi paani lijiye jitna aap pee sakte hain." },
  { id:"gussa-reaction-mat-do", title:"Gussa Aaya Toh Reaction Na Dijiye", tags:["Sabr","Tahammul","Pachhtawa Se Bachna"], ic:"😤", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "When Angry, Do Not React", "tags": ["Patience", "Tolerance", "Avoiding Regret"], "scene": "Anger is human. But sending a message in anger, threatening, ending a relationship, insulting someone, posting on social media, or embarrassing someone at the office can all become a source of regret later.", "masla": "A decision made in anger often causes the very harm that we would never do in a calm state.", "islam": "Controlling anger and acting with patience is a very great principle of character.", "nabi": "The Prophet ﷺ said: the strong man is not the one who wins a wrestling bout, the strong man is the one who controls himself when angry.", "galti": "We treat anger as our 'truth', when it is only a passing emotion that goes away.", "tabdeeli": "When anger comes, instead of responding at once, pause for a while. Make 'Anger = Pause' your principle."},
    scene:"Gussa aana insani hai. Lekin gusse mein message bhejna, dhamki dena, rishta todna, insult karna, social media par post karna, ya kisi ko office mein embarrass karna, yeh sab baad mein pachhtawe ka sabab ban sakta hai.",
    masla:"Gusse mein liya gaya faisla aksar woh nuqsan pahunchata hai jo sahi halat mein hum kabhi na karte.",
    islam:"Ghussa zabt karna aur sabr se kaam lena bohot bada akhlaqi usool hai.",
    nabi:"Nabi ﷺ ne farmaya: taaqatwar woh nahi jo kushti mein jeete, taaqatwar woh hai jo gusse ke waqt apne aap par qabu rakhe.",
    galti:"Hum gusse ko apni 'sacchai' samajh lete hain, jabke woh sirf ek waqti jazbaat hota hai jo guzar jaata hai.",
    tabdeeli:"Jab gussa aaye, turant response dene ke bajaye kuch waqt ka waqfa lijiye, 'Gussa = Pause' ko apna usool banaiye." },
  { id:"har-baat-jawab-nahi", title:"Har Baat Ka Jawab Dena Zaroori Nahi", tags:["Khamoshi","Sabr","Pukhta-Fehmi"], ic:"🔕", cat:"zubaan", color:"#7e6fd6",
    en:{"title": "You Do Not Have to Answer Everything", "tags": ["Silence", "Patience", "Good Judgement"], "scene": "Someone said something on WhatsApp, someone provoked us in an Instagram comment, someone taunted us at the office, and we reply immediately. Then another reply, then a counter-reply, and 30 minutes later we realise we have lost both our time and our peace.", "masla": "It is not necessary to answer everything, and it is not necessary to win every argument.", "islam": "Avoiding pointless arguments and keeping the tongue under control is part of Islamic character.", "nabi": "In the Prophet ﷺ's teaching, saying something good or remaining silent is a basic principle (Sahih Bukhari 6475).", "galti": "We think that staying silent is 'admitting defeat', when sometimes leaving a conversation is the real wisdom.", "tabdeeli": "Next time someone provokes you online, before replying ask yourself: 'Will anything be gained from this argument?'"},
    scene:"WhatsApp par kisi ne kuch kaha, Instagram comment mein kisi ne provoke kiya, office mein kisi ne taunt kiya, aur hum turant reply karte hain. Phir woh reply, phir counter-reply, aur 30 minute baad pata chalta hai ke hum apna waqt aur sukoon dono kho chuke hain.",
    masla:"Har baat ka jawab dena zaroori nahi, aur har argument jeetna bhi zaroori nahi.",
    islam:"Fuzool bahason se bachna aur zaban ko qabu mein rakhna Islami akhlaaq ka hissa hai.",
    nabi:"Nabi ﷺ ki taleem mein achhi baat kehna ya khamosh rehna ek bunyadi usool hai (Sahih Bukhari 6475).",
    galti:"Hum sochte hain ke khamosh rehna 'haar maanna' hai, jabke kabhi conversation chhod dena hi asal samajhdari hai.",
    tabdeeli:"Agli baar koi online provoke kare, reply dene se pehle khud se poochiye: 'Kya is bahas se kuch hasil hoga?'" },
  { id:"comparison-zaroori-nahi", title:"Har Cheez Mein Apna Comparison Zaroori Nahi", tags:["Shukr","Qanaat","Sukoon"], ic:"📊", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "You Don't Need to Compare Yourself in Everything", "tags": ["Gratitude", "Contentment", "Peace"], "scene": "They have a car. Their house is big. Their salary is higher. They got married. They have children. They have the latest phone. And we start comparing our whole life to their highlight reel.", "masla": "Comparison often eats away at gratitude. The blessings Allah has given us lose their value because of comparison.", "islam": "Being content with Allah's distribution and thanking Him for our blessings is part of faith.", "nabi": null, "galti": "Without realising it, we see only the 'best moments' of others on social media and start measuring our whole life against theirs.", "tabdeeli": "Today, when the thought of comparing yourself to someone comes, immediately remember three of your own blessings."},
    scene:"Uske paas car hai. Uska ghar bada hai. Uski salary zyada hai. Uski shaadi ho gayi. Uske bachche hain. Uske paas latest phone hai, aur hum apni zindagi ko uski highlight reel se compare karna shuru kar dete hain.",
    masla:"Comparison aksar shukr ko kha jaata hai. Jo kuch Allah ne hamein diya hai, uski qadr comparison ki wajah se dhundli pad jaati hai.",
    islam:"Allah ki taqseem par raazi rehna aur apni nematon ka shukr ada karna Imaan ka hissa hai.",
    nabi:null,
    galti:"Hum jaane-anjaane social media par doosron ki zindagi ke sirf 'best moments' dekh kar apni poori zindagi ko unke saath tolne lagte hain.",
    tabdeeli:"Aaj kisi se comparison ka khayal aaye, toh foran apni teen nematein yaad kijiye." },
  { id:"status-daalna-zaroori-nahi", title:"Har Cheez Status Par Daalna Zaroori Nahi", tags:["Niji Khushi","Riya Se Bachna","Sukoon"], ic:"📵", cat:"digital", color:"#5c7cfa",
    en:{"title": "You Don't Need to Post Everything as a Status", "tags": ["Personal Happiness", "Avoiding Showing Off", "Peace"], "scene": "Food, a trip, a new phone, a gift, a salary, shopping, the home, a relationship: it is not necessary to make every moment public.", "masla": "Some happiness belongs only to you and your loved ones. The constant desire to show others can sometimes reduce the real joy itself.", "islam": "Keeping one's intention sincere and avoiding showing off one's blessings is part of Islamic manners.", "nabi": null, "galti": "As soon as we hear good news, we first think of posting a status, instead of first feeling that moment ourselves.", "tabdeeli": "When something good happens today, instead of posting a status at once, enjoy it quietly for a while."},
    scene:"Khana, trip, new phone, gift, salary, shopping, ghar, relationship, har moment ko public karna zaroori nahi.",
    masla:"Kuch khushiyan sirf aapki aur aapke apno ki bhi ho sakti hain. Har waqt dusron ko dikhane ki chahat kabhi-kabhi asal khushi ko hi kam kar deti hai.",
    islam:"Niyyat ko khalis rakhna aur apni nematon ki numaish se bachna Islami adab ka hissa hai.",
    nabi:null,
    galti:"Hum kisi achhi khabar ke milte hi sabse pehle status lagane ki soch lete hain, bajaye iske ke pehle us lamhe ko khud mehsoos karein.",
    tabdeeli:"Aaj kuch achha ho toh foran status lagane ke bajaye usay kuch der sirf enjoy kijiye." },
  { id:"jism-amanat", title:"Jism Bhi Allah Ki Amanat Hai", tags:["Warzish","Taaqat","Jismani Sargarmi"], ic:"💪", cat:"sehat", color:"#e0893f",
    en:{"title": "The Body Is Also a Trust from Allah", "tags": ["Exercise", "Strength", "Physical Activity"], "scene": "From morning till night we sit at a desk, look at the phone, eat, and then sleep. In the whole day the body may have walked only a few steps.", "masla": "When physical movement disappears from life, weakness and laziness quietly take its place. We understand health only as a matter of prayer or medicine, when the body itself is also a trust, and protecting it is a duty upon us.", "islam": "In Islam, strength and health are considered desirable. Strength is not just something that can be seen; it is the ability by which a person can worship his Lord better and fulfil his responsibilities well.", "nabi": "The Prophet ﷺ said that the strong believer is better and more beloved to Allah than the weak believer, and he taught that every believer should strive for what benefits him (Sahih Muslim 2664). The Prophet ﷺ himself used to race with Hazrat Aisha RA.", "galti": "We often think 'I don't have time' or 'I'll start tomorrow', when even a small daily effort can be a way of protecting this trust.", "tabdeeli": "Include a daily 15-20 minute walk or some light physical activity in your routine."},
    scene:"Subah se raat tak kursi par baithe kaam kiya, phone dekha, khaana khaya, phir so gaye. Poore din mein jism ne shayad chand kadam hi chale.",
    masla:"Jab jismani harkat zindagi se nikal jaati hai, kamzori aur susti chup-chaap jagah bana leti hai. Hum sehat ko sirf dua ya dawa tak samajh lete hain, jabke jism khud bhi ek amanat hai jiski hifazat hum par farz hai.",
    islam:"Islam mein taaqat aur sehat ko pasandeedah qarar diya gaya hai. Taaqat sirf dikhne ki cheez nahi, balki woh salahiyat hai jisse insan apne Rab ki ibadat behtar tareeqe se kar sake aur apni zimmedariyan behtar nibha sake.",
    nabi:"Nabi ﷺ ne farmaya ke taaqatwar momin, kamzor momin se behtar aur Allah ko zyada mehboob hai, aur sath yeh taleem di ke har momin faida-mand cheez hasil karne ki koshish kare (Sahih Muslim 2664). Nabi ﷺ khud Hazrat Aisha RA ke sath daudne ka musabaqa karte the.",
    galti:"Aksar hum sochte hain 'waqt nahi milta' ya 'kal se shuru karunga', jabke chhoti si rozana koshish bhi is amanat ki hifazat ka zariya ban sakti hai.",
    tabdeeli:"Rozana sirf 15-20 minute ki sair ya koi halki jismani sargarmi apni routine mein shamil kijiye." },
  { id:"kaam-karne-wala-chhota-nahi", title:"Kaam Karne Wale Ko Chhota Na Samjhiye", tags:["Mehnat Ki Izzat","Huqooq","Insaniyat"], ic:"👷", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "Do Not Think of a Worker as Lesser", "tags": ["Respect for Work", "Rights", "Humanity"], "scene": "Driver, cleaner, delivery boy, security guard, domestic worker, office assistant, construction worker. We use their services, but do we also give them respect?", "masla": "A person's profession does not decide their human worth. The one who does a job that seems small is not small.", "islam": "Islam gives great importance to the rights of workers and those who serve.", "nabi": "The Prophet ﷺ's teachings took the rights of workers seriously. He is famously recorded as instructing that a worker's wage be paid before his sweat dries (Ibn Majah 2443).", "galti": "Even without meaning to, we use a tone with them that is different from the tone we use with a 'big' officer. We need to notice this difference in ourselves.", "tabdeeli": "Today, thank someone whose work is often overlooked."},
    scene:"Driver, cleaner, delivery boy, security guard, domestic worker, office assistant, construction worker, hum unki service use karte hain, lekin kya hum unko izzat bhi dete hain?",
    masla:"Kisi ka profession uski insani qeemat decide nahi karta. Jo kaam chhota lagta hai, uska karne wala chhota nahi hota.",
    islam:"Mazdoor aur khidmatgaar ke huqooq ko Islam mein bohot ahmiyat di gayi hai.",
    nabi:"Nabi ﷺ ki taleemaat mein workers ke huqooq ko seriously liya gaya hai, mazdoor ki ujrat usko uska paseena sukhne se pehle dene ki hidayat mashhoor hai (Ibn Majah 2443).",
    galti:"Hum na chahte hue bhi apni baat mein ek lehja istemal kar lete hain jo kisi 'bade' officer se alag hota hai, yeh farq khud mehsoos karna zaroori hai.",
    tabdeeli:"Aaj kisi aise shakhs ka shukriya ada kijiye jiska kaam aksar nazar-andaz hota hai." },
  { id:"kaam-kal-par-mat-daliye", title:"Kaam Ko Kal Par Mat Daliye", tags:["Zimmedari","Waqt","Stress Se Bachna"], ic:"🗓️", cat:"waqt", color:"#c79a2e",
    en:{"title": "Do Not Put Work Off Until Tomorrow", "tags": ["Responsibility", "Time", "Avoiding Stress"], "scene": "The email later, the assignment later, the bills later, the important call later, the document later. Then the deadline arrives and we work under stress.", "masla": "Not every delay is laziness, but deliberately postponing an important responsibility again and again can become a habit that harms us.", "islam": "Completing our responsibilities on time is part of keeping a trust.", "nabi": null, "galti": "We think 'I'll have more time tomorrow', when tomorrow will be just as busy as today.", "tabdeeli": "Choose one task you have been postponing for days, and give it just 15 minutes today."},
    scene:"Email baad mein, assignment baad mein, bills baad mein, important call baad mein, document baad mein, phir deadline aa jaati hai aur hum stress mein kaam karte hain.",
    masla:"Har derri laziness nahi hoti, lekin jaan-boojh kar zaroori zimmedari ko baar baar postpone karna ek aadat ban sakta hai jo khud hamare liye takleef-deh hai.",
    islam:"Apni zimmedariyon ko waqt par poora karna amanat ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'kal zyada waqt milega', jabke kal bhi utna hi masroof hota hai jitna aaj.",
    tabdeeli:"Aaj ek aisa kaam chuniye jo aap kai din se postpone kar rahe hain aur sirf 15 minute usi par laga dijiye." },
  { id:"kachra-sirf-kachra-nahi", title:"Kachra Sirf Kachra Nahi", tags:["Ijtimaai Safai","Zimmedari","Imaan"], ic:"🗑️", cat:"maahol", color:"#4caf7d",
    en:{"title": "Rubbish Is Not Just Rubbish", "tags": ["Public Cleanliness", "Responsibility", "Faith"], "scene": "You leave a restaurant with a cup in your hand. The bin is five metres away, but you put the cup on a bench and walk off.", "masla": "This small act is not 'just one cup'. For the next person passing that way, it becomes dirt and a nuisance. We think cleanliness is limited to our home or the masjid, when keeping roads, parks and stations clean is also our responsibility.", "islam": "One of the branches of faith is removing something harmful from the road. Keeping one's own place clean is not enough; protecting others' path is also part of the Deen.", "nabi": "The Prophet ﷺ described removing something harmful from the road as a charity and a branch of faith.", "galti": "We think 'what difference can such a small thing make?', but when everyone thinks this way, the whole road fills with filth.", "tabdeeli": "Wherever you go, carry your own rubbish to a bin yourself, even if it is a few steps away."},
    scene:"Aap restaurant se nikle. Cup haath mein tha. Dustbin 5 metre door tha, lekin aapne cup wahin bench par rakh diya aur chal diye.",
    masla:"Yeh chhota sa amal 'sirf ek cup' nahi, is raaste se guzarne wale agle insaan ke liye woh gandagi aur takleef ban jaata hai. Hum safai ko apne ghar ya masjid tak mehdood samajh lete hain, jabke raaste, park, station, sab jagah ki safai bhi hamari zimmedari hai.",
    islam:"Imaan ke darjaat mein se ek yeh bhi hai ke raaste se takleef-deh cheez hata di jaye. Yani apni jagah saaf rakhna kaafi nahi, doosron ke raaste ko mehfooz rakhna bhi deen ka hissa hai.",
    nabi:"Nabi ﷺ ne raaste se takleef-deh cheez hatane ko sadqah aur Imaan ki ek shaakh qarar diya.",
    galti:"Hum sochte hain 'itni si cheez se kya farq padega', lekin yahi soch jab sab log rakhte hain, poora raasta gandagi se bhar jaata hai.",
    tabdeeli:"Jahan bhi guzrein, apne haath ki cheez khud dustbin tak le jaiye, chahe woh chand kadam door hi kyun na ho." },
  { id:"khane-ki-burai-mat-kijiye", title:"Khane Ki Burai Mat Kijiye", tags:["Shukr","Mehnat Ki Qadar","Adab"], ic:"🍲", cat:"khana", color:"#c0563f",
    en:{"title": "Do Not Criticise the Food", "tags": ["Gratitude", "Respect for Effort", "Manners"], "scene": "'What is this you made?' 'It's completely useless.' 'It has no taste.' Not liking a food is one thing, but insulting the effort of the person who cooked it is another.", "masla": "When we criticise food, we are not only belittling the food, but also the effort that someone put in for us.", "islam": "The way we show dislike for food should also be done with good manners.", "nabi": "The Prophet ﷺ's way with food gives an example: if he did not like a food, he would leave it, without criticising it.", "galti": "Sometimes in jest and sometimes in the name of honesty, we criticise the food so much that the cook's heart is broken.", "tabdeeli": "Don't like it? Simply say politely: 'I may not like this, so I'll have something else.'"},
    scene:"'Yeh kya bana diya?' 'Bilkul bekaar hai.' 'Isme taste hi nahi.' Kisi khane ko pasand na karna alag baat hai, lekin use banane wale ki mehnat ko insult karna alag.",
    masla:"Jab hum khane ki burai karte hain, toh sirf khana nahi, us mehnat ko bhi kam-tar kehte hain jo kisi ne hamare liye ki.",
    islam:"Khane ki na-pasandeedgi zahir karne ka tareeqa bhi adab se hona chahiye.",
    nabi:"Nabi ﷺ ke tarz-e-khana mein yeh misaal milti hai ke agar koi khana pasand na aaye toh usay chhod dijiye, uski burai mat kijiye.",
    galti:"Hum kabhi majak mein, kabhi sacchai ke naam par khane ki itni tanqeed kar dete hain ke banane wale ka dil toot jaaye.",
    tabdeeli:"Pasand nahi? Bas politely keh dijiye: 'Mujhe shayad yeh pasand nahi, main kuch aur le leta hoon.'" },
  { id:"paisa-rokna-chhoti-baat-nahi", title:"Kisi Ka Paisa Rokna Chhoti Baat Nahi", tags:["Haq","Zulm","Zimmedari"], ic:"💸", cat:"maal", color:"#b8860b",
    en:{"title": "Withholding Someone's Money Is Not a Small Matter", "tags": ["Rights", "Injustice", "Responsibility"], "scene": "A salary is delayed, a freelancer's payment is delayed, a worker's pay is delayed, a refund is held back, a commission is held back, and we keep saying 'I'll pay tomorrow'.", "masla": "If you have the means to pay someone's right and yet deliberately delay it, this is not just delay, it is injustice.", "islam": "Withholding someone's right when you are able to pay it is a severely disliked act in Islam.", "nabi": "It is reported from the Prophet ﷺ that a wealthy person delaying the repayment of a debt is an injustice (Jami' at-Tirmidhi).", "galti": "We think 'a small delay will make no difference', when the other person's household budget may depend on that money.", "tabdeeli": "If a payment is pending, set an exact date instead of saying 'I'll pay sometime'."},
    scene:"Salary delay, freelancer ka payment delay, worker ka payment delay, refund rokna, commission rokna, 'kal de denge' kehte rehna.",
    masla:"Agar aapke paas kisi ka haq dene ki salahiyat hai aur phir bhi jaan-boojh kar derri kar rahe hain, toh yeh sirf derri nahi, zyadti hai.",
    islam:"Kisi ka haq rokna, jabke dene ki istita'at ho, Islam mein sakht na-pasandeedah amal hai.",
    nabi:"Nabi ﷺ se riwayat hai ke maldaar shakhs ka qarz ki adaigi mein derri karna zulm hai (Jami' at-Tirmidhi).",
    galti:"Hum sochte hain 'thodi derri se kya farq padega', jabke saamne wale ka ghar ka kharcha usi paise par rukha ho sakta hai.",
    tabdeeli:"Kisi ka payment pending hai toh 'kabhi de denge' ke bajaye exact tareekh tay kijiye." },
  { id:"majboori-tamasha-nahi", title:"Kisi Ki Majboori Ko Tamasha Mat Banaiye", tags:["Izzat-e-Nafs","Hamdardi","Akhlaq"], ic:"🎭", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "Do Not Turn Someone's Hardship into a Spectacle", "tags": ["Self-Respect", "Empathy", "Character"], "scene": "Someone's clothes are old. Someone does not have a good phone. Someone is in financial trouble. Someone's English is weak. Someone is physically slow. Someone made a mistake in public.", "masla": "Is it necessary to take out a phone and film at such a moment? Is it necessary to mock them in a friends' group? A person's weakness should never become a source of entertainment for us.", "islam": "An important part of Islamic character is protecting a person's dignity.", "nabi": null, "galti": "Sometimes in jest and sometimes in the hunt for content for social media, we unknowingly turn someone's hardship into a spectacle.", "tabdeeli": "The next time you notice someone's weakness, see the person, not content."},
    scene:"Kisi ke kapde purane hain. Kisi ke paas achha phone nahi. Koi financial problem mein hai. Kisi ki English weak hai. Koi physically slow hai. Kisi ko public mein galti ho gayi.",
    masla:"Kya us waqt phone nikal kar video banana zaroori hai? Kya friends ke group mein uski mazaak banana zaroori hai? Kisi ki kamzori hamare liye tafreeh ka zariya nahi honi chahiye.",
    islam:"Islami akhlaaq ka ek important hissa insaan ki izzat-e-nafs (dignity) ko mehfooz rakhna hai.",
    nabi:null,
    galti:"Hum kabhi mazaak mein, kabhi social media ke liye content ki talaash mein kisi ki majboori ko unknowingly tamasha bana dete hain.",
    tabdeeli:"Aaj kisi ki weakness notice ho toh usay content nahi, insaan samjhiye." },
  { id:"line-mein-haq", title:"Line Mein Apna Haq, Dusron Ka Bhi Haq", tags:["Qataar","Usool","Ijtimaai Nazm-o-Zabt"], ic:"🚦", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "Your Place in the Queue Is Your Right, and So Is Everyone Else's", "tags": ["Queue", "Principles", "Public Order"], "scene": "You have been standing at the billing counter for 20 minutes. Others are waiting behind you too. Suddenly someone pushes in front, saying 'just one minute'.", "masla": "This is not only breaking a queue. That person has not only saved his own time; he has also taken the time and right of everyone standing behind.", "islam": "Wherever our right meets someone else's right, courtesy and fairness are needed. Violating others' rights, even the right to time, is a disliked act in Islam.", "nabi": "The Prophet ﷺ taught Muslims justice and equality among themselves, and forbade interfering unjustly with someone's right.", "galti": "In haste we tell ourselves 'my work is important', but we forget that the work of every person in the queue is just as important.", "tabdeeli": "Wait patiently for your turn, whether in a queue or in traffic. Take your right, but only as much as is yours."},
    scene:"Aap 20 minute se billing counter ki line mein khade hain. Peeche bhi kai log intezar mein hain. Achanak koi 'bas ek minute' kehte hue beech mein ghus jaata hai.",
    masla:"Yeh sirf line todna nahi, us shakhs ne sirf apna waqt nahi bachaya, balki peeche khade har insaan ka waqt aur haq bhi chheen liya.",
    islam:"Jahan bhi hamara haq kisi doosre ke haq se juda ho, wahan adab aur insaaf zaroori hai. Doosron ka haq maarna, chahe woh waqt ka hi haq kyun na ho, Islam mein na-pasandeedah amal hai.",
    nabi:"Nabi ﷺ ne musalmanon ko aapas mein insaaf aur baraabari ki taleem di, aur kisi ke haq mein na-haq dakhal-andaazi se mana farmaya.",
    galti:"Jaldi mein hum khud se keh dete hain 'mera kaam zaroori hai', lekin bhool jaate hain ke line mein khade har shakhs ka kaam bhi usi tarah zaroori hai.",
    tabdeeli:"Apni baari ka sabr se intezar kijiye, line ho ya traffic, apna haq utna hi lijiye jitna aapka hai." },
  { id:"maafi-maangna-chhota-nahi", title:"Maafi Maangne Mein Chhota Kaun Ho Gaya?", tags:["Inkisaar","Sach","Rishte"], ic:"🙏", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "Who Becomes Smaller When Asking for Forgiveness?", "tags": ["Humility", "Truth", "Relationships"], "scene": "'It was my fault' is hard to say. We give explanations: 'Yes, but he did it first', 'I did it because...', 'Actually, I didn't mean it that way...'", "masla": "Sometimes a simple 'I made a mistake, please forgive me' is enough, but instead we start giving explanations.", "islam": "Admitting one's mistake is not weakness; it is a sign of humility and good character.", "nabi": null, "galti": "We take justification for an apology, when the other person only wants to hear that we realise our mistake.", "tabdeeli": "If you have recently made a mistake with someone, offer a straightforward apology before any justification."},
    scene:"'Galti meri thi' kehna mushkil hai. Hum explanation dete hain: 'Haan, lekin usne pehle...', 'Maine isliye kiya kyunki...', 'Actually meri intention yeh nahi thi...'",
    masla:"Kabhi-kabhi simple 'mujhse galti hui, mujhe maaf kar do' itna hi kaafi hota hai, lekin hum iski jagah safai dene lagte hain.",
    islam:"Apni ghalti tasleem karna kamzori nahi, balki inkisaar aur achhe akhlaaq ki nishani hai.",
    nabi:null,
    galti:"Hum justification ko maafi samajh lete hain, jabke saamne wala sirf itna sunna chahta hai ke hamari ghalti ka ehsaas hai.",
    tabdeeli:"Agar kisi se aapki recent galti hui hai, justification se pehle seedhi maafi dijiye." },
  { id:"masjid-adab", title:"Masjid Mein Sirf Namaz Nahi, Adab Bhi Hai", tags:["Masjid Ka Adab","Sukoon","Ikhlaas"], ic:"🕌", cat:"ibadat", color:"#9b6fd6",
    en:{"title": "A Masjid Has Manners as Well as Prayer", "tags": ["Masjid Etiquette", "Peace", "Sincerity"], "scene": "We go to the masjid and pray, but do we also think about our conduct? Leaving shoes scattered about, leaving a gap in the row, keeping the phone loud, standing among people with a bad smell, leaving rubbish in the masjid.", "masla": "In the masjid, along with worship, we should also consider the peace of the other worshippers. It is not enough just to complete our own prayer.", "islam": "The masjid is the House of Allah, and everyone who comes there has a right to a peaceful and well-mannered environment.", "nabi": "The Prophet ﷺ taught that people should be protected from discomfort caused by smells when coming to the masjid.", "galti": "We think 'I've only come for prayer', and ignore these small matters, when these very small matters also affect the devotion of others.", "tabdeeli": "Before going to the masjid, take care of your clothes, your body and your breath."},
    scene:"Masjid mein jaakar hum namaz padhte hain, lekin kya hum apne rawayye ka bhi khayal rakhte hain? Jootay idhar-udhar rakh dena, saf mein jagah chhod dena, phone loud rakhna, badbu ke saath logon ke darmiyan khade hona, masjid mein kachra chhod dena.",
    masla:"Masjid mein ibadat ke saath doosre musalliyon ke sukoon ka bhi khayal hona chahiye, sirf apni namaz mukammal karna kaafi nahi.",
    islam:"Masjid Allah ka ghar hai, aur wahan aane wale har insaan ka haq hai ke usay sukoon aur adab ka maahol mile.",
    nabi:"Nabi ﷺ ne badbu wali cheez kha kar masjid mein aane ke hawale se doosre logon ko takleef se bachane ki taleem di.",
    galti:"Hum sochte hain 'main toh sirf namaz ke liye aaya hoon', aur in chhoti baaton ko ignore kar dete hain, jabke yahi chhoti baatein doosron ke khushu ko bhi mutasir karti hain.",
    tabdeeli:"Masjid mein jaane se pehle apne kapde, body aur breath ka khayal rakhiye." },
  { id:"mehmaan-phone-side", title:"Mehmaan Aaye Toh Phone Side Mein Rakhiye", tags:["Mehmaan-Nawazi","Tawajjo","Adab"], ic:"📴", cat:"ghar", color:"#d6708f",
    en:{"title": "When a Guest Comes, Put the Phone Aside", "tags": ["Hospitality", "Attention", "Manners"], "scene": "A guest arrives, we say 'Come in, come in!', then we take out the phone: WhatsApp, Instagram, reels, messages. The guest is sitting in front of us, but our attention is on the screen.", "masla": "Hospitality is not just serving food; giving your time is also part of hospitality.", "islam": "Honouring a guest and giving them full attention is part of Islamic manners.", "nabi": null, "galti": "We think 'I'll just check one message', but the guest feels the incomplete attention immediately.", "tabdeeli": "While a guest is in your home, put your phone aside."},
    scene:"Guest aaya, hum kehte hain 'Aaiye aaiye!' phir phone khola, WhatsApp, Instagram, reels, messages. Guest saamne baitha hai, lekin tawajjo screen par.",
    masla:"Hospitality sirf khana serve karna nahi, apna waqt dena bhi mehmaan-nawazi ka hissa hai.",
    islam:"Mehmaan ki izzat aur uski taraf poori tawajjo dena Islami adab ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'bas ek message dekh leta hoon', jabke guest ko yeh adhoori tawajjo foran mehsoos ho jaati hai.",
    tabdeeli:"Mehmaan ke saamne phone side mein rakh dijiye jab tak woh ghar mein hai." },
  { id:"mehmaan-ghar-hisab-nahi", title:"Mehmaan Ke Ghar Har Cheez Ka Hisab Mat Lagaiye", tags:["Mehmaan-Nawazi","Qanaat","Izzat"], ic:"🏡", cat:"ghar", color:"#d6708f",
    en:{"title": "Do Not Count Everything in a Host's Home", "tags": ["Hospitality", "Contentment", "Honour"], "scene": "'How many dishes are there?' 'How big is the AC?' 'How much does the furniture cost?' 'How much was spent on the wedding?' Sometimes we go as guests and come back as auditors.", "masla": "Hospitality means not only eating the food, but also respecting the host's honour and effort.", "islam": "Honouring guests and accepting their hospitality with the right intention is Islamic manners.", "nabi": null, "galti": "The habit of calculating costs stops us from seeing the effort and intention of others; we are left looking only at numbers.", "tabdeeli": "Next time you visit someone's home, instead of calculating the cost, appreciate the host's effort."},
    scene:"'Kitne dishes hain?' 'AC kitna bada hai?' 'Furniture kitne ka hoga?' 'Shaadi mein kitna kharcha hua?', kabhi hum mehmaan bankar jaate hain aur auditor bankar wapas aate hain.",
    masla:"Mehmaan-nawazi ka matlab sirf khana khana nahi, host ki izzat aur uski mehnat ki qadr karna bhi hai.",
    islam:"Mehmaanon ki izzat karna aur unki mehmaan-nawazi ko sahi niyyat se qubool karna Islami adab hai.",
    nabi:null,
    galti:"Hisaab-kitaab lagane ki aadat hamein doosron ki mehnat aur niyyat dekhne se rok deti hai, hum sirf numbers dekhte reh jaate hain.",
    tabdeeli:"Agli dafa kisi ke ghar jaakar cost calculate karne ke bajaye host ki mehnat appreciate kijiye." },
  { id:"muskurana-rawayya", title:"Muskurana Bhi Ek Rawayya Hai", tags:["Sadqah","Achha Lafz","Chhoti Nekiyan"], ic:"🙂", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "Smiling Is Also a Good Behaviour", "tags": ["Charity", "Kind Words", "Small Good Deeds"], "scene": "We often link charity only to giving money. But greeting a security guard, saying thank you to a waiter, speaking respectfully to a shopkeeper, smiling at an elder, giving two minutes to a troubled friend: these too are small good deeds.", "masla": "We think charity happens only when we take something out of our pocket, and we do not value these small acts because we consider them 'just normal manners'.", "islam": "A kind word, helping others, and removing something harmful from the road are also mentioned among examples of charity.", "nabi": "The Prophet ﷺ said that meeting someone with a smile is also charity.", "galti": "We keep looking for big good deeds, and overlook the small good deeds that we have every day.", "tabdeeli": "Today, greet one person with a warm smile and a salaam, even if they are a stranger."},
    scene:"Hum aksar sadqah ko sirf paisa dene se jodte hain. Lekin security guard ko salaam, waiter ko thank you, shopkeeper se izzat se baat, buzurg ko smile, pareshaan dost ko do minute dena, yeh sab bhi chhoti chhoti nekiyan hain.",
    masla:"Hum sochte hain ke sadqah sirf tab hota hai jab jeb se kuch nikale, aur in chhoti baaton ko 'bas normal manners' samajh kar inki qadr nahi karte.",
    islam:"Achha lafz, madad aur raaste se takleef-deh cheez hata dena bhi sadqah ke examples mein aaye hain.",
    nabi:"Nabi ﷺ ne farmaya ke muskura kar milna bhi sadqah hai.",
    galti:"Hum badi nekiyon ki talaash mein rehte hain, aur rozana milne wali in chhoti nekiyon ko nazar-andaz kar dete hain.",
    tabdeeli:"Aaj kisi ek shakhs ko, chahe woh ajnabi hi kyun na ho, khushdili se muskura kar salaam kijiye." },
  { id:"office-samaan-apka-nahi", title:"Office Ka Samaan Aapka Nahi", tags:["Amanat","Zimmedari","Diyanat"], ic:"🖇️", cat:"maal", color:"#b8860b",
    en:{"title": "The Office's Things Are Not Yours", "tags": ["Trust", "Responsibility", "Honesty"], "scene": "The office printer, stationery, fuel, internet, the company laptop, office supplies. We often think 'it's the company's, so it's fine'.", "masla": "A company does not belong to any one individual. Personal misuse of a resource given to you for work can become a question of trust.", "islam": "A trust includes everything entrusted to you for work, even if it belongs to a company.", "nabi": null, "galti": "We treat this as a 'small matter', when it is a form of betraying a trust.", "tabdeeli": "Before taking any office item home or using it personally, ask yourself: 'Am I allowed to do this?'"},
    scene:"Office ka printer, stationery, fuel, internet, company ka laptop, office supplies, hum aksar sochte hain 'company ka hi toh hai'.",
    masla:"Company ka matlab kisi individual ka nahi hota. Jo resource aapko kaam ke liye diya gaya hai, uska personal misuse trust ka masla ban sakta hai.",
    islam:"Amanat mein wohi cheezein bhi shamil hain jo kaam ke liye aapko saunpi gayi hain, chahe woh kisi company ki hi kyun na hon.",
    nabi:null,
    galti:"Hum isay 'chhoti si baat' samajh lete hain, jabke yeh amanat mein khayanat ka ek roop hai.",
    tabdeeli:"Office ki kisi cheez ko ghar le jaane ya personal use se pehle khud se poochiye: 'Kya mujhe iski ijazat hai?'" },
  { id:"online-zubaan-ka-adab", title:"Online Bhi Zubaan Ka Adab Rakhiye", tags:["Guftugu","Akhlaq","Zimmedari"], ic:"⌨️", cat:"digital", color:"#5c7cfa",
    en:{"title": "Keep Your Tongue's Manners Online Too", "tags": ["Speech", "Character", "Responsibility"], "scene": "Hiding behind a screen, we write things we would never say to someone's face: insults in comment sections, abuse from anonymous accounts, mocking someone in a group.", "masla": "Your tongue has not changed; only the keyboard has become your tongue. Being online does not end accountability.", "islam": "Saying something good or staying silent is a principle that applies equally online and offline.", "nabi": "The Prophet ﷺ said: whoever believes in Allah and the Last Day should say something good or remain silent (Sahih Bukhari 6475).", "galti": "We think that the 'anonymity' behind a screen frees us from responsibility, when nothing is hidden from Allah.", "tabdeeli": "Before writing any comment online, ask yourself: 'Would I say this to their face as well?'"},
    scene:"Screen ke peeche rehkar hum woh baatein likh dete hain jo saamne wale ko kabhi nahi kehte, comment section mein insult, anonymous account se abuse, group mein kisi ka mazaak.",
    masla:"Aapki zaban badli nahi hai, sirf keyboard ban gaya hai. Online hone se jawabdari khatam nahi ho jaati.",
    islam:"Achhi baat kahna ya khamosh rehna, yeh usool online aur offline dono jagah barabar lagu hota hai.",
    nabi:"Nabi ﷺ ne farmaya: jo Allah aur Qiyamat ke din par imaan rakhta hai, woh achhi baat kahe ya khamosh rahe (Sahih Bukhari 6475).",
    galti:"Hum sochte hain screen ke peeche 'anonymity' hamein zimmedari se azaad kar deti hai, jabke Allah ke nazdeek kuch bhi posheeda nahi.",
    tabdeeli:"Online koi comment likhne se pehle socha kijiye: 'Kya main yeh baat saamne mil kar bhi kehta?'" },
  { id:"paaki-sirf-ibadat-nahi", title:"Paaki Sirf Ibadat Ke Liye Nahi", tags:["Safai","Zaati Safai","Zahiri Hulia"], ic:"🧼", cat:"zaati-safai", color:"#2fb6b0",
    en:{"title": "Cleanliness Is Not Only for Worship", "tags": ["Cleanliness", "Personal Hygiene", "Outward Appearance"], "scene": "The time for prayer came, we made wudu and reached the masjid. But since morning our clothes were the ones we wore yesterday, and our hair has not been combed for two days.", "masla": "When cleanliness is limited to the wudu for prayer, a bad smell or outward neglect in daily life can cause discomfort to others: family, colleagues at work, people standing beside us in the masjid.", "islam": "The Quran instructs us to take care of our adornment, meaning good appearance and clothing, when going to the masjid. Outward cleanliness is not only for the time of worship; it should be part of daily life.", "nabi": "The Prophet ﷺ forbade coming to the masjid after eating garlic or onions, because their smell could disturb other worshippers.", "galti": "We think 'I'm only at home, who will see?', when the people at home deserve our good outward appearance just as much.", "tabdeeli": "Make daily bathing, wearing clean clothes and caring for your teeth a routine of your everyday life, not just a matter for prayer time."},
    scene:"Namaz ka waqt hua, wuzu kiya, masjid pahunche, lekin subah se poore din kapde wahi the jo kal pehne the, aur baal bhi do din se nahi sanware.",
    masla:"Jab safai sirf namaz ke wuzu tak mehdood ho jaati hai, rozmarra ki zindagi mein badbu ya zaahiri be-tawajjohi dusron ke liye, ghar walon, daftar ke saathiyon, masjid mein saath khade logon ke liye, takleef ka sabab ban sakti hai.",
    islam:"Qur'an mein masjid jaate waqt zeenat yani achhi haalat aur libas ka khayal rakhne ka hukm hai. Yani zahiri paaki sirf ibadat ke waqt ke liye khaas nahi, rozmarra ki zindagi ka hissa honi chahiye.",
    nabi:"Nabi ﷺ ne garlic ya pyaz khane ke baad masjid aane se mana farmaya, kyunke uski badbu doosre namaziyon ko takleef de sakti thi.",
    galti:"Hum sochte hain 'ghar mein hi toh hoon, kaun dekhega', jabke ghar wale bhi utne hi haqdar hain hamari achhi zahiri haalat ke.",
    tabdeeli:"Roz nahana, saaf kapde pehenna aur miswak/brush ka khayal rakhna apni rozana zindagi ka mamool banaiye, sirf namaz ke waqt ka nahi." },
  { id:"padosi-bagal-wala-nahi", title:"Padosi Sirf Bagal Wala Ghar Nahi", tags:["Padosi Ka Haq","Sukoon","Zimmedari"], ic:"🏘️", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "A Neighbour Is Not Just the House Next Door", "tags": ["Rights of Neighbours", "Peace", "Responsibility"], "scene": "Remembering the neighbour only when we need something is not the neighbour's right. Loud music, blocking their gate with your car, leaving rubbish at their door, late-night noise, unnecessary disturbance from construction.", "masla": "Is our freedom somewhere costing someone else their peace? It is necessary to ask this of ourselves.", "islam": "The Prophet ﷺ linked not harming one's neighbour with faith. Caring for the neighbour is not just a good habit; it is a requirement of faith.", "nabi": "The Prophet ﷺ repeatedly stressed the rights of the neighbour, to the extent that the Companions thought he might even make the neighbour an heir.", "galti": "We give priority to our freedom and convenience, and forget that its effects reach the house next door.", "tabdeeli": "Identify one thing you do that might inconvenience your neighbour, and reduce it."},
    scene:"Padosi ko sirf tab yaad karna jab usse koi kaam ho, yeh padosi ka haq nahi. Loud music, aapki gaadi se uska gate block hona, aapka kachra uske saamne, late-night noise, construction ki wajah se unnecessary takleef.",
    masla:"Hamari azaadi kahin na kahin kisi aur ke sukoon ki qeemat par toh nahi aa rahi? Yeh sawal khud se poochna zaroori hai.",
    islam:"Nabi ﷺ ne padosi ko takleef na dene ko Imaan ke saath joda hai, yani padosi ka khayal rakhna sirf achhi aadat nahi, Imaan ka tagaza hai.",
    nabi:"Nabi ﷺ ne baar baar padosi ke huqooq ki taakeed farmayi, is hadd tak ke Sahaba ko guman hone laga ke shayad padosi ko wirasat mein hissedaar bhi bana diya jaayega.",
    galti:"Hum apni azaadi aur convenience ko priority dete hain, aur bhool jaate hain ke iska asar bagal wale ghar tak pahunchta hai.",
    tabdeeli:"Aaj ek aisi cheez identify kijiye jo aapki wajah se padosi ko inconvenience de sakti hai, aur usay kam kijiye." },
  { id:"parking-ka-haq", title:"Parking Ka Bhi Haq Hai", tags:["Huqooq","Zimmedari","Ijtimaai Nazm"], ic:"🅿️", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "Parking Also Has Rights", "tags": ["Rights", "Responsibility", "Public Order"], "scene": "You park the car, occupy two parking spaces, park in front of someone's gate, block an emergency exit, and say 'it's only for 10 minutes'.", "masla": "For the person whose gate is blocked, those 10 minutes may be very important. Do not make your convenience someone else's inconvenience.", "islam": "Blocking the way and rights of others is a disliked act in Islam.", "nabi": null, "galti": "We think 'it's only a little while, nobody will come', when that 'little while' can be a great trouble for someone.", "tabdeeli": "When parking, ask yourself: 'Am I blocking someone else's way?'"},
    scene:"Gaadi park ki, do parking spaces occupy kar li, kisi ke gate ke saamne park kar diya, emergency exit block kar diya, 'bas 10 minute ke liye hai.'",
    masla:"Jis insaan ka gate block hua, uske liye woh 10 minute bohot important ho sakte hain. Apni convenience ko doosron ki inconvenience mat banaiye.",
    islam:"Doosron ke raaste aur haq mein rukawat daalna Islam mein na-pasandeedah amal hai.",
    nabi:null,
    galti:"Hum sochte hain 'thodi der ki baat hai, koi nahi aayega', jabke wahi 'thodi der' kisi ke liye badi museebat ban sakti hai.",
    tabdeeli:"Gaadi park karte waqt sochiye: 'Kya yahan kisi aur ka raasta toh nahi ruk raha?'" },
  { id:"pet-bharna-zindagi-bharna", title:"Pet Bharna Aur Zindagi Bharna Alag Hai", tags:["Zyada Khana","Mota-pan","Tarz-e-Zindagi"], ic:"⚖️", cat:"sehat", color:"#e0893f",
    en:{"title": "Filling the Stomach Is Not the Same as Filling a Life", "tags": ["Overeating", "Body Weight", "Lifestyle"], "scene": "Looking at someone's body, we jokingly said 'look how much he eats', without knowing the reason for it.", "masla": "A person's physical build is not a sin in itself. Medical conditions, genetics, age, medicines and pregnancy all affect the body. The problem arises when we look at someone's body and start passing judgement on their character.", "islam": "The Quran's principle is clear: eat and drink, but do not be extravagant (7:31). Islam did not forbid food, but one should not make a habit of always keeping the stomach full, and mocking someone's outward body is also against Islamic manners.", "nabi": "The Prophet ﷺ taught moderation in eating: food as needed, and if more is required, divide the stomach into three parts: one for food, one for water, and one for breath (Tirmidhi 2380, Hasan Sahih).", "galti": "Even when we do not mean to, we comment on someone's body, thinking it is 'just a joke', when it can be hurtful to them.", "tabdeeli": "Before commenting on someone's body, stop. Practise moderation in your own diet, and leave other people's bodies to them and to Allah."},
    scene:"Kisi ka jism dekh kar humne mazaak mein keh diya 'kitna khaata hai yeh', bina yeh jaane ke uski wajah kya hai.",
    masla:"Kisi shakhs ki jismani banawat apne aap mein gunah nahi. Medical conditions, genetics, umar, dawaiyan, hamal, in sab ka asar jism par parta hai. Masla tab hai jab hum kisi ke jism ko dekh kar uske kirdaar ka faisla sunane lagte hain.",
    islam:"Qur'an ka usool saaf hai: khao aur piyo, magar israf na karein (7:31). Islam ne khana mana nahi kiya, lekin har waqt pet bhar kar rakhna lifestyle nahi banana chahiye, aur kisi ke zahiri jism par taana kasna bhi Islami adab ke khilaf hai.",
    nabi:"Nabi ﷺ ne khane mein miyaanaroi ki taleem di, zarurat ke mutabiq khana, aur zyada zarurat ho to pet ko teen hisson mein taqseem karna (Tirmidhi 2380, Hasan Sahih).",
    galti:"Hum na chahte hue bhi kisi ke jism par comment kar dete hain, yeh soch kar ke yeh 'bas ek mazaak' hai, jabke woh shakhs ke liye takleef-deh ho sakta hai.",
    tabdeeli:"Kisi ke jism par comment karne se pehle ruk jaiye, khud apni khurak mein miyaanaroi apnaiye, aur doosron ke jism ko un ke aur Allah ke darmiyan rehne dijiye." },
  { id:"pet-godaam-mat-banao", title:"Pet Ko Godaam Mat Banaiye", tags:["Khana-Peena","Miqdar Ka Khayal","Aitedaal"], ic:"🍽️", cat:"khana", color:"#c0563f",
    en:{"title": "Do Not Make Your Stomach a Storehouse", "tags": ["Eating", "Awareness of Quantity", "Moderation"], "scene": "At a buffet we fill the plate: dal, rice, salad, sweets, all together, just because 'we paid, so we must taste everything'.", "masla": "We come to think of the stomach as a storehouse that must always be filled. Taking more than needed and then leaving half of it is both disrespect for food and harm to health.", "islam": "The Quran's ruling is clear: eat and drink, but do not be extravagant (7:31).", "nabi": "Instead of filling the stomach, the Prophet ﷺ taught eating as much as needed. If more is necessary, he advised dividing the stomach into three parts: one for food, one for water, and one for breath (Tirmidhi 2380, Hasan Sahih).", "galti": "Eating out of boredom, or taking more than needed in the thought of 'getting our money's worth', becomes a habit, and we do not even see it as a problem.", "tabdeeli": "Take only as much as you need on your plate. If you want more, you can always take it later."},
    scene:"Buffet mein plate bhar li, dal, chawal, salad, mithai, sab ek saath, sirf isliye kyunke 'paise diye hain toh sab taste karna hai'.",
    masla:"Pet ko hum ek aisa godaam samajhne lagte hain jise har waqt bharna zaroori hai. Zarurat se zyada lena, phir aadha chhod dena, yeh khane ki be-qadri bhi hai aur sehat ka nuqsan bhi.",
    islam:"Qur'an ka hukm wazeh hai: khao aur piyo, magar israf na karein (7:31).",
    nabi:"Nabi ﷺ ne pet bharne ke bajaye zarurat ke mutabiq khane ki taleem di, aur agar zyada khana zaroori ho jaye, to pet ko teen hisson mein taqseem kiya jaye: ek khane ke liye, ek pani ke liye, ek saans ke liye (Tirmidhi 2380, Hasan Sahih).",
    galti:"Boriyat mein khana, ya 'paisa vasool' karne ki soch mein zarurat se zyada lena, yeh aadatan ho jaata hai, hum isay masla samajhte hi nahi.",
    tabdeeli:"Plate mein utna hi lijiye jitni zarurat ho, baqi baad mein bhi liya ja sakta hai." },
  { id:"phone-samne-insaan", title:"Phone Haath Mein Hai, Lekin Saamne Insaan Hai", tags:["Tawajjo","Rishte","Waqt"], ic:"📱", cat:"digital", color:"#5c7cfa",
    en:{"title": "The Phone Is in Your Hand, but a Person Is in Front of You", "tags": ["Attention", "Relationships", "Time"], "scene": "We sit with a friend, phone in hand. Mum is talking, phone in hand. A spouse is sharing something, phone in hand. A child wants to show something, phone in hand.", "masla": "The person sitting in front of us deserves our full attention, but the screen always comes between us.", "islam": "Giving others our time and attention is also part of their rights.", "nabi": null, "galti": "We think 'I'm listening, after all', when the other person can feel incomplete attention too.", "tabdeeli": "Today, in at least one important conversation, put the phone aside and give the other person your full attention."},
    scene:"Friend ke saath baithe hain, phone haath mein. Ammi baat kar rahi hain, phone haath mein. Spouse kuch share kar raha hai, phone haath mein. Bachcha kuch dikhana chahta hai, phone haath mein.",
    masla:"Saamne baitha insaan humse hamari poori tawajjo ka haqdar hai, lekin screen hamesha beech mein aa jaati hai.",
    islam:"Doosron ko apna waqt aur tawajjo dena bhi unke huqooq mein shamil hai.",
    nabi:null,
    galti:"Hum sochte hain 'main sun toh raha hoon', jabke adhoori tawajjo bhi saamne wale ko mehsoos ho jaati hai.",
    tabdeeli:"Aaj kam se kam ek important baat-cheet mein phone side mein rakh kar poori tawajjo saamne wale ko dijiye." },
  { id:"plate-utna-hi-lijiye", title:"Plate Mein Utna Hi Lijiye Jitna Kha Sakte Hain", tags:["Israf","Khana","Aitedaal"], ic:"🍛", cat:"khana", color:"#c0563f",
    en:{"title": "Take on Your Plate Only as Much as You Can Eat", "tags": ["Extravagance", "Food", "Moderation"], "scene": "At a buffet, a wedding, a hotel or a home dinner, we fill the plate and then leave half of it.", "masla": "Every wasted amount of food is in some way extravagance, and avoiding extravagance is a teaching of Islam.", "islam": "The Quran gives clear guidance to avoid extravagance in eating and drinking (7:31). Food is permitted, and enjoying it is permitted, but wasting it is not.", "nabi": null, "galti": "We think 'we've paid, so we should take more', when taking more and leaving it is in fact a loss.", "tabdeeli": "Keep the first serving small. If you need more, go back for it."},
    scene:"Buffet ho, shaadi ho, hotel ho ya ghar ka dinner, plate bhar li, phir aadha chhod diya.",
    masla:"Khane ki har waste hui miqdar kahin na kahin israf hai, aur israf se bachna Islam ki taleem hai.",
    islam:"Qur'an mein khane-peene ke saath israf se bachne ki saaf hidayat aati hai (7:31), khana allowed hai, enjoy karna allowed hai, lekin zaya karna nahi.",
    nabi:null,
    galti:"Hum sochte hain 'paise diye hain toh zyada lena chahiye', jabke zyada lekar chhod dena asal mein nuqsan hi hai.",
    tabdeeli:"Pehli serving chhoti rakhiye. Zarurat ho toh dobara le lijiye." },
  { id:"public-jagah-property-nahi", title:"Public Jagah Aapki Private Property Nahi", tags:["Public Space","Zimmedari","Ijtimaai Haq"], ic:"🪑", cat:"maahol", color:"#4caf7d",
    en:{"title": "A Public Place Is Not Your Private Property", "tags": ["Public Space", "Responsibility", "Social Rights"], "scene": "At the park we find a bench and leave rubbish on it. At the railway station we leave a bottle. In the lift we leave a wrapper. We use a washroom and leave it dirty for the next person.", "masla": "A public place does not mean 'nobody's'. A public place means 'everyone's'. And what belongs to everyone also carries shared responsibility.", "islam": "Respecting others' rights and keeping public places clean is part of Islamic character.", "nabi": null, "galti": "We think 'there will be a cleaner here, they will clean it', and we place our responsibility on someone else.", "tabdeeli": "Wherever you go, try to leave the place no dirtier than when you arrived."},
    scene:"Park mein bench mili, us par kachra chhod diya. Railway station mein bottle rakh di. Lift mein wrapper chhod diya. Washroom use kiya aur agle insaan ke liye use ganda chhod diya.",
    masla:"Public jagah ka matlab yeh nahi ke 'kisi ka nahi'. Public jagah ka matlab hai: sab ka. Aur jo cheez sab ki ho, uske saath zimmedari bhi sab ki hoti hai.",
    islam:"Doosron ke haq ka khayal rakhna aur ijtimaai jaghon ko saaf rakhna Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'yahan koi cleaner hoga, saaf kar dega', aur apni zimmedari kisi aur par daal dete hain.",
    tabdeeli:"Jahan bhi aap ja rahe hain, koshish kijiye ke aapke jaane ke baad jagah pehle se zyada gandi na ho." },
  { id:"public-paisa-amanat", title:"Public Paisa = Amanat", tags:["Shehri Zimmedari","Amanat","Huqooq"], ic:"🏛️", cat:"maal", color:"#b8860b",
    en:{"title": "Public Money Is a Trust", "tags": ["Civic Responsibility", "Trust", "Rights"], "scene": "A government office, a public hospital, a road, a school, the railways, public electricity, public property: we often think of public things as 'free'.", "masla": "Misuse of a public resource affects the rights of others on some level, because it is a shared trust of everyone.", "islam": "Protecting a trust and the rights of others is not limited to private matters; social responsibility is also part of it.", "nabi": null, "galti": "We think 'this belongs to the government, what does it have to do with me?', when it is actually a shared right of everyone.", "tabdeeli": "Look after public property as carefully as you would look after something in your own home."},
    scene:"Government office, public hospital, road, school, railway, public electricity, public property, aksar hum public cheez ko 'free' samajhte hain.",
    masla:"Public resource ka misuse kisi na kisi level par doosron ke haq ko affect karta hai, kyunke yeh sab ki saanjhi amanat hai.",
    islam:"Amanat aur doosron ke huqooq ka khayal rakhna sirf niji maamlaat tak mehdood nahi, ijtimaai zimmedari bhi isi ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sarkar ki cheez hai, mera kya lena-dena', jabke yeh asal mein sab logon ka saanjha haq hai.",
    tabdeeli:"Public property ko apne ghar ki cheez ki tarah mehfooz rakhiye." },
  { id:"rasta-dustbin-nahi", title:"Rasta Aapka Dustbin Nahi", tags:["Safai","Wrapper","Zimmedari"], ic:"🧃", cat:"maahol", color:"#4caf7d",
    en:{"title": "The Road Is Not Your Dustbin", "tags": ["Cleanliness", "Wrappers", "Responsibility"], "scene": "You eat a packet of chips, hold the wrapper, and cannot find a bin nearby, so you just leave it at the side of the road. Sometimes you throw a tissue, a bottle or a packet out of a car.", "masla": "We often think 'it's just one small wrapper'. But the question is this: if everyone left just one wrapper, the whole road would be full of rubbish.", "islam": "In Islam, removing something harmful from the road is also mentioned as charity (Sunnah).", "nabi": null, "galti": "By saying 'it's just one wrapper', we shrink our own responsibility, when this same thinking, if everyone adopted it, would make the problem big.", "tabdeeli": "Keep your wrapper in your hand until you find a bin."},
    scene:"Chips ka packet khaya, wrapper haath mein tha aur aas-paas dustbin nahi mila, toh humne bas use road ke kinare chhod diya. Kabhi gaadi se tissue, bottle ya packet bahar phenk diya.",
    masla:"Hum aksar sochte hain 'ek chhota sa wrapper hi toh hai'. Lekin sawal yeh hai: agar har shakhs ek-ek wrapper chhod de toh pura raasta kachray se bhar jaayega.",
    islam:"Islam mein raaste se takleef-deh cheez hata dena bhi sadqah ke taur par zikr hua hai (Sunnah).",
    nabi:null,
    galti:"'Bas ek wrapper hai' keh kar hum apni responsibility ko chhota kar lete hain, jabke yahi soch sab ki ho jaaye toh masla bada ban jaata hai.",
    tabdeeli:"Apna wrapper dustbin milne tak haath mein rakhiye." },
  { id:"raste-mein-takleef-mat-banaiye", title:"Raste Mein Takleef Mat Banaiye", tags:["Safai","Sadqah","Zimmedari"], ic:"🪨", cat:"maahol", color:"#4caf7d",
    en:{"title": "Do Not Create Trouble on the Road", "tags": ["Cleanliness", "Charity", "Responsibility"], "scene": "On the road there are stones, broken glass, plastic, construction material, a bike parked in the wrong place, or a car parked in such a way that people have to walk out onto the road.", "masla": "Sometimes we create the trouble, sometimes we can remove it, but often we do neither.", "islam": "Removing something harmful from the road is among the well-known examples of charity.", "nabi": "The Prophet ﷺ also made this action a branch of faith.", "galti": "We think 'this is not my job', when a small effort can be a great comfort for someone else.", "tabdeeli": "Where possible, reduce the obstacles on the road, and do not add to them."},
    scene:"Raaste mein stone, broken glass, plastic, construction material, bike galat jagah, ya car aise park ki hui ke logon ko road par aana pade.",
    masla:"Kabhi hum takleef create karte hain, kabhi usay remove kar sakte hain, lekin aksar hum dono mein se kuch nahi karte.",
    islam:"Raaste se takleef-deh cheez hata dena sadqah ke mash'hoor examples mein shaamil hai.",
    nabi:"Nabi ﷺ ne is amal ko Imaan ki ek shaakh bhi qarar diya.",
    galti:"Hum sochte hain 'yeh mera kaam nahi', jabke chhoti si koshish kisi aur ke liye bohot bada aaram ban sakti hai.",
    tabdeeli:"Jahan mumkin ho, raaste ki takleef kam kijiye, badhaiye mat." },
  { id:"road-par-akelay-nahi", title:"Road Par Aap Akelay Nahi Hain", tags:["Traffic","Huqooq","Zimmedari"], ic:"🚗", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "You Are Not Alone on the Road", "tags": ["Traffic", "Rights", "Responsibility"], "scene": "Everyone on the road is in a hurry, but there is unnecessary honking, driving on the wrong side, aggressive overtaking, running red lights, not giving pedestrians space, blocking an ambulance.", "masla": "These are not just traffic violations; they are also matters of others' safety and rights.", "islam": "Protecting the lives and rights of others is an important part of Islamic responsibility.", "nabi": null, "galti": "We put our own hurry above everything, and forget that every person on the road is just as precious.", "tabdeeli": "Today, practise one thing consciously while driving: 'I must watch not only my destination, but also others' safety.'"},
    scene:"Road par sabko jaldi hai, lekin unnecessary horn, wrong-side driving, aggressive overtaking, red light todna, pedestrian ko space na dena, ambulance ko block karna.",
    masla:"Yeh sab sirf traffic violations nahi, doosron ki safety aur haq ka maamla bhi hai.",
    islam:"Doosron ki jaan aur haq ki hifazat karna Islami zimmedari ka ahem hissa hai.",
    nabi:null,
    galti:"Hum apni jaldi ko sabse zyada zaroori samajh lete hain, aur bhool jaate hain ke road par har insaan ki jaan utni hi qeemti hai.",
    tabdeeli:"Aaj driving mein ek cheez consciously practice kijiye: 'Mujhe sirf apni manzil nahi, doosron ki safety bhi dekhni hai.'" },
  { id:"screenshot-amanat", title:"Screenshot Bhi Amanat Hai", tags:["Amanat","Trust","Privacy"], ic:"📸", cat:"digital", color:"#5c7cfa",
    en:{"title": "A Screenshot Is Also a Trust", "tags": ["Trust", "Privacy", "Discretion"], "scene": "Someone sent you a personal message. We took a screenshot, sent it to a friend, and it went on to another group, and the original sender never even knew.", "masla": "The concept of privacy has not disappeared in the digital world; only the medium has changed. Passing on something someone shared with you privately, without permission, can break trust.", "islam": "A trust is not only money or things; someone's words and secrets are also a trust that must be protected.", "nabi": null, "galti": "We think 'I only sent it to one close friend', but if everyone thought this way, the news would gradually reach everyone.", "tabdeeli": "Ask for permission before forwarding a screenshot of any private chat."},
    scene:"Kisi ne personal message bheja. Humne screenshot liya, phir friend ko bheja, phir doosre group mein chala gaya, original bhejne wale ko pata bhi nahi.",
    masla:"Digital duniya mein privacy ka concept khatam nahi hua, bas uska medium badal gaya hai. Kisi ne jo baat aapse privately share ki, usay bina permission circulate karna trust ko tod sakta hai.",
    islam:"Amanat sirf paisa ya cheez nahi, kisi ki baat aur raaz bhi amanat hai jiski hifazat zaroori hai.",
    nabi:null,
    galti:"Hum sochte hain 'bas ek close friend ko bheja hai', lekin yahi soch sab ki ho toh baat dheere dheere sab tak pahunch jaati hai.",
    tabdeeli:"Kisi private chat ka screenshot forward karne se pehle permission lijiye." },
  { id:"udhar-yaad-rakhiye", title:"Udhar Liya Hai Toh Yaad Rakhiye", tags:["Qarz","Amanat","Haq"], ic:"📝", cat:"maal", color:"#b8860b",
    en:{"title": "If You Borrowed, Remember It", "tags": ["Debt", "Trust", "Rights"], "scene": "'Brother, I'll give you ₹500 tomorrow.' Then tomorrow. Then next week. Then: 'Yaar, I forgot.'", "masla": "A person who trusted you with money should not have to rely on your memory for their right.", "islam": "The Quran gives guidance even to writing down a debt formally, so that no one's right is lost.", "nabi": null, "galti": "We treat a debt as a small matter, when that money may be essential to the other person.", "tabdeeli": "Make a simple list of everything you owe: to whom, how much, and when it is due."},
    scene:"'Bhai, ₹500 kal de dunga.' Phir kal. Phir next week. Phir: 'Yaar yaad hi nahi raha.'",
    masla:"Jis shakhs ne aap par trust karke paisa diya, uska haq aapki memory par depend nahi karna chahiye.",
    islam:"Qur'an qarz ko formally likh kar rakhne tak ki hidayat deta hai, taake kisi ka haq zaya na ho.",
    nabi:null,
    galti:"Hum qarz ko chhoti baat samajh lete hain, jabke saamne wale ke liye woh paisa zaroori ho sakta hai.",
    tabdeeli:"Jo bhi udhar hai, ek simple list bana lijiye: kis se, kitna, kab dena hai." },
  { id:"waiter-bhi-insaan", title:"Waiter Bhi Insaan Hai", tags:["Izzat","Sabr","Service"], ic:"🧑‍🍳", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "The Waiter Is Also a Human Being", "tags": ["Respect", "Patience", "Service"], "scene": "You order food at a restaurant. Sometimes the waiter is late, sometimes the order is wrong, sometimes the service is slow, and we immediately say: 'You people don't know how to do your job!'", "masla": "Being served does not give us the right to look down on another person. If a mistake has been made, make a complaint, but with respect.", "islam": "Speaking gently and respectfully to others is Islamic manners, whatever the relationship.", "nabi": null, "galti": "In haste or in anger, we say words we would never say in a calm state, and forget that the person in front of us is also a human being.", "tabdeeli": "Next time you speak to a service worker, use their name if you know it, or say 'brother' or 'sir' respectfully."},
    scene:"Restaurant mein khana order kiya. Kabhi waiter late ho gaya, kabhi order galat aa gaya, kabhi service slow hai, aur hum foran keh dete hain: 'Tum logon ko kaam hi nahi aata!'",
    masla:"Service lene ka matlab yeh nahi ke kisi insaan ko neecha dikhane ka haq mil jaata hai. Galti hui hai toh complaint kijiye, lekin izzat ke saath.",
    islam:"Doosron se baat karte waqt narmi aur izzat ka khayal rakhna Islami adab hai, chahe rishta kaisa bhi ho.",
    nabi:null,
    galti:"Jaldi ya gusse mein hum aise alfaaz bol dete hain jo normal halat mein kabhi nahi bolte, aur bhool jaate hain ke saamne bhi ek insaan hi hai.",
    tabdeeli:"Agli baar service worker se baat karte waqt uska naam lekar ya 'bhai/bhaiya' kehkar respect se baat kijiye." },
  { id:"wuzu-paani-amanat", title:"Wuzu Ka Paani Bhi Amanat Hai", tags:["Israf","Paani","Zimmedari"], ic:"🚿", cat:"maahol", color:"#4caf7d",
    en:{"title": "The Water for Wudu Is Also a Trust", "tags": ["Wastefulness", "Water", "Responsibility"], "scene": "While making wudu we turned the tap on fully and let the water run. Perhaps we have never thought that something used for worship can also be wasted.", "masla": "Purity is important, but not wastefulness in the name of purity. Leaving the tap running, keeping the shower on longer than needed, letting water run while brushing your teeth: these are daily habits where we can show responsibility.", "islam": "Islam forbids wasting water, even when it is used for an act like worship.", "nabi": "The Prophet ﷺ forbade extravagance even in wudu. He taught that one should not waste water even when performing wudu beside a flowing river.", "galti": "We think water is 'unlimited' because it comes as soon as the tap is opened, when it too is a blessing for which we will be held accountable.", "tabdeeli": "Open the tap only as much as needed for wudu, and keep it closed in between."},
    scene:"Wuzu karte waqt nal poora khol diya aur paani behta raha, humne shayad kabhi socha hi nahi ke ibadat ke liye istemal hone wali cheez bhi zaya ki ja sakti hai.",
    masla:"Paaki zaroori hai, lekin paaki ke naam par israf nahi. Nal khula chhodna, zaroorat se zyada shower chalate rehna, brush karte waqt paani behne dena, yeh sab rozana ki aadatein hain jahan hum zimmedari dikha sakte hain.",
    islam:"Islam mein paani ke israf se mana kiya gaya hai, chahe woh ibadat jaisi amal ke liye hi kyun na istemal ho raha ho.",
    nabi:"Nabi ﷺ ne wuzu mein bhi israf se mana farmaya tha, yahan tak ke behte hue dariya ke kinare wuzu karne wale ko bhi paani zaya na karne ki hidayat di gayi hai.",
    galti:"Hum paani ko 'unlimited' samajh lete hain kyunke nal kholte hi aa jaata hai, jabke yeh bhi ek nemat hai jiska hisaab hoga.",
    tabdeeli:"Wuzu mein nal ko zarurat ke mutabiq kholiye, aur kaam ke darmiyan band rakhiye." },
  { id:"doosre-ki-screen", title:"Doosre Ki Screen, Aapka Maamla Nahi", tags:["Privacy","Public Places","Adab"], ic:"👀", cat:"zubaan", color:"#7e6fd6",
    en:{"title": "Someone Else's Screen Is Not Your Business", "tags": ["Privacy", "Public Places", "Manners"], "scene": "You are sitting in a bus, auto, metro or train. The person next to you is using their phone, WhatsApp is open, and they are chatting personally with someone. Our eyes suddenly fall on their screen, and sometimes we deliberately turn our head to look: who they are talking to, what they are writing, how much money a transaction is for.", "masla": "Whatever comes before your eyes does not become permissible or appropriate to look at. A person's screen is their private space. They are sitting in public transport, but that does not mean their private conversation has become public.", "islam": "The Quran (49:12) forbids prying: looking into other people's private matters without reason. Whatever is not yours to see, there is no need to look into.", "nabi": "The Prophet ﷺ gave a strict warning about looking into someone else's home without permission (Sahih Muslim). Today, sometimes a mobile screen is in front of us instead of a window, but the principle remains the same.", "galti": "We say 'I just happened to see it', but sometimes the first glance is accidental, while the second glance is our own choice.", "tabdeeli": "The next time you see the screen of the person beside you on public transport, look away. Look at your own phone, look outside, remember Allah, or simply travel in silence."},
    scene:"Bus, auto, metro ya train mein baithe hain. Bagal wala phone use kar raha hai, WhatsApp khula hai, kisi se personal chat ho rahi hai. Humari nazar achanak uski screen par padti hai, aur kabhi jaan-boojhkar thodi gardan ghuma kar dekhte hain: kis se baat kar raha hai, kya likh raha hai, kitne paise ka transaction hai.",
    masla:"Har woh cheez jo aapki aankhon ke saamne aa jaye, uska dekhna jaiz ya munasib nahi ho jaata. Kisi ki screen uski niji jagah hai. Woh public transport mein baitha hai, lekin iska matlab yeh nahi ke uski private guftugu public ho gayi.",
    islam:"Qur'an (49:12) mein tajassus se, yani dusron ke niji maamlaat ko be-wajah khodne se, mana kiya gaya hai. Jo cheez aapke liye nahi hai, usmein jhaankna zaroori nahi.",
    nabi:"Nabi ﷺ se doosre ke ghar mein bila ijazat jhaankne ke bare mein sakht warning milti hai (Sahih Muslim). Aaj ghar ki khidki ki jagah kabhi-kabhi mobile screen humare saamne hoti hai, lekin usool wahi rehta hai.",
    galti:"Hum kehte hain 'bas nazar pad gayi thi', lekin kabhi-kabhi pehli nazar accidental hoti hai, doosri nazar hamari apni choice hoti hai.",
    tabdeeli:"Agli baar public transport mein bagal wale ki screen nazar aaye toh nazar hata lijiye, apna phone dekhiye, bahar dekhiye, zikr kijiye ya bas khamoshi se safar kijiye." },
  { id:"aapki-awaaz-sirf-aapki-nahi", title:"Aapki Awaaz Sirf Aapki Nahi", tags:["Public Places","Noise","Consideration"], ic:"🔊", cat:"huqooq", color:"#3f8fe0",
    en:{"title": "Your Voice Is Not Only Yours", "tags": ["Public Places", "Noise", "Consideration"], "scene": "A video plays in the train, a reel at full volume on the bus, a call on speaker in the metro, a video in the waiting room, and we think 'I'm not bothered by it'.", "masla": "The choices we make in a public place affect others too. We may want to hear a video, but it is not necessary that others must hear it as well. Someone may be reading, someone sleeping, someone reciting the Quran, someone just wanting quiet.", "islam": "Not causing others discomfort and respecting people's peace is an important part of Islamic manners.", "nabi": "The Prophet ﷺ strongly stressed not harming one's neighbour. The same principle can be applied in public places.", "galti": "We take our convenience as the default: 'The sound seems fine to me', when the question should be whether it seems fine to others as well.", "tabdeeli": "On buses, trains, the metro, in waiting rooms, hospitals or any public place, use earphones for audio. If you do not have them, save the video for later."},
    scene:"Train mein video chal raha hai, bus mein reel full volume par, metro mein speaker par call, waiting room mein video chal raha hai, aur hum sochte hain 'mujhe toh problem nahi ho rahi'.",
    masla:"Public jagah mein hamari choice ka asar doosron par bhi parta hai. Hamein video sunna hai, lekin doosron ko bhi woh sunna pade, yeh zaroori nahi, shayad koi padh raha ho, koi so raha ho, koi Qur'an padh raha ho, koi sirf khamoshi chahta ho.",
    islam:"Doosron ko takleef na dena aur logon ke sukoon ka khayal rakhna Islami adab ka ahem hissa hai.",
    nabi:"Nabi ﷺ ne padosi ko takleef na dene ke bare mein sakht taakeed farmayi, isi usool ko public jaghon mein bhi laaga jaa sakta hai.",
    galti:"Hum apni convenience ko default samajh lete hain, 'mujhe toh awaaz theek lag rahi hai', jabke sawal yeh hona chahiye ke kya doosron ko bhi theek lag rahi hai.",
    tabdeeli:"Bus, train, metro, waiting room, hospital ya kisi public jagah mein audio ke liye earphones istemal kijiye, aur agar available na hon toh video baad ke liye rakh dijiye." },
  { id:"jahan-khaya-wahan-sameta", title:"Jahan Khaya, Wahan Sameta Bhi", tags:["Safai","Zimmedari","Dining"], ic:"🪣", cat:"maahol", color:"#4caf7d",
    en:{"title": "Where You Eat, Clear Up Too", "tags": ["Cleanliness", "Responsibility", "Dining"], "scene": "You ate at a restaurant. There is a cup on the table, a plate, a tissue, a bottle, and we got up and walked off, thinking 'there are staff, they'll do it'.", "masla": "Clearing the table may be the restaurant staff's job, but not every task that someone else could do means we should have them do it. If a cup and plate came into our hands, leaving our own place untidy for no reason is also a lack of consideration.", "islam": "Valuing food, avoiding wastefulness and considering others are Islamic principles. This is not a specific ruling that 'you must take the plate to the sink yourself', but these principles can be applied here.", "nabi": "There are reports in Sahih Muslim about the Prophet ﷺ and the blessing of food and cleaning dishes, pointing to the value of food.", "galti": "Sometimes we begin to see a service worker as only a 'service', thinking 'I paid, so they will do it'. Paying does not mean the other person's effort no longer deserves respect.", "tabdeeli": "In a restaurant, office pantry, canteen or any shared eating place, put away what you reasonably can yourself: tissues in the bin, bottles in the designated place, and do not leave the table needlessly messy."},
    scene:"Restaurant mein khana khaya. Table par cup hai, plate hai, tissue hai, bottle hai, aur hum uth kar seedha chale gaye, yeh soch kar 'staff hai na, woh kar lenge'.",
    masla:"Restaurant staff ka kaam table clear karna ho sakta hai, lekin har woh kaam jo koi doosra kar sakta hai, zaroori nahi ke hum usse karwayein. Agar cup aur plate humare haath se table tak gaya hai, toh apni jagah ko be-wajah messy na chhodna bhi ek consideration hai.",
    islam:"Khane ki qadr karna, israf se bachna aur doosron ka khayal rakhna Islami usool hain. Yeh koi specific hukm nahi ke 'plate khud sink tak le jao', lekin inhi usoolon ko yahan laaga ja sakta hai.",
    nabi:"Sahih Muslim mein Nabi ﷺ ke bartan saaf karne aur khane mein barkat ke hawale se riwayat milti hai, jo khane ki qadr karne ki taraf ishara karti hai.",
    galti:"Hum kabhi service worker ko insaan se zyada 'service' samajhne lagte hain, 'maine paise diye hain, woh karenge'. Paise dene ka matlab yeh nahi ke doosre insaan ki mehnat ki qadr khatam ho gayi.",
    tabdeeli:"Restaurant, office pantry, canteen ya kisi shared dining jagah mein jo cheez aap khud reasonably samet sakte hain, use wahin chhod kar mat jaiye, tissue dustbin mein, bottle designated jagah par, aur table ko be-wajah messy na chhodein." },
  { id:"apna-kaam-khud-saleeqa", title:"Apna Kaam Khud Karna Bhi Saleeqa Hai", tags:["Khud-Inhisaari","Ghar","Zimmedari"], ic:"🧦", cat:"ghar", color:"#d6708f",
    en:{"title": "Doing Your Own Work Is Also Good Manners", "tags": ["Self-Reliance", "Home", "Responsibility"], "scene": "At home, if you need something: 'Mum, bring it.' Clothes: 'Give them to someone.' Water: 'Bring one for me too.' Your own cup, your own plate: 'Someone will pick it up', 'Mum will do it.' Sometimes we behave at home as if the other people in the house exist for our personal service.", "masla": "Household tasks should not be the 'work' of just one gender. Managing your own clothes, putting away your plate and cup, keeping your room clean, making your own bed: this is self-reliance and responsibility, not a burden on someone else.", "islam": "Every person living in the home should contribute to its responsibilities. The thought that 'this is only a woman's job' or 'this is only a man's job' does not fit with the spirit of Islamic teaching.", "nabi": "In Sahih al-Bukhari, Hazrat Aisha RA reported that when the Prophet ﷺ was at home he would share in the housework, and when he heard the call to prayer he would leave for the prayer (Bukhari 5363).", "galti": "Outside, at the office, we are fully independent, do our own work and are responsible to our bosses, but as soon as we get home we say 'Mum will do it' or 'my wife will do it'. The people at home are not our servants.", "tabdeeli": "From today, set one simple principle: 'If I can do something myself, I will not automatically call someone else for it.' Pick up your plate, put away your cup, manage your own clothes, and gladly lend a hand with other household tasks."},
    scene:"Ghar mein kuch chahiye toh 'Ammi, le aaiye'. Kapde: 'kisi ko de do'. Paani: 'mere liye bhi le aao'. Apna cup, apni plate, 'koi utha dega', 'Ammi kar lengi'. Kabhi hum ghar mein aise behave karte hain jaise ghar ke doosre log hamari personal khidmat ke liye hain.",
    masla:"Ghar ke kaam sirf kisi ek jins ke 'kaam' nahi hone chahiye. Apne kapde manage karna, apni plate-cup rakhna, apna room saaf rakhna, apna bed banana, yeh khud-inhisaari aur zimmedari hai, kisi ek par bojh nahi.",
    islam:"Ghar mein rehne wala har shakhs ghar ki zimmedari mein apna hissa daale, yeh soch ke 'sirf aurat ka kaam hai' ya 'sirf mard ka kaam hai' Islami taleem ki rooh se mail nahi khaati.",
    nabi:"Hazrat Aisha RA se Sahih al-Bukhari mein riwayat hai ke Nabi ﷺ jab ghar mein hote toh apne ghar ke kaam mein hissa lete, aur jab azaan sunte toh namaz ke liye nikal jaate (Bukhari 5363).",
    galti:"Hum bahar daftar mein poori tarah independent hote hain, apna kaam khud karte hain, apne boss ke saamne zimmedar hote hain, lekin ghar aate hi 'Ammi kar dengi' ya 'Biwi kar degi' keh dete hain. Ghar wale hamare khidmatgaar nahi.",
    tabdeeli:"Aaj se ek simple usool banaiye: 'jo kaam main khud kar sakta/sakti hoon, uske liye kisi aur ko automatically mat bulaiye.' Apni plate uthaiye, apna cup rakhiye, apne kapde khud manage kijiye, aur ghar ke doosre kaamon mein bhi khushi se haath bataiye." },
  { id:"bas-10-minute-matlab-10", title:"“Bas 10 Minute” Ka Matlab 10 Minute Hi Ho", tags:["Waqt Ki Pabandi","Waada","Zimmedari"], ic:"🕰️", cat:"waqt", color:"#c79a2e",
    en:{"title": "'Just 10 Minutes' Should Mean 10 Minutes", "tags": ["Punctuality", "Promises", "Responsibility"], "scene": "We say 'I'll be there in 10 minutes'. The other person waits. Ten minutes pass, then 15, then 20, then 30, and a message arrives: 'Just 5 minutes more'. Sometimes we do not lie deliberately; we simply misjudge how long it will take.", "masla": "If getting there will realistically take 30 minutes, then saying 10 minutes disturbs the other person's time. They may be waiting for you, may have stopped another task, or may be planning an appointment around your timing. For you it is a 20-minute difference; for them those 20 minutes are part of their life.", "islam": "Islam takes seriously the value of time, keeping promises and commitments, and the rights of people. When you tell someone when you will arrive, do not treat it as a casual estimate; try to give the realistic time it will take.", "nabi": null, "galti": "We think 'I'll say 10 minutes, I'll see on the way', then traffic comes, parking is not available, another task comes up, and we do not notice how 10 minutes became 30. The problem is not just being late; the problem is making an unrealistic promise.", "tabdeeli": "From now on, when someone asks 'how long will you be?', give your realistic time, not your best-case time: for example, 'about 30 minutes, depending on traffic'. It is better to say a little more than to keep someone waiting with repeated 'just 5 minutes'."},
    scene:"Hum kehte hain 'bas 10 minute mein aa raha hoon'. Saamne wala wait karta hai. 10 minute guzarte hain, phir 15, phir 20, phir 30, aur message aata hai 'bas 5 minute aur'. Kabhi hum jaan-boojhkar jhoot nahi bolte, bas apne waqt ka andaza galat laga lete hain.",
    masla:"Agar pahunchne mein realistically 30 minute lagenge, toh 10 minute kehna saamne wale ke waqt ko disturb karta hai. Woh shayad aapka intezar kar raha hai, apna koi kaam rok kar baitha hai, ya kisi appointment ko aapke hisaab se plan kar raha hai. Aapke liye sirf 20 minute ka farq hai, uske liye woh 20 minute bhi uski zindagi ka waqt hai.",
    islam:"Islam waqt ki qadr, ahd aur waade ki pabandi, aur logon ke huqooq ko sanjeedgi se leta hai. Jab kisi ko apne pahunchne ka waqt batayein, toh usay sirf casual andaza na samjhiye, jitna realistically waqt lagega, utna hi batane ki koshish kijiye.",
    nabi:null,
    galti:"Hum sochte hain '10 minute bol deta hoon, raste mein dekh lenge', phir traffic aa jaata hai, parking nahi milti, koi kaam aur aa jaata hai, aur 10 minute kab 30 ban jaate hain pata hi nahi chalta. Masla sirf late hona nahi, masla unrealistic waada karna hai.",
    tabdeeli:"Aaj se jab koi pooche 'kitni der mein aaoge', toh apni best-case timing nahi, realistic timing bataiye, jaise 'takriban 30 minute, traffic par depend karega'. Thoda zyada waqt batana behtar hai, baar baar 'bas 5 minute' kehkar kisi ko wait karwana nahi." },

  { id:"khane-ke-aadaab", title:"Khane Ke Aadaab", tags:["Khane Ka Saleeqa","Sunnah","Shukr"], ic:"🍽️", cat:"khana", color:"#c0563f", guide:true,
    en:{"title": "Etiquette of Eating", "tags": ["Manners of Eating", "Sunnah", "Gratitude"], "intro": "Food is not only a way to satisfy hunger; it is a blessing from Allah. So eating too has its own manners: remembering Allah before eating, keeping clean, eating with the right hand, eating from what is in front of you, avoiding extravagance, caring for others, and giving thanks to Allah.", "closing": "Food is not only for satisfying hunger. For a Muslim there is Bismillah in food too, there is gratitude, cleanliness, Sunnah, moderation, consideration for others, and appreciation of Allah's blessing. Eat, value the blessing, avoid extravagance, and eat with good manners.", "sections": [{"heading": "Before Eating", "items": ["Wash both hands well before eating and take care to keep them clean.", "Take care of cleaning your mouth and rinsing it, especially if your mouth has an odour.", "Say Bismillah before you begin eating.", "If you remember the recommended dua for eating, you may recite it.", "Eat with your right hand. The Prophet ﷺ taught mentioning Allah's name and eating with the right hand.", "Sit down to eat with composure, calm and modesty.", "Be mindful of your posture and clothing while eating.", "Begin eating with the feeling of gratitude, understanding the food as a blessing of Allah."]}, {"heading": "How to Eat", "items": ["Eat with your right hand.", "If it is a shared dish, eat from the part in front of you. Do not reach across in front of others.", "When it is suitable to eat with the hand, the Sunnah is to use three fingers: the thumb, the index finger and the middle finger.", "Eat neither too quickly nor needlessly slowly. Eat with calm and good manners.", "Keep each morsel small and manageable.", "If there is food in your mouth, avoid speaking.", "Do not speak with your mouth full.", "Do not eat in a way that disgusts or inconveniences the person opposite you.", "Keep your fingers and hands as clean as possible while eating.", "Do not move the shared food around, and do not turn over the whole dish to find the thing you like.", "Leave something for others too; do not collect only the things you like.", "Keep in mind the people who are eating with you.", "Do not look at someone else's portion or morsel, and do not touch their plate without need."]}, {"heading": "The Heart's Attitude Towards Food", "items": ["Eat your food understanding it as a blessing of Allah.", "Remember Allah's gratitude while you eat.", "As you look at the food, remember those who are facing hunger or hardship at this time.", "Ask Allah to make things easy for those in need.", "When you receive food, keep an attitude of gratitude instead of ingratitude and complaint.", "If you do not like a food, do not criticise it. The Prophet ﷺ, if he did not like a food, would leave it, but he never criticised it.", "If you like the food, praise and thank the one who cooked it.", "Do not think lightly of the effort of the one who cooked."]}, {"heading": "Moderation in Eating", "items": ["Do not eat too much.", "It is not necessary to keep the stomach full at all times.", "The Prophet ﷺ taught moderation in eating, and mentioned keeping one part for food, one part for drink and one part for breath.", "Do not eat beyond what you need in order to get your money's worth.", "At a buffet, take only as much as you can eat, instead of filling your plate with everything.", "Take less at first; if you need more, you can go back for it.", "Do not waste food by leaving it on your plate.", "Eat and drink as the Quran teaches, but do not be extravagant."]}, {"heading": "Manners of Eating Together", "items": ["Eating together increases love and a sense of belonging.", "In a shared dish, eat from the part in front of you.", "Keep the person opposite you in mind as well.", "Do not take only the best thing for yourself.", "Do not reduce someone else's portion.", "Do not touch someone's morsel, plate or food without their permission.", "Keep the children and the elders in mind too.", "Do not embarrass others while eating.", "Do not make fun of someone's amount of food, manner of eating or speed.", "Do not turn the dastarkhwan into a place for needless gossip, backbiting or arguments."]}, {"heading": "If a Morsel Falls", "items": ["If a morsel of food falls and the dirt on it can be cleaned, it may be cleaned and eaten.", "The Prophet ﷺ taught picking up a fallen morsel, removing the dirt from it and eating it.", "A morsel that has fallen on the dastarkhwan should not be thought useless if it can be made clean.", "If the morsel has fallen somewhere it cannot be cleaned hygienically, keep health and cleanliness in mind.", "Picking up every fallen morsel without thinking is not the aim; keep cleanliness and health in mind alongside the Sunnah."]}, {"heading": "Hands and Plate After Eating", "items": ["Do not leave the clean remaining food on your plate needlessly after eating.", "Eat in a way that cleans your utensils as much as possible, and do not waste food.", "There is a mention of the Prophet ﷺ cleaning the fingers and the dish, because the blessing may lie in any part of the food, and we do not know which part.", "If you ate with your hand, licking the fingers is mentioned in the Sunnah.", "After that, wash your hands well.", "If a spoon or cutlery was used, place it neatly as well.", "After eating, clean your mouth and rinse it.", "If needed, clean your teeth as well."]}, {"heading": "If You Are a Guest", "items": ["Value the food the host has offered.", "Do not make unnecessary comments about the amount, quantity, taste or arrangements of the food.", "Take only as much food as there is.", "Do not take more than your share of your favourite item.", "Do not insist after refusing food several times.", "Look upon the host's hospitality with appreciation.", "After eating, pray to Allah for the host.", "Before getting up, ask permission appropriately."]}, {"heading": "If You Are the Host", "items": ["Serve food to the guest sincerely.", "Offer food, but do not make the guest uncomfortable by insisting repeatedly.", "Keep the guest's needs and comfort in mind.", "Do not serve extra food only because 'refusing would be rude'.", "Give the guest honour and peace.", "Do not turn a meal into a competition of show and formality beyond your means."]}, {"heading": "After Eating", "items": ["Thank Allah.", "Recite the recommended dua after eating.", "If you ate at a meal given by someone, pray for the host.", "Wash your hands again.", "Rinse your mouth and take care of its cleanliness.", "Do not leave your plate or cup needlessly where it is.", "If you are in a restaurant, office or shared dining place, do not leave behind things that you can safely and easily put away yourself.", "If you are a guest, thank the host and leave with permission."]}]},
    intro:"Khana sirf bhook mitane ka zariya nahi, Allah ki ek nemat hai. Isliye khane ka bhi apna saleeqa hai: khane se pehle Allah ko yaad karna, saaf-suthra rehna, dahine haath se khana, apne saamne se khana, israf se bachna, doosron ka khayal rakhna aur Allah ka shukr ada karna.",
    sections:[
      { heading:"Khane Se Pehle", ic:"🌿", items:[
        "Khana khane se pehle dono haath achhi tarah dhoyein aur safai ka khayal rakhein.",
        "Munh ki safai aur kulla ka bhi khayal rakhein, khaas taur par jab munh mein badbu ho.",
        "Khana shuru karne se pehle Bismillah padhein.",
        "Khane ke liye masnoon dua yaad ho toh padh sakte hain.",
        "Dahine haath se khayein. Nabi ﷺ ne khane ke waqt Allah ka naam lene aur dahine haath se khane ki hidayat di.",
        "Saleeqe, sukoon aur haya ke saath baith kar khayein.",
        "Khana khate waqt apni posture aur libaas ka bhi khayal rakhein.",
        "Khana Allah ki nemat samajh kar shukr ke ehsaas ke saath shuru karein."
      ] },
      { heading:"Khana Kaise Khayein", ic:"🍛", items:[
        "Dahine haath se khayein.",
        "Shared dish ho toh apne saamne se khayein. Doosron ke saamne haath na le jayein.",
        "Jab khana haath se khana munasib ho, toh teen ungliyon se khana Sunnah mein milta hai: angutha, shahadat ki ungli aur beech wali ungli.",
        "Khane ko na bahut jaldi aur na be-wajah bahut dheere khayein. Sukoon aur saleeqe se khayein.",
        "Luqma chhota aur manageable rakhein.",
        "Munh mein luqma ho toh baat karne se bachein.",
        "Munh bhar kar baat na karein.",
        "Khate waqt aise na khayein ke saamne wale ko ghin ya takleef ho.",
        "Ungliyon aur haath ko khane ke darmiyan jitna mumkin ho saaf rakhein.",
        "Shared food ko idhar-udhar na karein aur apni pasand ki cheez dhoondhne ke liye poora bartan na ulat-pulat karein.",
        "Doosron ke liye bhi khana chhodein; sirf apni pasand ki cheezein jama na karein.",
        "Saath baith kar khane walon ka khayal rakhein.",
        "Kisi ke portion ya luqme par nazar na rakhein aur na hi uski plate ko bina zarurat touch karein."
      ] },
      { heading:"Khane Ke Saath Dil Ka Rawayya", ic:"🤲", items:[
        "Khana Allah ki nemat samajh kar khayein.",
        "Khate waqt Allah ka shukr yaad rakhein.",
        "Khane ko dekh kar un logon ko bhi yaad karein jo is waqt bhook ya tangdasti ka saamna kar rahe hain.",
        "Allah se dua karein ke woh zaruratmandon ke liye aasani paida farmaye.",
        "Khana milne par na-shukri aur shikayat ke bajaye shukr ka rawayya rakhein.",
        "Kisi khane ko pasand na aaye toh uski burai na karein. Nabi ﷺ kisi khane ko pasand na karte toh use chhod dete, lekin uski burai nahi karte the.",
        "Khana pasand aaye toh khana banane wale ki tareef aur shukriya karein.",
        "Khana banane wale ki mehnat ko halka na samjhein."
      ] },
      { heading:"Khane Mein Aitidaal", ic:"🍽️", items:[
        "Zyada na khayein.",
        "Pet ko har waqt bhar kar rakhna zaroori nahi.",
        "Nabi ﷺ ne khane mein aitidaal ki taleem di aur ek hissa khane, ek hissa peene aur ek hissa saans ke liye rakhne ka zikr farmaya.",
        "Khane ko 'paisa vasool' karne ke liye zarurat se zyada na khayein.",
        "Buffet mein har cheez plate mein bhar lene ke bajaye jitna kha sakte hain utna hi lein.",
        "Pehle kam lein; zarurat ho toh dobara le sakte hain.",
        "Plate mein khana chhod kar waste na karein.",
        "Qur'an ke mutabiq khaaiye aur peejiye, lekin israf na kijiye."
      ] },
      { heading:"Saath Khane Ke Aadaab", ic:"🤝", items:[
        "Mil baith kar khana mohabbat aur apnapan badhata hai.",
        "Shared dish mein apne saamne se khayein.",
        "Saamne wale ka bhi khayal rakhein.",
        "Achhi cheez sirf apne liye na kheench lein.",
        "Doosre ke portion ko kam na karein.",
        "Kisi ke luqme, plate ya khane ko bina ijazat na chhuyein.",
        "Bachchon aur buzurgon ka bhi khayal rakhein.",
        "Khate waqt doosron ko embarrass na karein.",
        "Kisi ke khane ki quantity, tareeqa ya speed ka mazaak na banayein.",
        "Dastarkhwan ko be-wajah gossip, gheebat aur behas ki jagah na banayein."
      ] },
      { heading:"Luqma Gir Jaaye Toh", ic:"🫓", items:[
        "Agar khane ka luqma gir jaaye aur us par lagi gandagi ko saaf karna mumkin ho, toh use saaf karke khaya ja sakta hai.",
        "Nabi ﷺ ne giray hue luqme ko uthakar uski gandagi door karne aur khane ki taleem di.",
        "Dastarkhwan par gira hua luqma agar saaf ho sakta hai toh use bekaar na samjhein.",
        "Agar luqma aisi jagah gira ho jahan use hygienically saaf karna mumkin na ho, toh sehat aur safai ka khayal rakhein.",
        "Har giray hue luqme ko bina soche uthana maqsad nahi; Sunnah ke saath safai aur sehat ka bhi khayal rakhein."
      ] },
      { heading:"Khane Ke Baad Haath Aur Plate", ic:"👅", items:[
        "Khana khane ke baad plate mein bache hue saaf khane ko be-wajah na chhodein.",
        "Apne bartan ko jitna mumkin ho saaf karke khayein, khane ko waste na karein.",
        "Nabi ﷺ se ungliyon aur bartan ko saaf karne ka zikr milta hai, kyunke barkat khane ke kis hisse mein ho, yeh maloom nahi.",
        "Haath se khaya ho toh ungliyon ko chaatna Sunnah mein milta hai.",
        "Iske baad haath achhi tarah saaf kar lein.",
        "Agar spoon ya cutlery use ki ho toh use bhi saleeqe se rakhein.",
        "Khane ke baad munh ki safai aur kulla karein.",
        "Zarurat ho toh daanton ki safai bhi karein."
      ] },
      { heading:"Agar Aap Mehmaan Hain", ic:"🧑‍🍳", items:[
        "Mezban ne jo khana pesh kiya hai, uski qadr karein.",
        "Khane ki kami, miqdar, zaiqa ya intezam par be-wajah tabsira na karein.",
        "Jitna khana hai utna hi lein.",
        "Sirf apni pasand ki cheez zyada na lein.",
        "Khane ke liye baar baar mana karne ke baad bhi zid na karein.",
        "Mezban ki mehmaan-nawazi ko qadr ki nazar se dekhein.",
        "Khane ke baad Allah se mezban ke liye dua karein.",
        "Uthne se pehle munasib taur par ijazat lein."
      ] },
      { heading:"Agar Aap Mezban Hain", ic:"🏡", items:[
        "Mehmaan ko ikhlas ke saath khana pesh karein.",
        "Khane ke liye peshkash karein, lekin baar baar zid karke mehmaan ko asahaj na karein.",
        "Mehmaan ki zarurat aur aaram ka khayal rakhein.",
        "Sirf isliye zyada khana na khilayein ke 'mana karna badtameezi hai'.",
        "Mehmaan ko izzat aur sukoon dein.",
        "Dawat ko apni haisiyat se bahar jaakar takalluf ka muqabala na banayein."
      ] },
      { heading:"Khane Ke Baad", ic:"🙏", items:[
        "Allah ka shukr ada karein.",
        "Khane ke baad ki masnoon dua padhein.",
        "Dawat mein khaya ho toh mezban ke liye masnoon dua karein.",
        "Haath dobara dhoyein.",
        "Kulla karein aur munh ki safai ka khayal rakhein.",
        "Apni plate/cup ko be-wajah wahin na chhodein.",
        "Agar aap kisi restaurant, office ya shared dining jagah mein hain, toh jo cheez aap khud safely aur aasani se samet sakte hain, use wahin chhod kar na jayein.",
        "Mehmaan hon toh shukriya ada karein aur ijazat lekar uthein."
      ] },
    ],
    closing:"Khana sirf bhook mitana nahi hai. Ek Muslim ke liye khane mein bhi Bismillah hai, shukr hai, safai hai, Sunnah hai, aitidaal hai, doosron ka khayal hai, aur Allah ki nemat ki qadr hai. Khana khaiye, nemat ki qadr kijiye, israf se bachiye aur saleeqe ke saath khaiye." },

  { id:"sone-ke-aadaab", title:"Sone Ke Aadaab", tags:["Neend Ka Saleeqa","Sunnah","Zikr-o-Dua"], ic:"🌙", cat:"neend", color:"#3a4d8f", guide:true,
    en:{"title": "Etiquette of Sleep", "tags": ["Manners of Sleep", "Sunnah", "Remembrance and Dua"], "intro": "Sleep is not merely a way to remove tiredness; it is a great blessing from Allah. Every night we close our day and then sleep, entrusting ourselves to Allah. The Prophet ﷺ taught us a beautiful way even for the time of sleep: cleanliness, wudu, remembrance of Allah, recitation of the Quran, dua, taking care of our own safety, and trust in Allah.", "closing": "Sleep too is a blessing of Allah. Instead of handing the night over to the phone, tension and endless scrolling, close your night with calm, remembrance, dua and trust. If the day was spent on worldly tasks, close the night with the remembrance of Allah. Tomorrow morning may turn out to be a better day of your life.", "sections": [{"heading": "Before Sleeping", "items": ["Take care to keep your body and clothes clean before sleeping.", "Sleep after making wudu. The Prophet ﷺ taught making wudu for sleep and then lying down on the right side.", "Check and clean your bed.", "Before getting into bed, it is Sunnah to shake it out with the hand or the edge of a cloth, because we do not know what may have fallen on it while we were away.", "Keep the room as clean, comfortable and peaceful as possible.", "Place the things you need in their place before sleeping, so that there is no needless disturbance during the night.", "Closing the doors of the house and saying Allah's name is in the Sunnah.", "Covering water vessels and other open containers is also in the Sunnah.", "If there is fire, a lamp or any unsafe flame, put it out before sleeping. The Prophet ﷺ taught extinguishing fire before sleep."]}, {"heading": "Ask Your Phone's Permission Before Sleeping", "items": ["Stop aimless scrolling before sleeping.", "Make it a habit to use the bed only for calm and rest, instead of endless social media browsing.", "Avoid arguments, heated chats and unnecessary online discussion before sleeping.", "An urgent message can be answered in the morning.", "It can be helpful to keep the phone a little away from the bed.", "You can keep notifications on silent or sleep mode.", "Instead of looking at a screen right up to the moment of sleep, give your mind time to rest. (These are points of modern sleep hygiene; do not take them as a direct Sunnah ruling. The aim is only that technology should not dominate our sleep and worship.)"]}, {"heading": "Do Not Stretch the Night Without Need After Isha", "items": ["The Prophet ﷺ did not like sleeping before Isha or unnecessary talk after Isha. This does not mean every conversation after Isha is forbidden; necessary work, knowledge, household matters and beneficial talk are separate from this.", "Unnecessary night gossip, endless scrolling, aimless arguments and staying awake for no reason can affect your sleep, Fajr and your ability for the next day. Ending the night well is also a good manner."]}, {"heading": "Ayat al-Kursi", "items": ["Reciting Ayat al-Kursi before sleep is recommended. In a report in Sahih al-Bukhari from Abu Hurairah RA, its protection is mentioned."]}, {"heading": "Surah Al-Mulk", "items": ["Reciting Surah Al-Mulk before sleep can also be made a beautiful practice of the night.", "It is reported in the virtues of Surah Al-Mulk that a Surah of 30 verses kept interceding for its reader until he was forgiven, and that Surah is Al-Mulk (Jami' at-Tirmidhi).", "So instead of treating it only as a 'sleep Surah', recite it with recitation of the Quran and the hope of Allah's forgiveness. The night may be short, but time spent with the Quran is precious."]}, {"heading": "Surah Al-Ikhlas, Al-Falaq and An-Nas", "items": ["Before sleeping, recite Surah Al-Ikhlas, Surah Al-Falaq and Surah An-Nas.", "The Prophet ﷺ would recite these three Surahs, blow lightly on his hands, and pass them over his body, doing this three times. It is a beautiful practice of protection for the night and of trust in Allah."]}, {"heading": "The Last Two Verses of Surah Al-Baqarah", "items": ["Reciting the last two verses of Surah Al-Baqarah at night is also a practice of virtue.", "The Prophet ﷺ said that whoever recites the last two verses of Surah Al-Baqarah at night, they will be sufficient for him."]}, {"heading": "Tasbih of Fatimah RA", "items": ["Before sleeping, also recite the Tasbih of Fatimah RA: SubhanAllah 33 times, Alhamdulillah 33 times, Allahu Akbar 34 times, a total of 100.", "It is reported from Ali RA that Fatimah RA asked for a servant because of the hardship of household work, and the Prophet ﷺ taught her this remembrance at sleep, saying that it is better for her than a servant.", "Reflect: the Prophet ﷺ showed his daughter not only worldly ease, but the spiritual strength that comes from the remembrance of Allah. We can make this remembrance part of our night routine."]}, {"heading": "The Dua for Sleep", "items": ["At bedtime the Prophet ﷺ would recite: 'Bismika Allahumma amutu wa ahya.' Meaning: 'O Allah! In Your name I die and I live.' This dua is reported in Sahih al-Bukhari.", "The Prophet ﷺ also taught another long recommended dua to recite before sleep, which includes surrendering oneself to Allah and entrusting all one's affairs to Him."]}, {"heading": "Sleeping on the Right Side", "items": ["Lying down on the right side while sleeping is Sunnah.", "The Prophet ﷺ instructed Al-Bara bin Azib RA to make wudu before sleeping, then lie on the right side, and recite the recommended dua.", "It is also reported from the Prophet ﷺ that he would place the right hand under the cheek, and lightly bend the legs.", "So a beautiful Sunnah way of sleeping can be: wudu, remembrance, dua, lying on the right side, and sleeping in trust in Allah."]}, {"heading": "Sleep With the Intention of Tahajjud", "items": ["While going to sleep, hold in your heart the intention to get up for Tahajjud. Set an alarm, try to sleep early, and pray to Allah: 'O Allah, wake me at night for Your worship.'", "Sleeping with the intention of Tahajjud is a beautiful intention, but do not stop at intention alone. Also adopt practical means to wake up: set an alarm, keep the phone a little away from the bed, do not delay going to sleep without reason, and if possible ask someone at home to wake you.", "On waking, make wudu and pray Tahajjud. If one night you do not wake up, do not despair of yourself; set the intention again the next night."]}, {"heading": "The Resolve to Rise for Fajr", "items": ["When going to sleep, also make this intention: 'I have to get up for Fajr.' The aim is not to make a routine of the morning after missing Fajr; preparation for Fajr begins from the night before.", "An order could be: the intention for Tahajjud, an alarm for Fajr, wudu, Tahajjud if possible, then the Fajr prayer. And if you cannot get up for Tahajjud, you must certainly get up for Fajr.", "Fajr is obligatory, while Tahajjud is a voluntary act of worship, so it is necessary to understand the different ranks of the two in your night planning."]}, {"heading": "Settle the Heart Too Before Sleeping", "items": ["Sometimes the body is in bed, but the mind is still busy with thoughts such as 'why did they say that to me', 'what will happen tomorrow', 'my work is not finished'. Learn to release your heart before sleeping too.", "What has happened, leave with Allah. What must be done tomorrow, plan it. What is not in your control, put your trust in Allah.", "Avoid the habit of sleeping while holding a curse or anger towards someone, and remind yourself: 'I tried what was in my power; now it is left to Allah.'"]}, {"heading": "Are You Upset With Someone?", "items": ["It is not necessary to carry every disagreement in your heart all night. If there has been a misunderstanding with someone and it can be resolved, talk to them at a suitable time.", "But going to sleep with thoughts such as 'I will never forgive him' or 'tomorrow I will teach him a lesson' can destroy your own peace as well.", "Forgiving is not always ignoring the matter; sometimes it means you are freeing your heart from an unnecessary burden."]}, {"heading": "Avoid Sleeping on a Full Stomach", "items": ["Eating a very heavy meal just before sleep can disturb sleep and digestion.", "Do not eat unnecessarily at night, and avoid late-night snacking that is only out of boredom.", "If you are hungry, eat as needed, and after eating give your body time to settle, rather than lying straight down on the bed. (This is advice related to health and sleep, not a specific Sunnah ruling.)"]}, {"heading": "Cleanliness and Personal Protection", "items": ["Keep your body clean before sleeping, and wash if needed.", "Take care of cleaning your mouth and teeth, and keep your clothes comfortable and clean.", "Do not sleep in a shared sleeping place with sweat or body odour, and if you share a bed with someone, also consider their comfort. Cleanliness is a manner of the night as well as of the day."]}, {"heading": "Take Care of the Safety of the Home", "items": ["Before sleeping, quickly check: the gas stove is off, the lamp or candle is out, any unsafe electrical item is switched off, the door is secure, charging wires are safe, children are in a safe place, and water vessels are covered.", "The Prophet ﷺ taught closing doors at night, covering vessels, and putting out lamps and fire. In other words, practical safety can also become part of the manners of the Deen alongside worship."]}, {"heading": "Take Sleep Seriously", "items": ["It is also not right to think of sleep as 'a waste of time'; the body needs rest. If you stay awake until late every night and Fajr, work, study, exercise and household responsibilities all begin to suffer, reconsider your routine.", "Keep your sleep time consistent within reason, reduce the habit of needless night-time waking, and plan your night with the morning's essential tasks in view. Getting enough sleep is also a responsibility for your physical health."]}, {"heading": "Qailullah, the Short Afternoon Nap", "items": ["Qailullah is the name for the rest taken during the afternoon. Islamic reports mention rest in the afternoon, and it can be a good way to refresh the body and mind again.", "A little rest in the afternoon can reduce tiredness, improve mental focus, and give energy for the rest of the day.", "Science has also reported good links between a short afternoon nap and mental health. In a five-year gradual study, daytime sleep of 1 to 29 minutes among people over 65 was associated with a lower risk of mental decline (PubMed study).", "So it is more accurate to say that a short afternoon nap of about 30 minutes may be beneficial for mental health, but research does not yet prove that 'a 30-minute nap cures dementia'. Research has found various links between long or excessive sleep and dementia or mental decline (PubMed study).", "No fixed duration for Qailullah is set in the Quran or in authentic Hadith. In practice, 30 to 60 minutes of rest may be suitable, but if a long nap affects your night sleep or your daily routine, you should reduce its length.", "The purpose of Qailullah is not to sleep the whole day, but to rest for a while so that you can spend the rest of the day better."]}, {"heading": "Sleep Is Not an Escape From Tomorrow", "items": ["Before sleeping, you can ask yourself three questions: How much did I remember Allah today? Did I cause anyone hardship today? What should I do better tomorrow?", "Then hand your day over to Allah and go to sleep."]}, {"heading": "On Waking", "items": ["When the Prophet ﷺ woke up, he would recite a dua of thanks to Allah: 'Alhamdu lillahil-lazi ahyana ba'da ma amatana wa ilaihin-nushur.' Meaning: 'All praise is for Allah, who gave us life after causing us to die, and to Him is the resurrection.' (Sahih al-Bukhari)", "In other words, the night ends with the remembrance of Allah, and the morning begins with the remembrance of Allah too."]}, {"heading": "A Beautiful Night Routine", "items": ["If we gather all of this into one simple routine, the night might pass like this: finish your work, put the phone aside, take care of your cleanliness and personal protection, make wudu, check and shake out the bed, recite Ayat al-Kursi, then Al-Ikhlas, Al-Falaq and An-Nas three times each, the last two verses of Surah Al-Baqarah and Surah Al-Mulk, the Tasbih of Fatimah RA, the recommended dua for sleep, the intention for Tahajjud, an alarm for Fajr, and then lie on your right side and sleep in trust in Allah."]}]},
    intro:"Neend sirf thakawat door karne ka naam nahi, yeh Allah ki ek badi nemat hai. Hum har raat apne din ko khatam karte hain aur phir Allah ke hawale hokar sote hain. Nabi ﷺ ne sone ke waqt bhi humein ek khoobsurat saleeqa sikhaya: safai, wuzu, Allah ka zikr, Qur'an ki tilawat, dua, apni hifazat ka intezam aur Allah par bharosa.",
    sections:[
      { heading:"Sone Se Pehle", ic:"🛏️", items:[
        "Sone se pehle apne badan aur kapdon ki safai ka khayal rakhein.",
        "Wuzu karke soyein. Nabi ﷺ ne sone ke liye wuzu karne aur phir dahini taraf letne ki hidayat di.",
        "Apna bistar check aur saaf kar lein.",
        "Bistar par jaane se pehle use haath ya kapde ke kinare se jhaad lena Sunnah hai, kyunke humein nahi maloom ke hamari ghair-maujoodgi mein us par kya aa gaya ho.",
        "Kamre ko jitna mumkin ho saaf, comfortable aur sukoon wala rakhein.",
        "Sone se pehle zaroori cheezein apni jagah rakh dein, taaki raat ko be-wajah disturbance na ho.",
        "Ghar ke darwaze band karna aur Allah ka naam lena Sunnah mein aata hai.",
        "Paani ke bartan aur doosre khule containers ko dhak dena bhi Sunnah mein aata hai.",
        "Agar aag, diya ya koi unsafe flame ho toh use bujha kar soyein. Nabi ﷺ ne sone se pehle fire ko bujhane ki hidayat di."
      ] },
      { heading:"Sone Se Pehle Phone Se Bhi Ijazat Lijiye", ic:"📱", items:[
        "Sone se pehle be-wajah scrolling band karein.",
        "Bed ko endless social media browsing ki jagah sirf sukoon aur aaram ke liye istemal karne ki aadat banayein.",
        "Sone se pehle bahas, tez-mizaj chats aur be-zaroorat online guftugu se bachein.",
        "Kisi zaroori message ka jawab subah bhi diya ja sakta hai.",
        "Phone ko bistar se thoda door rakhna faida-mand ho sakta hai.",
        "Notifications ko silent ya sleep mode par rakh sakte hain.",
        "Sone ke bilkul waqt tak screen dekhte rehne ke bajaye apne zehan ko aaram dene ka waqt dein. (Yeh modern sleep hygiene ki baatein hain, inhe Sunnah ka seedha hukm na samjhein, maqsad sirf yeh hai ke technology hamari neend aur ibadat dono par ghalib na ho.)"
      ] },
      { heading:"Isha Ke Baad Raat Ko Be-Wajah Lamba Na Kheenchein", ic:"🕋", items:[
        "Nabi ﷺ Isha se pehle sone aur Isha ke baad be-zaroorat baat-cheet ko pasand nahi farmate the. Iska matlab yeh nahi ke Isha ke baad har guftugu mana hai, zaroori kaam, ilm, ghar ke maamlaat aur faida-mand baatein is se alag hain.",
        "Be-zaroorat raat ki gossip, endless scrolling, be-maqsad bahas aur bila wajah der tak jagna hamari neend, Fajr aur agle din ki salahiyat ko mutasir kar sakta hai. Raat ko khatam karna bhi ek saleeqa hai."
      ] },
      { heading:"Ayat-ul-Kursi", ic:"📖", items:[
        "Sone se pehle Ayat-ul-Kursi padhna masnoon hai. Sahih al-Bukhari mein Abu Hurairah RA ki riwayat mein iski hifazat ka zikr aata hai."
      ] },
      { heading:"Surah Al-Mulk", ic:"🌙", items:[
        "Sone se pehle Surah Al-Mulk padhna bhi ek khoobsurat raat ka amal banaya ja sakta hai.",
        "Surah Al-Mulk ke fazail ke hawale se riwayat milti hai ke 30 ayaat wali ek Surah apne padhne wale ke liye shafa'at karti rahi, yahan tak ke uski maghfirat kar di gayi, aur woh Surah Al-Mulk hai (Jami' at-Tirmidhi).",
        "Isliye ise sirf 'sone ki Surah' samajhne ke bajaye Qur'an ki tilawat aur Allah ki maghfirat ki umeed ke saath padhein. Raat ka waqt chhota ho sakta hai, lekin Qur'an ke saath guzara hua waqt qeemti hai."
      ] },
      { heading:"Surah Ikhlas, Falaq Aur Naas", ic:"🤍", items:[
        "Sone se pehle Surah Ikhlas, Surah Falaq aur Surah Naas padhein.",
        "Nabi ﷺ in teenon Surahon ko padhkar apne haathon par halki phoonk karte aur apne jism par pherte, aur teen martaba aisa karte the. Yeh raat ki hifazat aur Allah par tawakkul ka khoobsurat amal hai."
      ] },
      { heading:"Surah Baqarah Ki Aakhri Do Ayaat", ic:"📖", items:[
        "Raat mein Surah Baqarah ki aakhri do ayaat padhna bhi fazilat wala amal hai.",
        "Nabi ﷺ ne farmaya ke jo shakhs raat mein Surah Baqarah ki aakhri do ayaat padhe, woh uske liye kaafi hain."
      ] },
      { heading:"Tasbih-e-Fatima RA", ic:"🌿", items:[
        "Sone se pehle Tasbih-e-Fatima RA bhi padhein: SubhanAllah 33 martaba, Alhamdulillah 33 martaba, Allahu Akbar 34 martaba, kul 100 martaba.",
        "Ali RA se riwayat hai ke Fatima RA ne ghar ke kaam ki mushaqqat ki wajah se khadim ki darkhwast ki, toh Nabi ﷺ ne unhein sone ke waqt yeh zikr sikhaya aur farmaya ke yeh tumhare liye khadim se behtar hai.",
        "Sochiye: Nabi ﷺ ne apni beti ko sirf duniya ki aasani nahi, balki Allah ke zikr se milne wali roohani taqat ka raasta bataya. Is zikr ko raat ki routine ka hissa bana sakte hain."
      ] },
      { heading:"Sone Ki Dua", ic:"🤲", items:[
        "Sone ke waqt Nabi ﷺ yeh dua padhte: 'Bismika Allahumma amutu wa ahya'. Matlab: 'Ae Allah! Tere hi naam ke saath main marta hoon aur jeeta hoon.' Yeh dua Sahih al-Bukhari mein riwayat hai.",
        "Ek aur lambi masnoon dua bhi Nabi ﷺ ne sone se pehle padhne ki taleem di, jisme Allah ke saamne apne aap ko surrender karna aur apne tamam maamlaat Allah ke hawale karna shamil hai."
      ] },
      { heading:"Dahini Taraf Sona", ic:"🛌", items:[
        "Sone ke waqt dahini taraf letna Sunnah hai.",
        "Nabi ﷺ ne Al-Bara bin Azib RA ko sone ke liye wuzu karne, phir dahini taraf letne aur masnoon dua padhne ki hidayat di.",
        "Nabi ﷺ se sone ke waqt dahina haath gaal ke neeche rakhna bhi riwayat hua hai, aur pairon ko halka modna.",
        "Isliye sone ka ek khoobsurat Sunnah tareeqa ho sakta hai: wuzu, azkaar, dua, dahini taraf letna, aur Allah ke hawale hokar sona."
      ] },
      { heading:"Tahajjud Ki Niyyat Karke Sona", ic:"🌃", items:[
        "Raat ko sote waqt apne dil mein Tahajjud ke liye uthne ka irada rakhein. Alarm lagaiye, jaldi sone ki koshish kijiye aur Allah se dua kijiye: 'Ya Allah, mujhe raat mein apni ibadat ke liye utha dena.'",
        "Tahajjud ki niyyat karke sona ek khoobsurat intention hai, lekin sirf niyyat par rukna nahi, uthne ke liye practical sabab bhi ikhtiyar karein: alarm lagayein, phone ko bistar se thoda door rakhein, sone ka waqt be-wajah late na karein, aur agar mumkin ho toh kisi ghar wale ko bhi jagane ko keh sakte hain.",
        "Uthne par wuzu karein aur Tahajjud ada karein. Aur agar kisi raat aankh na khule, toh apne aap ko mayoos na karein, agli raat phir niyyat kijiye."
      ] },
      { heading:"Fajr Ke Liye Uthne Ka Irada", ic:"🕌", items:[
        "Raat ko sote waqt yeh niyyat bhi rakhein: 'Mujhe Fajr ke liye uthna hai.' Fajr ko miss karne ke baad subah ki routine banana maqsad nahi, Fajr ke liye raat se hi tayyari shuru hoti hai.",
        "Tarteeb kuch yun ho sakti hai: Tahajjud ki niyyat, Fajr ke liye alarm, wuzu, mumkin ho toh Tahajjud, phir Fajr ki namaz. Aur agar Tahajjud ke liye na uth sakein, toh Fajr ke liye zaroor uthna hai.",
        "Fajr farz hai, Tahajjud nafl ibadat hai, isliye raat ki planning mein dono ka darja alag samajhna zaroori hai."
      ] },
      { heading:"Sone Se Pehle Dil Ko Bhi Sulaayein", ic:"🧠", items:[
        "Kabhi jism bistar par hota hai, lekin zehan abhi bhi 'usne mujhe yeh kyun kaha', 'kal kya hoga', 'mera kaam complete nahi hua' jaisi baaton mein laga hota hai. Sone se pehle apne dil ko bhi release karna seekhein.",
        "Jo ho gaya, usko Allah ke hawale karein. Jo kal karna hai, uski planning kar lein. Jo aapke ikhtiyar mein nahi, us par tawakkul karein.",
        "Kisi ke liye baddua aur gusse ko lekar sone ki aadat se bachein, aur apne aap ko yaad dilayein: 'Jo mere bas mein tha, maine koshish ki, ab Allah ke hawale.'"
      ] },
      { heading:"Kisi Se Naraz Hain?", ic:"❤️", items:[
        "Har ikhtilaf ko raat bhar apne dil mein lekar chalna zaroori nahi. Agar kisi se galat-fehmi hui hai aur use suljhana mumkin ho, toh munasib waqt par baat kijiye.",
        "Lekin raat ko 'main kabhi maaf nahi karunga' ya 'kal usko sabak sikhaunga' jaise khayalat lekar sona aapke apne sukoon ko bhi khatam kar sakta hai.",
        "Maaf kar dena hamesha masle ko nazar-andaz karna nahi hota, kabhi iska matlab yeh hota hai ke aap apne dil ko be-zaroorat bojh se azaad kar rahe hain."
      ] },
      { heading:"Bhari Pet Se Sone Ki Aadat Se Bachein", ic:"🍽️", items:[
        "Sone se bilkul pehle bahut bhari khana neend aur hazme ko disturb kar sakta hai.",
        "Raat ko be-zaroorat zyada khana na khayein, aur sirf boriyat ki wajah se late-night snacking se bachein.",
        "Agar bhook lage toh zarurat ke mutabiq khayein, aur khane ke baad foran bistar par lete jaane ke bajaye apne jism ko settle hone ka waqt dein. (Yeh sehat aur neend se juda mashwara hai, koi khaas Sunnah hukm nahi.)"
      ] },
      { heading:"Safai Aur Zaati Hifazat", ic:"🧼", items:[
        "Sone se pehle jism saaf rakhein, aur zarurat ho toh wash karein.",
        "Munh aur daanton ki safai ka khayal rakhein, aur apne kapde aaramdeh aur saaf rakhein.",
        "Paseene ya badbu ke saath kisi shared sone ki jagah par na soyein, aur agar bistar kisi aur ke saath share karte hain toh unke aaram ka bhi khayal rakhein. Safai din ka hi nahi, raat ka bhi adab hai."
      ] },
      { heading:"Ghar Ki Hifazat Ka Khayal Rakhein", ic:"🔥", items:[
        "Sone se pehle ek jaldi check kar lein: gas stove band hai, diya ya candle bujh gayi hai, koi unsafe electrical cheez off hai, darwaza mehfooz hai, charging wires safe hain, bachche mehfooz jagah par hain, aur paani ke bartan dhake hue hain.",
        "Nabi ﷺ ne raat ko darwaze band karne, bartanon ko dhakne aur chiraghon/aag ko bujhane ki hidayat di. Yani ibadat ke saath practical hifazat bhi Deen ke adab ka hissa ban sakti hai."
      ] },
      { heading:"Neend Ko Sanjeedgi Se Lijiye", ic:"⏰", items:[
        "Neend ko 'waqt ki barbaadi' samajhna bhi sahi nahi, jism ko aaram chahiye. Agar aap roz raat gaye tak jaagte hain aur Fajr, kaam, taleem, warzish aur ghar ki zimmedariyan sab mutasir hone lagti hain, toh apni routine par dobara ghaur karein.",
        "Apni sone ki timing had tak consistent rakhein, raat ko be-zaroorat jagne ki aadat kam karein, aur subah ke zaroori kaam ko dekhte hue raat ki planning karein. Neend poori karna bhi apni jismani sehat ki zimmedari hai."
      ] },
      { heading:"Qailullah, Dopahar Ki Chhoti Neend", ic:"☀️", items:[
        "Qailullah dopahar ke waqt li jaane wali aaram ki neend ko kaha jata hai. Islam ki riwayat mein dopahar ke aaram ka zikr milta hai, aur yeh jism aur zehan ko dobara taazgi dene ka ek achha zariya ho sakta hai.",
        "Dopahar mein thodi der aaram karne se thakan kam ho sakti hai, zehni tawajjoh behtar ho sakti hai aur din ke baqi hisson ke liye taqat mil sakti hai.",
        "Sains mein bhi dopahar ki chhoti neend aur zehni sehat ke darmiyan achhe talluqat report hue hain. Ek paanch saal ki tadreeji tahqeeq mein 65 saal se zyada umar ke afraad mein 1 se 29 minute ki din ki neend zehni girawat ke kam khatre ke saath mutalliq payi gayi (PubMed tahqeeq).",
        "Isliye yeh kehna zyada durust hai ke takriban 30 minute ki chhoti dopahar ki neend zehni sehat ke liye faida-mand ho sakti hai, lekin tahqeeq abhi yeh sabit nahi karti ke '30 minute ki neend dementia ko door kar deti hai'. Tahqeeqat mein lambi ya zarurat se zyada neend ke saath dementia ya zehni kamzori ke mukhtalif talluqat bhi mile hain (PubMed tahqeeq).",
        "Qailullah ki koi ek muqarrarah muddat Qur'an ya Sahih Hadith mein tay nahi ki gayi. Amli taur par 30 se 60 minute ka aaram munasib ho sakta hai, lekin agar lambi neend se raat ki neend ya din ki routine mutasir ho, toh is ka waqt kam kar dena chahiye.",
        "Qailullah ka maqsad poora din sona nahi, balki thodi der aaram karke baqi din ko behtar tareeqe se guzarna hai."
      ] },
      { heading:"Sone Ka Matlab Kal Se Bhaagna Nahi", ic:"🌅", items:[
        "Sone se pehle apne aap se teen sawal pooch sakte hain: aaj maine Allah ko kitna yaad kiya? Aaj maine kisi insaan ko takleef toh nahi di? Kal mujhe kya behtar karna hai?",
        "Phir apne din ko Allah ke hawale karke so jaiye."
      ] },
      { heading:"Jaagte Hi", ic:"🌄", items:[
        "Nabi ﷺ jaagne par Allah ka shukr ada karne ki dua padhte: 'Alhamdu lillahil-lazi ahyana ba'da ma amatana wa ilaihin-nushur.' Matlab: 'Sab tareef Allah ke liye hai jisne humein maut jaisi neend ke baad zinda kiya, aur usi ki taraf laut kar jaana hai.' (Sahih al-Bukhari)",
        "Yani raat ka ikhtitaam bhi Allah ke zikr se, aur subah ki ibtida bhi Allah ke zikr se."
      ] },
      { heading:"Ek Khoobsurat Night Routine", ic:"🌌", items:[
        "Agar in sab ko ek simple tareeqe mein samete, toh raat kuch yun guzar sakti hai: apna kaam wrap-up karein, phone side par rakhein, safai/zaati hifazat ka khayal rakhein, wuzu karein, bistar check/jhaad lein, Ayat-ul-Kursi padhein, phir Ikhlas, Falaq aur Naas teen martaba, Surah Baqarah ki aakhri do ayaat aur Surah Al-Mulk, Tasbih-e-Fatima RA, masnoon sone ki dua, Tahajjud ki niyyat, Fajr ke liye alarm, aur phir dahini taraf let kar Allah ke hawale hokar so jaiye."
      ] },
    ],
    closing:"Neend bhi Allah ki nemat hai. Raat ko phone, tension aur be-ant scrolling ke hawale karne ke bajaye, apni raat ko sukoon, zikr, dua aur tawakkul ke saath khatam kijiye. Din duniya ke kaam mein guzra ho, toh raat Allah ke zikr se khatam kijiye. Ho sakta hai kal ki subah aapki zindagi ka ek aur behtar din ho." },
];
const HOWTO_GROUPS = [
  {"key":"maskan","rur":"Maskan (Home) Tab","en":"Home Tab"},
  {"key":"taareekh","rur":"Taareekh Tab","en":"Calendar Tab"},
  {"key":"marifat","rur":"Ma'rifat Tab","en":"Knowledge Tab"},
  {"key":"deegar","rur":"Deegar Tab","en":"More Tab"},
  {"key":"settings","rur":"Deegar: Settings","en":"More: Settings"}
];
const HOWTO_CARDS = [
  {"g":"maskan","ic":"🏡","t":{"rur":"Maskan (Home)","en":"Home"},"d":{"rur":"Yahan aaj ki namaz, sehri, iftar aur nawafil ke auqaat ek list mein dikhte hain. Chalta hua waqt highlight hota hai aur neeche 'Waqt Baaqi' ka bar dikhta hai. Upar ‹ › se doosre din dekh sakte hain; 'Aaj' dabane par wapas aaj par aa jayenge. Sheher ka naam dabane se Jagah ki setting khul jati hai.","en":"Shows today's prayer, sehri, iftar and nafl times in one list. The current time slot is highlighted with a 'Time Left' bar. Use ‹ › to view other days and tap 'Today' to come back. Tap the city name to change your location."}},
  {"g":"maskan","ic":"📍","t":{"rur":"Sheher (Jagah) Badalna","en":"Change City (Location)"},"d":{"rur":"Maskan par sheher ka naam dabayein, ya Deegar > Settings > Apna Shahar Chunein mein jayein. Wahan 'GPS Se Location Lein' dabayein ya list mein se sheher chunein. Namaz ke auqaat isi jagah ke hisaab se banenge.","en":"Tap the city name on Home, or go to More > Settings > Choose Your City. Use 'Get Location via GPS' or pick a city from the list. Prayer times are calculated for that place."}},
  {"g":"maskan","ic":"🎛️","t":{"rur":"Namaz Mode","en":"Namaz Mode"},"d":{"rur":"Upar 'Namaz Mode' switch on karein to sirf 5 Farz namazein bade size mein dikhti hain, nafil aur doosre auqaat chhup jate hain. Off karne par poori list wapas aa jati hai.","en":"Turn on 'Namaz Mode' at the top to show only the five Farz prayers in a larger layout; nafl and other times are hidden. Turn it off to see the full list again."}},
  {"g":"maskan","ic":"✅","t":{"rur":"Namaz Tracker (✓ ~ ⏳)","en":"Prayer Tracker (✓ ~ ⏳)"},"d":{"rur":"Har Farz namaz ke saath 3 nishan hain: ✓ (waqt par padh li), ~ (qaza padhi), ⏳ (baaki hai). Dobara dabane se nishan hat jata hai. Upar '5 Farz Namaz' wale bataon se paanchon ek saath mark ho jati hain.","en":"Each Farz prayer has three marks: ✓ (prayed on time), ~ (prayed late, qaza) and ⏳ (pending). Tap again to clear. The '5 Farz Prayers' buttons at the top mark all five at once."}},
  {"g":"maskan","ic":"🌜","t":{"rur":"Roza Mode","en":"Fasting (Roza)"},"d":{"rur":"Sehri wali line mein 'Roza' ka switch hai. On karne par us din ka roza ginti mein aata hai aur screen halke rang mein badal jati hai. Roze ka hisaab Safar-e-Taraqqi mein dikhta hai.","en":"The 'Roza' switch on the Sehri row marks the day as a fasting day and tints the screen softly. Your fasting count appears in Progress Journey."}},
  {"g":"maskan","ic":"🤲","t":{"rur":"Aaj ki Du'a / Aaj ki Hadees (Home)","en":"Today's Du'a / Hadees (Home)"},"d":{"rur":"Home par ek chhota patti-sa card aaj ki dua aur hadees ke tab dikhata hai. Kisi tab ya teer par dabayein to poora card khulta hai; band karne par patti wapas chhoti ho jati hai. Deegar tab ke 'Home par Aaj ki Du'a / Hadees' switch se ise band bhi kar sakte hain. Band karne ke baad bhi yeh Deegar > Rozana Hadaf mein milta hai.","en":"A slim strip on Home shows tabs for today's du'a and hadith. Tap a tab or the arrow to open the full card; closing it folds it back into the strip. You can turn it off with the 'Daily Du'a / Hadees on Home' switch in the More tab, and it stays available in More > Daily Goal."}},
  {"g":"taareekh","ic":"📅","t":{"rur":"Taareekh Tab","en":"Calendar Tab"},"d":{"rur":"Mahine ka calendar hai, Gregorian ya Hijri chun sakte hain. Har din ke neeche 5 chhote nishan us din ki 5 namazon ka haal batate hain. Kisi din par dabayein to us din ki tafseel khulti hai jahan aap namaz, roza aur azkar mark ya badal sakte hain. Purane din bhi theek kiye ja sakte hain.","en":"A monthly calendar in Gregorian or Hijri. The five small dots under each day show that day's Farz prayers. Tap a day to see and change its prayers, fasting and azkar. Past days can be corrected too."}},
  {"g":"marifat","ic":"🪔","t":{"rur":"Ma'rifat Tab kya hai?","en":"What is the Knowledge Tab?"},"d":{"rur":"Seekhne ka hissa: Qur'an (Normal aur Tajweed), duain, hadees, Allah ﷻ aur Rasool ﷺ ke naam, Qur'ani alfaaz, Aadaab, Khaas Shabd aur quiz. Upar aakhri padhi cheez ka 'Jaari rakhein' card aur sab mein dhoondhne ki jagah hai.","en":"The learning section: the Quran (Normal and Tajweed), du'as, hadith, the names of Allah ﷻ and the Prophet ﷺ, Quranic words, Aadaab, Special Words and the quiz. At the top are a 'Continue' card for what you last read and a search for everything."}},
  {"g":"marifat","ic":"📖","t":{"rur":"Qur'an Majeed (Mushaf)","en":"Quran (Mushaf)"},"d":{"rur":"Qur'an Majeed mein do Mushaf hain: Normal aur Tajweed (rangon ke saath). Dono 15 line ke hain aur page number ek jaise hain, isliye nishaan dono mein kaam karte hain. Right se left swipe karke page palatein; Paara, Surah ya Manzil se seedha jaayein; page number likh kar bhi ja sakte hain. Neeche ke buttons se nishaan lagayein, Note likhein, Rang (page ka rang), Andhera (night page), zoom, Share, aur Page palatne ki awaaz on/off karein. Upar 'Jaari rakhein' card aakhri padhi hui jagah se shuru karta hai. Poora Qur'an offline save kar sakte hain.","en":"The Quran has two Mushafs: Normal and Tajweed (colour-coded). Both are 15-line with the same page numbers, so bookmarks work in both. Swipe right to left to turn pages; jump by Para, Surah, Manzil or page number. The buttons below let you bookmark, write a Note, change the page Tint, use Night mode, zoom, Share, and switch the page-turn sound on or off. The 'Continue' card at the top resumes where you stopped. You can save the whole Quran for offline use."}},
  {"g":"marifat","ic":"📗","t":{"rur":"Tarjuma (Translation)","en":"Translation"},"d":{"rur":"Qur'an > Tarjuma mein surah-wise tarjuma. Upar Hinglish, Urdu, Hindi ya English chunein; A−/A+ se likhawat chhoti-badi karein. Paara, Surah ya Manzil ke button se seedha jaayein, 'Khojein' se dhoondhein. Kisi ayat par TAP karein to tilawat usi ayat se chalne lagti hai; kisi ayat par dabaye rakhein (press and hold) to us ayat par Note likh sakte hain. Nishaan, Rang, Andhera, Share (image) aur 'Mushaf' button (usi page ka Mushaf kholne ke liye) bhi hain.","en":"Qur'an > Translation shows the translation surah by surah. Pick Hinglish, Urdu, Hindi or English at the top and resize the text with A−/A+. Jump by Para, Surah or Manzil, or use Search. TAP any ayah to start the recitation from that ayah; PRESS AND HOLD an ayah to write a Note on it. There are also bookmark, Tint, Night, Share (as an image) and a Mushaf button that opens the same page in the Mushaf."},"s":1},
  {"g":"marifat","ic":"📚","t":{"rur":"Tafseer (alag se)","en":"Tafseer (separate)"},"d":{"rur":"Qur'an > Tafseer Tarjuma se alag hai: yeh 'Aasan Tarjuma Qur'an' (Mufti Muhammad Taqi Usmani) ki kitab hai, abhi sirf Urdu mein. Muqaddima aur surah ki list se ya 'Page par jaayein' se khulti hai; surah ka naam ya number likh kar dhoondhein. Page tasveer ki shakal mein hain: pehli baar kholne par internet chahiye, phir woh page offline bhi chalta hai. Right se left swipe karke page palatein; Note, Rang, Andhera, Bara karein aur Share yahan bhi hain.","en":"Qur'an > Tafseer is separate from the Translation: it is the book 'Aasan Tarjuma Quran' by Mufti Muhammad Taqi Usmani, currently in Urdu only. Open it from the Introduction and surah list, search a surah by name or number, or use 'Go to page'. Pages are images: the first open needs internet, and a page you have opened also works offline. Swipe right to left to turn pages; Note, Tint, Night, enlarge and Share are here too."},"s":1},
  {"g":"marifat","ic":"📊","t":{"rur":"Tilawat aur Khatm","en":"Reading and Khatm"},"d":{"rur":"Qur'an ka koi page 8 second khula rahe to padha hua ginta hai. Rozana target rakhein, kitab se padhe page khud jodein, aur Khatm ka hisaab aur andaazan mukammal hone ki tareekh dekhein.","en":"A Quran page counts as read after 8 seconds on it. Set a daily target, add pages read from a printed copy yourself, and see your Khatm progress and expected finish date."},"s":1},
  {"g":"marifat","ic":"🛑","t":{"rur":"Qur'an ki Alamaat aur Tajweed ke Qawaid","en":"Quran Signs and Tajweed Rules"},"d":{"rur":"Qur'an Majeed ki screen par 'Samajhne ke liye' mein: kahan rukna hai, kahan nahi (waqf ki alamaat), page ke nishaan, aur Tajweed ke 7 rangon ka aasaan matlab.","en":"Under 'Learn' on the Quran screen: where to stop and where not to (stopping signs), the page marks, and the 7 Tajweed colours explained simply."},"s":1},
  {"g":"marifat","ic":"🎧","t":{"rur":"Qur'an ki Tilawat (Audio)","en":"Quran Recitation (Audio)"},"d":{"rur":"Mushaf ya Tarjuma ke page par 'Tilawat sunein' dabayein. Aawaaz Mishary Alafasy ki hai, ek ek ayat, aur internet chahiye. Player mein: Arabi tilawat, 'Arabi + Urdu, ek ek ayat' ya 'Sirf Urdu tarjuma' chunein; 'Ayat' ya 'Poori surah' tak chalayein; 'Ayat dohraayein' (3 baar har ayat); rafter 0.5× se 2×; aur Sleep timer. Page palatne par tilawat usi page ke saath chalti hai. Mushaf ke aam pages par shuruaati ayat andaaze se milti hai (Paara aur Surah ke shuru wale pages par bilkul theek).","en":"Tap 'Listen' on a Mushaf or Translation page. The reciter is Mishary Alafasy, ayah by ayah, and it needs internet. In the player choose Arabic recitation, 'Arabic + Urdu, one ayah at a time' or 'Urdu translation only'; play one ayah or the whole surah; repeat each ayah 3 times; set the speed from 0.5× to 2×; and use the sleep timer. It follows the page as you turn it. On ordinary Mushaf pages the starting ayah is estimated; it is exact on the first page of a Para or Surah."},"s":1},
  {"g":"marifat","ic":"🤲","t":{"rur":"Du'a Padhiye","en":"Read Du'as"},"d":{"rur":"Roz marra ki duaein Arabic, transliteration aur matlab ke saath. Upar search se dhoondhein, Grid/List badlein.","en":"Everyday du'as with Arabic, transliteration and meaning, by category. Search at the top, switch between Grid and List, and mark each du'a as memorised."}},
  {"g":"marifat","ic":"📖","t":{"rur":"Hadees Dekhiye","en":"Browse Hadith"},"d":{"rur":"Mukhtasar ahadees hawale ke saath. Category chip se filter karein ya search karein.","en":"Short hadith with references, by category. Filter with the chips or search."}},
  {"g":"marifat","ic":"💚","t":{"rur":"Asma-ul-Husna","en":"Asma-ul-Husna"},"d":{"rur":"Allah ke 99 naam. Grid ya List se dekhein; kisi naam par dabayein to Arabic, tarjuma aur matlab dikhta hai. Upar ki bar se poori recitation chalayein (bar scroll karne par bhi upar rehti hai); chalte waqt maujooda naam highlight hota hai. Har naam ke saath ▶ se sirf wohi naam sunein. Rafter 0.5× se 2× tak badal sakte hain, aur naam ke page par '3 baar' se wohi naam teen dafa, beech mein thodi pause ke saath, sunein. Kisi naam ka card kholne par poori recitation ruk jati hai aur bar se wahin se dobara chal sakti hai; screen se wapas jaane par audio band ho jata hai. Yaad ho gaya / Yaad karna baaki hai mark karein, ☆ se pasandeeda mein rakhein, share icon se image bhejein. Upar ke rang wale button se is screen ka rang badlein.","en":"The 99 names of Allah ﷻ in Grid or List view. Tap a name for its Arabic, transliteration and meaning. Play the full recitation from the bar at the top (it stays pinned while you scroll) and the current name is highlighted as it plays. The ▶ next to each name plays just that name. Change the speed from 0.5× to 2×, and on a name's page use '3 times' to hear it three times with a short pause between. Opening a name pauses the full recitation, and you can resume from the bar; leaving the screen stops the audio. Mark names as memorised or still to memorise, save a favourite with ☆, share as an image, and change the screen's colour with the colour button at the top."}},
  {"g":"marifat","ic":"🌙","t":{"rur":"Asma-ul-Nabi","en":"Asma-ul-Nabi"},"d":{"rur":"Nabi ﷺ ke 99 mubarak naam, recording ki tarteeb ke mutabiq. Asma-ul-Husna ki tarah yahan bhi poori recitation, har naam ke saath ▶, rafter (0.5× se 2×), '3 baar' dohrana aur naam yaad karne ke nishan hain. Naamon ka matlab Hinglish aur English mein diya gaya hai.","en":"The 99 blessed names of the Prophet ﷺ, in the order of the recording. Like Asma-ul-Husna it has the full recitation, a ▶ beside each name, speed control (0.5× to 2×), '3 times' repeat and memorise marks. Meanings are given in Hinglish and English."}},
  {"g":"marifat","ic":"📗","t":{"rur":"Qur’ani Alfaaz Aur Ma’ani","en":"Quranic Words"},"d":{"rur":"Qur’an mein sab se zyada istemal hone wale 125 alfaaz, unka matlab, category, Qur’an mein kitni martaba aaye aur ek misaal. Grid ya List view aur search available hai.","en":"The 125 most-used words in the Quran, with meaning, category, how often each appears and an example. Grid or List view, sorting by count, and search."}},
  {"g":"marifat","ic":"📚","t":{"rur":"Khaas Shabd","en":"Special Words"},"d":{"rur":"Islami alfaaz category-wise. 'Sabhi Naam' se saare alfaaz dekhein, kisi category par dabayein ya search karein. Har lafz par Arabic, matlab aur misaal milti hai.","en":"Islamic vocabulary by category. 'All Words' shows everything; tap a category or search. Each word has Arabic, meaning and an example sentence."}},
  {"g":"marifat","ic":"🔤","t":{"rur":"Aaj Ka Lafz","en":"Word of the Day"},"d":{"rur":"Roz ek naya lafz, alag alag category se. 'Yaad ho gaya' ya 'Yaad karna baaki hai' mark karein; card hara ya peela ho jata hai. Neeche dono list dikhti hain aur 'Baaki Lafz ka Quiz' se dohrai kar sakte hain.","en":"One new word a day. Mark it 'Memorised' or 'Still to memorise'; the card turns green or yellow. Both lists appear below, with a quiz on the words you are still learning."}},
  {"g":"marifat","ic":"💡","t":{"rur":"Ghalat Fehmi Ka Izala","en":"Myth Busters"},"d":{"rur":"Aam ghalat fehmiyon ka jawab. 'Sab Padhein' mein poori list jawab ke saath hai; 'Quiz' mein ek ek sawal khel sakte hain.","en":"Answers to common misconceptions. 'Read all' shows the full list with answers; 'Quiz' asks one question at a time."}},
  {"g":"marifat","ic":"🧠","t":{"rur":"Quiz Kheliye","en":"Play Quiz"},"d":{"rur":"Category chuniye, 5 ya 10 sawal khelein. Galat jawabon ka jaiza aur sirf galat sawal dobara khelne ka option result par milta hai. Asma-ul-Husna aur Nabi ﷺ ke naamon ke sawal bhi hain.","en":"Pick a category and play 5 or 10 questions. On the result screen review your wrong answers or replay only those."}},
  {"g":"marifat","ic":"🎨","t":{"rur":"Rang (Colour): padhne ki screens","en":"Colour for the reading screens"},"d":{"rur":"Qur'an, Tarjuma, Tafseer aur Du'a, Hadees, Naam, Alfaaz waghaira ki screens mein upar rang ka button hai. Alag rang chunein ya 'Theme ke mutabiq' chunein taake app ke theme ka rang hi lag jaye.","en":"The Quran, Translation and Tafseer screens, and the Du'a, Hadith, Names and Words screens, have a colour button at the top. Pick a colour, or 'Match theme' to follow the app's theme colour."},"s":1},
  {"g":"deegar","ic":"🎯","t":{"rur":"Rozana Hadaf","en":"Daily Goal"},"d":{"rur":"Roz teen chhote kaam: ek hamesha paanchon Farz namaz mark karna, aur do har din badalte hain (dua, lafz, quiz, naam, Qur'an tilawat waghaira). Kaam par dabayein to seedha wahan pahunchenge. Aaj ki hadaf din mein teen dafa badal sakte hain. 'Aaj ki Du'a aur Hadees' par dabayein to aaj ki dua aur hadees khulti hain; wahan Yaad ho gaya / Yaad karna baaki hai mark kar sakte hain. Home ka card band kar dein tab bhi yahan se dua-hadees padh sakte hain. Poora card Deegar tab mein hai.","en":"Three small tasks each day: one is always marking all five Farz prayers, and two change daily (a du'a, a word, a quiz, a name, Quran reading and so on). Tap a task to go straight to it. You can change today's goal up to three times. 'Today's Du'a & Hadees' opens today's du'a and hadith, where you can mark each as memorised or still to memorise. If you close the Home card you can still catch up here. The full card is in the More tab."}},
  {"g":"deegar","ic":"📊","t":{"rur":"Safar-e-Taraqqi","en":"Progress Journey"},"d":{"rur":"Aap ka poora jaiza: Farz Namaz, Azkar, Roza, Quiz aur Lafz ke card, aur sabse neeche Paabandi (streaks). Upar Maahana/Saalana aur Gregorian/Hijri se muddat badlein.","en":"Your full review: Farz prayers, azkar, fasting, quiz and words, plus the last 7 days of your daily goal, with streaks at the bottom. Switch between monthly and yearly, Gregorian and Hijri."}},
  {"g": "deegar", "ic": "📿", "t": {"rur": "Tasbeeh Counter", "en": "Tasbeeh Counter"}, "d": {"rur": "Moti ya gol button par tap karke ginti karein. 📖 se dua ya zikr chunein, upar A− / A+ se likhawat chhoti-badi karein, aur neeche Undo, Reset aur Target se ginti sambhalein. Target poora hone par khaas awaaz aur halka kampan hota hai.", "en": "Tap the beads or the round button to count. Pick a dua or zikr with 📖, change the text size with A− / A+, and use Undo, Reset and Target below. A special sound and a light vibration tell you when the target is done."}},
  {"g": "deegar", "ic": "📋", "s": 1, "t": {"rur": "Zikr profiles aur Aaj ka zikr", "en": "Zikr profiles and Today's zikr"}, "d": {"rur": "Profile dua ya zikr ki ek list hoti hai (Subah, Shaam, Anbiya, Istighfar ya aapki banayi hui). Upar '📋 Aaj ka zikr' dabane par aaj ka set khulta hai aur ek ek karke poora hota hai. Settings mein chun sakte hain ke kaun sa profile aaj ka ho. Har profile mein din (Peer se Itwar) aur Subah / Dopahar ke baad chun sakte hain, taake us din woh apne aap 'Aaj ka zikr' ban jaye. Profile ke andar ⠿ pakad kar dua ka order badal sakte hain.", "en": "A profile is a list of duas or zikr (Morning, Evening, Anbiya, Istighfar or your own). '📋 Today's zikr' opens today's set and you finish it one by one. In Settings you can pick which profile is today's. For each profile you can choose weekdays (Mon to Sun) and morning or afternoon, so it becomes Today's zikr automatically. Inside a profile, hold ⠿ and drag to change the order."}},
  {"g": "deegar", "ic": "🎉", "s": 1, "t": {"rur": "Set poora hone par", "en": "When a set is complete"}, "d": {"rur": "Poora set khatam hone par 'Mashallah' card aata hai, jis mein aaj ki kul ginti aur lagatar din (streak) dikhte hain.", "en": "When the whole set is done, a 'Mashallah' card shows today's total and your day streak."}},
  {"g": "deegar", "ic": "📊", "s": 1, "t": {"rur": "Hisaab", "en": "Stats"}, "d": {"rur": "Counter ke 📊 mein Aaj, Hafta aur Mahina ke tabs hain: ginti ka chart, sab se zyada padhi gayi duaein, kitne din set poora hua, aur lagatar din.", "en": "The 📊 on the counter has Today, Week and Month tabs: a chart of your counts, the most-read duas, days the set was completed, and your streak."}},
  {"g": "deegar", "ic": "🌅", "s": 1, "t": {"rur": "Manzar aur Live aasman", "en": "Scenes and Live sky"}, "d": {"rur": "Settings mein manzar, roshni (andhera se roshan), mausam (barish, baraf, hawa) aur raftaar chun sakte hain. 'Live aasman' mein subah se raat tak ka din 2, 5 ya 10 minute mein chalta hai, aur ⏸ se ruk jata hai. 'Waqti' mein aasman aapke shehar ke asli namaz ke waqton ke hisaab se chalta hai. Chaand ka phase Islami tareekh ke mutabiq hota hai.", "en": "In Settings choose the scene, brightness (dark to light), weather (rain, snow, wind) and speed. 'Live sky' runs a full day-and-night in 2, 5 or 10 minutes and can be paused with ⏸. 'Real time' follows your city's actual prayer times. The moon shows the phase of the Islamic date."}},
  {"g": "deegar", "ic": "🔔", "s": 1, "t": {"rur": "Awaaz, kampan aur options", "en": "Sound, vibration and options"}, "d": {"rur": "Settings mein awaaz ki kisam aur volume, target poora hone ki chime, khaas moti ka nishaan, kampan, 'target par ruk jayen', 'screen on rakhein' (pehle se band) aur Arabic, talaffuz, tarjuma dikhana chun sakte hain. 'Seedha counter' se profile ke bina simple counter par aa sakte hain.", "en": "In Settings choose the sound type and volume, the completion chime, a marker bead, vibration, 'stop at target', 'keep screen on' (off by default) and whether to show Arabic, transliteration and meaning. 'Plain counter' takes you back to the simple counter without a profile."}},
  {"g": "deegar", "ic": "🤲", "s": 1, "t": {"rur": "Dua ke saath padhein", "en": "Read with the Tasbeeh"}, "d": {"rur": "Du'a section mein kisi bhi dua par 'Tasbeeh ke saath padhein' dabane se woh dua Arabic aur tarjuma ke saath counter par khulti hai. Wahan Istighfar ki duaon ke liye fawaid ka card list ke aakhir mein hai.", "en": "On any dua in the Du'a section, tap 'Read with Tasbeeh' to open it on the counter with its Arabic and meaning. The Istighfar list also ends with a card on the benefits and best times of istighfar."}},
  {"g":"deegar","ic":"🔊","t":{"rur":"Azaan","en":"Azaan"},"d":{"rur":"Deegar > Azaan mein Azaan ke alfaaz, talaffuz aur maana, aur duniya bhar ki masjidon ki Azaan.","en":"More > Azaan has the words of the Azaan with pronunciation and meaning, and recordings from mosques around the world."}},
  {"g":"deegar","ic":"🧎","t":{"rur":"Qaza Namaz Tracker","en":"Qaza Prayer Tracker"},"d":{"rur":"Chhoti hui namazon ka hisaab. Har namaz ki ginti likhein, ＋ se ek jodein, '✓ Padh Li' se ek kam karein. 'Purani Qaza Jodein' mein saal/mahine/din likh kar sab namazon mein ek saath jod sakte hain. Reset ke buttons dobara dabane par hi chalte hain.","en":"Keeps count of missed prayers. Enter each prayer's count, use ＋ to add one and '✓ Prayed' to take one off when you make it up. 'Add Past Qaza' adds years, months or days to all prayers at once. Reset buttons need a second tap."}},
  {"g":"deegar","ic":"🔁","t":{"rur":"Tareekh Badlein (Hijri)","en":"Date Converter (Hijri)"},"d":{"rur":"Gregorian tareekh ko Hijri mein aur Hijri ko Gregorian mein badalta hai.","en":"Converts Gregorian dates to Hijri and back."}},
  {"g":"deegar","ic":"🔭","t":{"rur":"Islami Mahine","en":"Islamic Months"},"d":{"rur":"Hijri saal ke 12 mahine. Kisi mahine par dabayein to us ki fazilat, ahem waqiat aur (agar hai to) haram mahine hone ki maloomat milti hai.","en":"The 12 months of the Hijri year. Tap a month for its virtues, important events and whether it is a sacred month."}},
  {"g":"deegar","ic":"📅","t":{"rur":"Mahine ka Timetable","en":"Monthly Timetable"},"d":{"rur":"Poore mahine ke namaz ke auqaat ek jadwal mein. Ramzan mein sehri aur iftar bhi dikhte hain.","en":"The prayer times for the whole month in one table. In Ramadan it also shows Suhoor and Iftar."}},
  {"g":"deegar","ic":"🕌","t":{"rur":"Qareebi Masjid","en":"Nearby Masjids"},"d":{"rur":"Aap ki jagah ke qareeb ki masjidein dhoondhta hai. Kisi masjid par dabayein to us ki tafseel aur rasta milta hai.","en":"Finds masjids near you. Tap one for its details and directions."}},
  {"g":"deegar","ic":"🎉","t":{"rur":"Khaas Din","en":"Special Days"},"d":{"rur":"Aane wale ahem Islami din: Eid, Ramzan ke din, Shab-e-Qadr, ghazwat aur mazeed. Tabs se filter karein. ⚠️ wale din ki tareekh mein ikhtilaf ya ta'qreeb hai. Har card ka share icon image bana deta hai.","en":"Upcoming important Islamic days: Eid, Ramadan days, Laylat-ul-Qadr, expeditions and more. Filter with the tabs. Days marked ⚠️ have disputed or approximate dates. Each card's share icon makes an image."}},
  {"g":"deegar","ic":"☪️","t":{"rur":"Ramzan","en":"Ramadan"},"d":{"rur":"Ramzan ka poora calendar (Grid ya List), Hijri aur Gregorian tareekh, sehri khatm aur iftar ke waqt, teen ashre aur Shab-e-Qadr ki raatein. Ramzan ke ilawa yeh sirf jhalak hai; Ramzan mein yahan roza aur namaz mark hoti hai.","en":"The full Ramadan calendar (Grid or List) with Hijri and Gregorian dates, sehri and iftar times, the three ashras and the nights of Laylat-ul-Qadr. Outside Ramadan it is a preview; during Ramadan you can mark fasting and prayers here."}},
  {"g":"deegar","ic":"⭐","t":{"rur":"Mere Pasandeeda","en":"My Favourites"},"d":{"rur":"Kisi bhi dua, hadees, naam ya lafz par ☆ dabayein, woh yahan jama ho jata hai.","en":"Tap ☆ on any du'a, hadith, name or word and it is collected here."}},
  {"g":"deegar","ic":"🎨","t":{"rur":"Theme aur Rang","en":"Theme and Colour"},"d":{"rur":"Deegar tab mein Light, Dark, Auto ya Waqti theme chunein (Waqti har namaz ke waqt ke mutabiq rang badalta hai). Neeche Rang (Colour) se app ka rang badlein, 'Zyada contrast' ya 'Kam animation' on karein, aur chunein ke app kholne par pehle kaun sa tab dikhe.","en":"In the More tab choose Light, Dark, Auto or Waqti (Waqti changes colours with each prayer time). Below it pick the app Colour, switch on 'High contrast' or 'Calmer motion', and choose which tab the app opens on."}},
  {"g":"deegar","ic":"⚙️","t":{"rur":"Settings","en":"Settings"},"d":{"rur":"Deegar tab ke 'Mazeed' hisse mein Settings, App Install aur Raabta hain. Settings ke andar ki cheezein neeche 'Deegar: Settings' mein usi tarteeb se hain, jis tarteeb se woh Settings mein dikhti hain.","en":"The 'More' section of the More tab holds Settings, Install the App and Contact. What is inside Settings is listed below under 'More: Settings', in the same order as on the Settings screen."}},
  {"g":"deegar","ic":"📲","t":{"rur":"App Install Karein","en":"Install the App"},"d":{"rur":"Waqt24 ko home screen par rakhein: Android par 'Install' dabayein, iPhone par Safari mein Share > Add to Home Screen. Install ke baad internet ke baghair bhi chalti hai.","en":"Add Waqt24 to your home screen: on Android press 'Install', on iPhone use Safari Share > Add to Home Screen. Once installed it also works offline."}},
  {"g":"deegar","ic":"📮","t":{"rur":"Raabta","en":"Contact"},"d":{"rur":"Sujhaav, madad ya masla batane ke liye Raabta mein diye gaye email par likhein: contact.waqt24@gmail.com. Wahan se seedha email app khul jata hai.","en":"For suggestions, help or to report a problem, write to contact.waqt24@gmail.com from More > Contact. It opens your email app directly."}},
  {"g":"settings","ic":"📍","t":{"rur":"Apna Shahar Chunein","en":"Choose Your City"},"d":{"rur":"Settings > Apna Shahar Chunein mein 'GPS Se Location Lein' dabayein ya list mein se sheher chunein. Namaz ke auqaat isi jagah ke hisaab se banenge.","en":"In Settings > Choose Your City use 'Get Location via GPS' or pick a city from the list. Prayer times are calculated for that place."},"s":1},
  {"g":"settings","ic":"🧭","t":{"rur":"Qibla ka Rukh","en":"Qibla Direction"},"d":{"rur":"Aap ki jagah se Ka'ba ki simt dikhata hai. Phone ka compass on karein aur phone ko sapaat rakhein.","en":"Shows the direction of the Ka'bah from your location. Turn on the phone's compass and hold the phone flat. It is in More > Settings."},"s":1},
  {"g":"settings","ic":"🕒","t":{"rur":"Waqt ka Andaaz aur Text ka Size","en":"Time Format and Text Size"},"d":{"rur":"Waqt ka Andaaz mein 12 ya 24 ghante ka format chunein. Text ka Size mein chhota se Sabse Bara tak chunein; Arabic ka size alag se bhi badal sakte hain.","en":"Time Format switches between 12 and 24 hours. Text Size goes from small to largest, and the Arabic size can be set separately."},"s":1},
  {"g":"settings","ic":"🃏","t":{"rur":"Home Card","en":"Home Card"},"d":{"rur":"Maskan ke upar ka card (abhi ka waqt aur agla waqt): Poora, Patli patti ya Band. Card par ✕ dabane ya swipe karne se woh ek darje chhota hota hai; Settings > Home Card se wapas la sakte hain.","en":"The card at the top of Home (the current and next prayer): Full, Slim strip or Off. Tapping ✕ or swiping it steps it down one level; bring it back from Settings > Home Card."},"s":1},
  {"g":"settings","ic":"📳","t":{"rur":"Vibration aur Awaaz","en":"Vibration and Sound"},"d":{"rur":"Tap par halki vibration aur awaaz ko alag alag on ya off kar sakte hain.","en":"Turn the light vibration and the tap sounds on or off separately."},"s":1},
  {"g":"settings","ic":"🌐","t":{"rur":"Zubaan (Language)","en":"Language"},"d":{"rur":"Settings > Zubaan mein 'Hinglish / Roman Urdu' ya 'English' chunein. English mein menu, buttons aur saari maloomat English mein badal jaati hai.","en":"Choose 'Hinglish / Roman Urdu' or 'English' in Settings > Language. In English, menus, buttons and all content switch to English."},"s":1},
  {"g":"settings","ic":"🔔","t":{"rur":"Yaad-dahaniyan","en":"Reminders"},"d":{"rur":"Yaad-dahaniyan on karke Farz, Nafil, Sehri/Iftar aur Aaj Ka Lafz/Hadees ke notification le sakte hain (app khuli ya background mein ho tab).","en":"Turn on reminders for Farz, Nafl, Sehri/Iftar and the daily word or hadith (while the app is open or in the background)."},"s":1},
  {"g":"settings","ic":"🔊","t":{"rur":"Azaan (Settings)","en":"Azaan (Settings)"},"d":{"rur":"Settings > Azaan se har namaz ke liye alag Azaan chunein; app khuli ho to namaz ke waqt chalegi.","en":"In Settings > Azaan choose a different Azaan for each prayer; it plays at prayer time while the app is open."},"s":1},
  {"g":"settings","ic":"🌙","t":{"rur":"Nafil Namaz Mark Karna","en":"Marking Nafl Prayers"},"d":{"rur":"Settings > Nafil Namaz Mark Karein ko On karein to Ishraq, Chaast, Awwabin, Tahajjud aur Du'a Qubooliyat ke saath ✓ aur ✗ aa jaate hain. Taareekh mein yeh Farz ke gol nishaan ke neeche chhote ▲ se dikhti hain.","en":"Turn on Settings > Mark Nafl Prayers to get ✓ and ✗ for Ishraq, Chaast, Awwabin, Tahajjud and Du'a Qubooliyat. In the Calendar they appear as small ▲ marks under the round Farz dots."},"s":1},
  {"g":"settings","ic":"🧮","t":{"rur":"Namaz ka Hisaab","en":"Prayer Calculation"},"d":{"rur":"Settings > Namaz ka Hisaab mein Asr (Hanafi ya Shafi'i) chunein aur Hijri tareekh ek do din aage peeche karein.","en":"In Settings > Prayer Calculation choose the Asr method (Hanafi or Shafi'i) and adjust the Hijri date by a day or two."},"s":1},
  {"g":"settings","ic":"🕌","t":{"rur":"Jamaat ka Waqt (Iqamah)","en":"Jamaat Times (Iqamah)"},"d":{"rur":"Settings > Jamaat ka Waqt mein apni masjid ki jamaat ka waqt likhein; Maskan par dikhega aur pehle yaad-dahani aa sakti hai.","en":"In Settings > Jamaat Times enter your masjid's jamaat times; they show on Home, with an optional reminder before."},"s":1},
  {"g":"settings","ic":"💾","t":{"rur":"Data Backup (Settings mein)","en":"Data Backup (in Settings)"},"d":{"rur":"Aapka data sirf isi phone mein hai. 'Backup Banayein' se file save karein aur zaroorat par 'Restore' se wapas laayein. Mahine mein ek baar backup ki yaad-dahani aati hai.","en":"Your data is saved only on this phone. 'Create Backup' saves a file and 'Restore Backup' brings it back. A reminder appears every month, or sooner when a lot has changed."},"s":1}
];
